local config = {
  ui_story_5043_50430101_1_dialog_content = "<color=#e8d9bb>Balai Kehakiman, Taman Lumopolis</color>",
  ui_story_5043_50430101_2_dialog_content = "Yang Mulia, bukan itu masalahnya!",
  ui_story_5043_50430101_3_dialog_content = "Aku bersumpah demi Dewa Cahaya, aku tidak berbohong padanya dalam masalah hati.",
  ui_story_5043_50430101_4_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50430101_5_dialog_content = "Pesan di pengadilan! Tergugat tidak akan mengganggu penggugat.",
  ui_story_5043_50430101_6_dialog_content = "Silakan lanjutkan, Hakim Leyn.",
  ui_story_5043_50430101_7_dialog_content = "Nona, Anda baru saja menyatakan bahwa penggugat gagal menjalankan tugasnya sebagai tunangan Anda selama masa pertunangan Anda. Apakah itu benar?",
  ui_story_5043_50430101_8_dialog_content = "Dia!",
  ui_story_5043_50430101_9_dialog_content = "Anda dapat membuat pernyataan akhir sebelum pengadilan memulai pertimbangannya.",
  ui_story_5043_50430101_10_dialog_content = "Mooncrown Day bulan lalu adalah peringatan tujuh bulan pertunangan kami.",
  ui_story_5043_50430101_11_dialog_content = "Tapi yang tidak berguna itu bahkan tidak peduli!",
  ui_story_5043_50430101_12_dialog_content = "Bisa aja. Anda tidak dapat mengharapkan saya untuk merayakan pertunangan kami setiap bulan!",
  ui_story_5043_50430101_13_dialog_content = "Saya mungkin tidak keberatan. Tapi Anda berhasil membeli hadiah yang berbeda untuk beberapa orang lainnya!",
  ui_story_5043_50430101_14_dialog_content = "Tunggu sebentar. Sudah kujelaskan, itu untuk hubungan bisnis keluargaku—",
  ui_story_5043_50430101_15_dialog_content = "T-Tunggu! Jangan mulai berdebat, sekarang...",
  ui_story_5043_50430101_16_dialog_content = "<size=30>Tina, Anda seorang hakim sekarang. Bertindak seperti itu!</size>",
  ui_story_5043_50430101_17_dialog_content = "<size=30>Oh ya, itu benar! Saya. Oke, lihat ini. Ahem...</size>",
  ui_story_5043_50430101_18_dialog_content = "<size=45>Pesan, pesan!</size>",
  ui_story_5043_50430101_19_dialog_content = "<color=#e8d9bb>*Kerumunan bergumam*</color>",
  ui_story_5043_50430101_20_dialog_content = "(Yang ingin saya ketahui adalah mengapa saya duduk di sini mendengarkan tiff kekasih...)",
  ui_story_5043_50430101_21_dialog_content = "Menjadi tidak sabar, PlayerName? Kamu mulai terlihat bosan.",
  ui_story_5043_50430101_22_dialog_content = "Apa, saya? Tidak sama sekali... Oh, oke, kamu benar seperti biasa, Carleen.",
  ui_story_5043_50430101_23_dialog_content = "Sejujurnya, saya merasakan hal yang sama.",
  ui_story_5043_50430101_24_dialog_content = "Tapi tidak sepertimu, aku tidak bisa menunjukkannya. Lagipula-",
  ui_story_5043_50430101_25_dialog_content = "Aku tahu. Sampai taraf tertentu, itu akan berdampak buruk pada Tuan Kota di sana.",
  ui_story_5043_50430101_26_dialog_content = "...",
  ui_story_5043_50430101_27_dialog_content = "Sejauh ini, dia belum mengatakan apa-apa.",
  ui_story_5043_50430101_28_dialog_content = "Maaf. Awalnya saya bermaksud agar Anda datang ke Lumopolis Gardens untuk memberikan laporan tentang petualangan Anda di Longzhou.",
  ui_story_5043_50430101_29_dialog_content = "Tapi sepertinya Tuan Kota tidak akan bisa menyisihkan waktu.",
  ui_story_5043_50430101_30_dialog_content = "Tidak masalah. Bukannya aku punya sesuatu yang mendesak untuk dilakukan.",
  ui_story_5043_50430101_31_dialog_content = "<size=30>Dan sejujurnya, saya tidak benar-benar ingin kembali ke salah satu ruang konferensi yang khidmat itu...</size>",
  ui_story_5043_50430101_32_dialog_content = "Maaf apa?",
  ui_story_5043_50430101_33_dialog_content = "Bukan apa-apa!",
  ui_story_5043_50430101_34_dialog_content = "(Sekarang saya memikirkannya, saya belum pernah ke sini sejak itu <color=#FFB400>kejadian</color>...)",
  ui_story_5043_50430101_35_dialog_content = "(Irridon sedang duduk di mana dia sekarang, membacakan putusan Balai Kehakiman pada Carleen.)",
  ui_story_5043_50430101_36_dialog_content = "(Dan Carleen... yah, dia banyak berubah sejak saat itu.)",
  ui_story_5043_50430101_37_dialog_content = "PlayerName, apakah kamu sedang melamun?",
  ui_story_5043_50430101_38_dialog_content = "Uhm, yah... aku hanya berpikir...",
  ui_story_5043_50430101_39_dialog_content = "Saya baru saja memikirkan tentang efek Mooncrown Day terhadap Lumopolis!",
  ui_story_5043_50430101_40_dialog_content = "Ya, hal semacam ini biasa terjadi di sepanjang tahun ini.",
  ui_story_5043_50430101_41_dialog_content = "Saat pria dan wanita muda menikmati suasana Mooncrown, beberapa memulai romansa baru, dan terkadang retakan terbentuk dalam hubungan yang ada.",
  ui_story_5043_50430101_42_dialog_content = "Lalu, ada bangsawan dekaden yang memiliki kecenderungan untuk mencoba dan memikirkan cara agar hiburan tersebut bertahan selama mungkin.",
  ui_story_5043_50430101_43_dialog_content = "Akibatnya, Balai Kehakiman berakhir dengan setumpuk perselisihan hubungan yang harus ditangani.",
  ui_story_5043_50430101_44_dialog_content = "Tuan Kota duduk untuk mendengarkan lebih sering dari biasanya, untuk mencegah kemungkinan situasi yang belum pernah terjadi sebelumnya terjadi atau lepas kendali.",
  ui_story_5043_50430101_45_dialog_content = "Bagaimanapun, saya lebih menikmati duduk di sini di antara hadirin daripada duduk di kursi terdakwa.",
  ui_story_5043_50430101_46_dialog_content = "Carleen…",
  ui_story_5043_50430101_47_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk!</color>",
  ui_story_5043_50430101_48_dialog_content = "<size=45>Memesan!</size>",
  ui_story_5043_50430101_49_dialog_content = "Secara keseluruhan, itu kejam dan tak termaafkan!",
  ui_story_5043_50430101_50_dialog_content = "Karena itu saya meminta pengadilan untuk mengakhiri pertunangan kami!",
  ui_story_5043_50430101_51_dialog_content = "Heheh. Penggugat yang terhormat, saya tentu mengerti dari mana Anda berasal.",
  ui_story_5043_50430101_52_dialog_content = "Seperti yang saya pahami, ini adalah pengaturan lama antara keluarga Anda. Dan Anda dan terdakwa adalah kekasih masa kecil.",
  ui_story_5043_50430101_53_dialog_content = "Itu masuk akal. Sulit membayangkan pria seperti terdakwa memenangkan hati wanita cantik seperti Anda tanpa keuntungan seperti itu.",
  ui_story_5043_50430101_54_dialog_content = "Kamu benar. Kami memang tumbuh bersama, itulah sebabnya saya mengenalnya lebih baik daripada siapa pun.",
  ui_story_5043_50430101_55_dialog_content = "Betapa iri. Mengapa, saya hampir cemburu pada terdakwa.",
  ui_story_5043_50430101_56_dialog_content = "(Apa?! Hakim ini agak menyeramkan!)",
  ui_story_5043_50430101_57_dialog_content = "J-Judge Schwab...",
  ui_story_5043_50430101_58_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50430101_59_dialog_content = "Hakim Schwab, tolong pertahankan profesionalisme Anda.",
  ui_story_5043_50430101_60_dialog_content = "Lagi pula, saya dan Hakim Ketua pun tidak tahu karakter terdakwa.",
  ui_story_5043_50430101_61_dialog_content = "Yang dapat kami pastikan adalah bahwa Anda harus mengambil keputusan setelah banyak pertimbangan berdasarkan berapa tahun Anda mengenalnya.",
  ui_story_5043_50430101_62_dialog_content = "eh...?",
  ui_story_5043_50430101_63_dialog_content = "(Heh. Dia jatuh cinta.)",
  ui_story_5043_50430101_64_dialog_content = "Eh, aku...",
  ui_story_5043_50430101_65_dialog_content = "Terdakwa, apakah Anda memiliki sesuatu untuk dikatakan sebelum Ketua Hakim Irridon menyampaikan putusan?",
  ui_story_5043_50430101_66_dialog_content = "<size=45>Sayangku! Anda selalu menjadi satu-satunya untuk saya!</size>",
  ui_story_5043_50430101_67_dialog_content = "B-Bagaimana Anda bisa mengatakan hal-hal seperti itu di sini ...",
  ui_story_5043_50430101_68_dialog_content = "Sangat baik. Dan selanjutnya-",
  ui_story_5043_50430101_69_dialog_content = "<size=45>Tunggu!</size>",
  ui_story_5043_50430101_70_dialog_content = "Saya minta maaf. Tapi saya telah mempertimbangkan kembali.",
  ui_story_5043_50430101_71_dialog_content = "saya ingin <color=#FFB400>menarik</color> kasus saya.",
  ui_story_5043_50430101_72_dialog_content = "(Apa, begitu saja?)",
  ui_story_5043_50430101_73_dialog_content = "Saya benar-benar minta maaf. Saya gagal mempertimbangkan tindakan saya sepenuhnya. Kita seharusnya menyelesaikan sendiri kesalahpahaman kita.",
  ui_story_5043_50430101_74_dialog_content = "Tidak. Ini salahku karena tidak lebih mencintai. Akulah yang bersalah padamu.",
  ui_story_5043_50430101_75_dialog_content = "Permintaan ditolak. Proses pengadilan harus dihormati. Ada formalitas yang harus diikuti baik saat mengajukan kasus maupun saat menariknya.",
  ui_story_5043_50430101_76_dialog_content = "Tetapi ada cara yang lebih mudah untuk menangani ini.",
  ui_story_5043_50430101_77_dialog_content = "Saya menemukan terdakwa—",
  ui_story_5043_50430101_78_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50430101_79_dialog_content = "-tidak bersalah!",
  ui_story_5043_50430101_80_dialog_content = "Tersayang!",
  ui_story_5043_50430101_81_dialog_content = "Rasa manis! Ayo, mari kita minum teh sore ...",
  ui_story_5043_50430101_82_dialog_content = "Kasus ditutup. Pengadilan ditunda.",
  ui_story_5043_50430101_83_dialog_content = "Tuhan Schwab, harap tunggu!",
  ui_story_5043_50430101_84_dialog_content = "Selamat atas sidang yang sukses, Lord Schwab! Tolong ambil bunga ini!",
  ui_story_5043_50430101_85_dialog_content = "D-Dan aku juga punya cokelat putih untukmu. Di Sini...",
  ui_story_5043_50430101_86_dialog_content = "(Agh...)",
  ui_story_5043_50430101_87_dialog_content = "Satu per satu, cantikku. Buatlah antrian yang tertib...",
  ui_story_5043_50430101_88_dialog_content = "<color=#e8d9bb>Taman Lumopolis, Kantor Hakim Ketua</color>",
  ui_story_5043_50430101_89_dialog_content = "Tujuan dari memiliki aturan adalah untuk memungkinkan kita dengan cepat melihat di mana kekacauan masih terjadi.",
  ui_story_5043_50430101_90_dialog_content = "Sudah berapa lama kasus hubungan konyol ini muncul di pengadilan?",
  ui_story_5043_50430101_91_dialog_content = "City Lord, Pak, hanya dalam sebulan terakhir ini.",
  ui_story_5043_50430101_92_dialog_content = "Jadi begitu. Ah, menjadi muda kembali...",
  ui_story_5043_50430101_93_dialog_content = "Tapi Hall of Justice adalah tempat yang sakral dan serius.",
  ui_story_5043_50430101_94_dialog_content = "Anda ingin kami berhenti mendengar kasus ini, Tuanku?",
  ui_story_5043_50430101_95_dialog_content = "Tidak, ini belum waktunya untuk itu.",
  ui_story_5043_50430101_96_dialog_content = "Itu hanya akan mengakibatkan warga mengarahkan kemarahan mereka ke Balai Kehakiman.",
  ui_story_5043_50430101_97_dialog_content = "Apa yang Anda ingin kami lakukan?",
  ui_story_5043_50430101_98_dialog_content = "Membentuk pengadilan bawahan sementara untuk menangani perselisihan romantis ini.",
  ui_story_5043_50430101_99_dialog_content = "Itu masih menjadi bagian dari Taman Lumopolis, tetapi terpisah dari Balai Kehakiman.",
  ui_story_5043_50430101_100_dialog_content = "Adapun kepegawaian ... kirimkan beberapa orang yang lebih muda. Ini akan menjadi pengalaman yang baik bagi mereka.",
  ui_story_5043_50430101_101_dialog_content = "Pengadilan sementara akan membutuhkan hakim ketua sementara.",
  ui_story_5043_50430101_102_dialog_content = "May Saya bertanya apakah Anda memiliki seseorang dalam pikiran?",
  ui_story_5043_50430101_103_dialog_content = "Saya kebetulan memperhatikan satu kandidat muda tertentu sebelumnya ...",
  ui_story_5043_50430101_104_dialog_content = "<color=#e8d9bb>Balai Kehakiman, Taman Lumopolis</color>",
  ui_story_5043_50430101_105_dialog_content = "Sepertinya Irridon dan Tuan Kota sedang mendiskusikan bisnis penting.",
  ui_story_5043_50430101_106_dialog_content = "Saya kira pertemuan hari ini tidak terjadi. Jika saya ingat dengan benar, slot gratis berikutnya dalam jadwalnya adalah...",
  ui_story_5043_50430101_107_dialog_content = "Oh maaf, PlayerName. Anda akan menunggu berhari-hari.",
  ui_story_5043_50430101_108_dialog_content = "Anda akan terbiasa dengan itu. Dia selalu melanggar janjinya dan mengabaikan pendapat orang lain.",
  ui_story_5043_50430101_109_dialog_content = "J-Jangan bicara seperti itu. Dan kita punya waktu luang sekarang, kan?",
  ui_story_5043_50430101_110_dialog_content = "Bahkan hanya dengan melihat para juri merapikan kertas mereka adalah cara yang bagus untuk menghabiskan waktu.",
  ui_story_5043_50430101_111_dialog_content = "Dakwaan. Bukti. Argumen... Oke, itu saja.",
  ui_story_5043_50430101_112_dialog_content = "Saya hampir selesai di sini. Tina, Apa kabarmu?",
  ui_story_5043_50430101_113_dialog_content = "Eh? Apa?",
  ui_story_5043_50430101_114_dialog_content = "Oh maaf, Leyn. Sidang itu berlangsung selama tiga jam. Aku semua-menguap ...",
  ui_story_5043_50430101_115_dialog_content = "Oh, seperti itu ya?",
  ui_story_5043_50430101_116_dialog_content = "Betapa sibuknya hari Anda. Di sini, sayangku Tina, minumlah secangkir minuman yang menenangkan untuk membuat Anda merasa lebih baik ...",
  ui_story_5043_50430101_117_dialog_content = "Mhm, terima kasih, Leyn. *Meneguk*",
  ui_story_5043_50430101_118_dialog_content = "Eh?!",
  ui_story_5043_50430101_119_dialog_content = "C-Cokelat panas?! Aku benci minuman manis!!!",
  ui_story_5043_50430101_120_dialog_content = "Heehee, bangun sekarang, kan? Saya tidak peduli jika Anda menderita narkolepsi. Bekerja dulu, tidur kemudian.",
  ui_story_5043_50430101_121_dialog_content = "Dan setelah kupikir-pikir... Aku merasa kau lebih mengantuk dari biasanya beberapa hari ini.",
  ui_story_5043_50430101_122_dialog_content = "Saya kira tidak demikian. Saya selalu terjaga selama empat jam setiap hari.",
  ui_story_5043_50430101_123_dialog_content = "Bahkan hari ini? Dan kamu mulai menguap sebelum kita menyelesaikan pekerjaan kemarin.",
  ui_story_5043_50430101_124_dialog_content = "Apakah kamu tidak tidur nyenyak? Saya tidak bisa membayangkan Anda menderita insomnia.",
  ui_story_5043_50430101_125_dialog_content = "Apa? Itu konyol. Seolah olah...",
  ui_story_5043_50430101_126_dialog_content = "Oke, semuanya sudah dirapikan. Aku akan pulang.",
  ui_story_5043_50430101_127_dialog_content = "Sampai jumpa besok, semuanya.",
  ui_story_5043_50430101_128_dialog_content = "Ya, aku akan segera pergi.",
  ui_story_5043_50430101_129_dialog_content = "Selamat tinggal, Nona Carleen dan pendamping pria.",
  ui_story_5043_50430101_130_dialog_content = "Sampai jumpa!",
  ui_story_5043_50430101_131_dialog_content = "(Apakah itu yang membuat saya direduksi menjadi? \"Teman laki-laki\"?)",
  ui_story_5043_50430101_132_dialog_content = "Wow! Lama tidak bertemu, pendamping pria Lady Carleen!",
  ui_story_5043_50430101_133_dialog_content = "Aku tahu suara itu...",
  ui_story_5043_50430101_134_dialog_content = "Matthieu! Dan Loew. Aku tidak berharap melihat kalian berdua.",
  ui_story_5043_50430101_135_dialog_content = "Matthieu, Saya melihat Anda menganggur dan kurang ajar seperti biasanya.",
  ui_story_5043_50430101_136_dialog_content = "Jangan marah, Putri. Saya di sini bukan untuk menganggur.",
  ui_story_5043_50430101_137_dialog_content = "Sesuatu yang menarik sedang terjadi. Apakah Anda ingin masuk?",
  ui_story_5043_50430101_138_dialog_content = "Sesuatu yang menarik\"?",
  ui_story_5043_50430101_139_dialog_content = "Ya. Saya sendiri baru saja mendapat kabar. Rakyat jelata tidak akan mendengarnya sampai besok.",
  ui_story_5043_50430101_140_dialog_content = "Majulah.",
  ui_story_5043_50430101_141_dialog_content = "Seperti ini. Pengadilan memiliki kasus yang sangat tidak biasa untuk didengar. Sekarang, itu belum ditugaskan, tapi ...",
  ui_story_5043_50430101_142_dialog_content = "Ini sama bagusnya dengan milikku.",
  ui_story_5043_50430101_143_dialog_content = "Maksudnya adalah dia memohon dan memohon mati-matian kepada Hakim Ketua sampai dia mendapatkannya.",
  ui_story_5043_50430101_144_dialog_content = "Hai! Berhenti menyela.",
  ui_story_5043_50430101_145_dialog_content = "Bagaimanapun, ini terhubung dengan Mooncrown Day...",
  ui_story_5043_50430101_146_dialog_content = "<color=#e8d9bb>Taman Lumopolis, Distrik Perumahan</color>",
  ui_story_5043_50430101_147_dialog_content = "La la... lalala... la la ♪...",
  ui_story_5043_50430101_148_dialog_content = "(Hal pertama yang harus dilakukan saat pulang: periksa apakah ada surat atau paket...)",
  ui_story_5043_50430101_149_dialog_content = "Oh...",
  ui_story_5043_50430101_150_dialog_content = "Tetap tidak ada.",
  ui_story_5043_50430101_151_dialog_content = "(Saya masih memiliki daun dan kacang <color=#FFB400>Dia</color> mengirim saya bulan lalu.)",
  ui_story_5043_50430101_152_dialog_content = "(Sudah waktunya aku mengirim sesuatu sebagai balasannya, tapi <color=#FFB400>Dia</color> masih belum memberi saya alamat barunya.)",
  ui_story_5043_50430101_153_dialog_content = "(Dan sekarang setelah kupikir-pikir, sudah hampir sebulan sejak aku mendengarnya <color=#FFB400>dia</color>.)",
  ui_story_5043_50430101_154_dialog_content = "(Cukup mengkhawatirkan... Kapan saya bisa mengirim kue yang saya buat <color=#FFB400>dia</color>?)",
  ui_story_5043_50430101_155_dialog_content = "(Mungkin saya harus... sedikit lebih proaktif?)",
  ui_story_5043_50430201_1_dialog_content = "<color=#e8d9bb>Keesokan harinya</color>",
  ui_story_5043_50430201_2_dialog_content = "Jadi begitulah keadaannya.",
  ui_story_5043_50430201_3_dialog_content = "Penguasa Kota telah memutuskan untuk mendirikan pengadilan sementara di Taman Lumopolis.",
  ui_story_5043_50430201_4_dialog_content = "Saya telah memutuskan untuk menyebutnya <color=#FFB400>Divisi Romansa</color>.",
  ui_story_5043_50430201_5_dialog_content = "Saya mengerti. Dan saya akan terus melakukan yang terbaik di sana.",
  ui_story_5043_50430201_6_dialog_content = "Tetapi jika saya boleh bertanya, siapa yang akan menjabat sebagai hakim ketua? Apakah Anda juga akan memikul beban itu?",
  ui_story_5043_50430201_7_dialog_content = "Tidak, kami telah mendapat petunjuk dari Tuan Kota tentang hal itu. Dia telah menyarankan Hakim <color=#FFB400>Schwab</color>.",
  ui_story_5043_50430201_8_dialog_content = "Sebuah keputusan yang tidak sepenuhnya kumengerti, meski dia tampaknya memberi kesan pada Penguasa Kota kemarin...",
  ui_story_5043_50430201_9_dialog_content = "Dan mungkin gayanya sangat cocok untuk berurusan dengan urusan cinta.",
  ui_story_5043_50430201_10_dialog_content = "Sangat baik. Schwab memang memiliki caranya sendiri yang unik untuk menyelesaikan kekacauan kemarin. Saya terkesan.",
  ui_story_5043_50430201_11_dialog_content = "Dia pasti tahu bagaimana menggunakan... pesonanya.",
  ui_story_5043_50430201_12_dialog_content = "Anda tidak harus kecewa, Leyn.",
  ui_story_5043_50430201_13_dialog_content = "Anda semua baru saja menjadi juri resmi, tetapi Tuan Kota menghargai kemampuan Anda.",
  ui_story_5043_50430201_14_dialog_content = "Dan ketika Anda kembali dari Divisi Percintaan, Anda akan berada pada posisi yang baik untuk promosi.",
  ui_story_5043_50430201_15_dialog_content = "Ya. Terima kasih, Hakim Ketua.",
  ui_story_5043_50430201_16_dialog_content = "Juga, saya punya tugas lain untuk Anda.",
  ui_story_5043_50430201_17_dialog_content = "Faktanya, ini bisa menjadi kasus tersulit yang harus ditangani Divisi Percintaan saat ini.",
  ui_story_5043_50430201_18_dialog_content = "Anda mungkin pernah mendengarnya? <color=#FFB400>Kasus patung tanpa kepala</color>?",
  ui_story_5043_50430201_19_dialog_content = "Saya mendapatkan kasus pertama saya begitu cepat?",
  ui_story_5043_50430201_20_dialog_content = "Ah, lega rasanya mendengar kau begitu tertarik. Saya sudah memiliki lima atau enam orang yang menolak kasus ini.",
  ui_story_5043_50430201_21_dialog_content = "Dan mengapa mereka melakukannya?",
  ui_story_5043_50430201_22_dialog_content = "Terlepas dari fakta bahwa ini adalah kasus yang aneh... kebanyakan dari mereka mengatakan bahwa mereka sibuk berkencan dengan kekasih mereka.",
  ui_story_5043_50430201_23_dialog_content = "Oh, begitu…",
  ui_story_5043_50430201_24_dialog_content = "(Para bangsawan itu tidak pernah berubah...)",
  ui_story_5043_50430201_25_dialog_content = "Penggugat dalam kasus ini adalah seorang bangsawan dari Halaman Lumopolis, Tn. <color=#FFB400>Byron</color>.",
  ui_story_5043_50430201_26_dialog_content = "<color=#e8d9bb>Empat hari yang lalu</color>",
  ui_story_5043_50430201_27_dialog_content = "<color=#e8d9bb>Ding, ding—Ding—</color>",
  ui_story_5043_50430201_28_dialog_content = "Aku datang, aku datang. Berhenti mengoceh!",
  ui_story_5043_50430201_29_dialog_content = "Anda menelepon, Pak? Anda membunyikan Bell of Justice?",
  ui_story_5043_50430201_30_dialog_content = "Ya. Saya ingin menuntut seseorang! Ini tetangga saya.",
  ui_story_5043_50430201_31_dialog_content = "Dia rusak <color=#FFB400>Galatea</color>, patung yang berdiri di luar Hall of Justice. Aku melihatnya dengan mataku sendiri!",
  ui_story_5043_50430201_32_dialog_content = "Tunggu sebentar. Saya tahu patung di luar sana melambangkan keadilan. Tapi sejak kapan namanya Galatea?",
  ui_story_5043_50430201_33_dialog_content = "Dan ya, itu rusak beberapa hari yang lalu, tapi sejujurnya, kami pikir itu sudah tua ...",
  ui_story_5043_50430201_34_dialog_content = "Nona, tolong jaga bahasamu. Galatea adalah <color=#FFB400>\"dia\"</color>!!! Akulah yang menamainya.",
  ui_story_5043_50430201_35_dialog_content = "Eh, baiklah. Lalu, maukah Anda menyerahkan keluhan Anda kepada saya?",
  ui_story_5043_50430201_36_dialog_content = "Biar kulihat...",
  ui_story_5043_50430201_37_dialog_content = "Hm? Tuan Byron, kejahatan yang Anda tuduhkan pada tetangga Anda—apakah ini benar?",
  ui_story_5043_50430201_38_dialog_content = "Anda baru saja mengatakan dia merusak patung itu, tetapi di sini Anda telah menulis <color=#FFB400>\"penghalang cinta</color>.\"",
  ui_story_5043_50430201_39_dialog_content = "Itu benar. Karena...",
  ui_story_5043_50430201_40_dialog_content = "Galatea adalah milikku <color=#FFB400>kekasih</color>!",
  ui_story_5043_50430201_41_dialog_content = "Jadi dia jatuh cinta pada sebuah patung... dan sekarang ingin menuntut orang yang merusaknya?",
  ui_story_5043_50430201_42_dialog_content = "Ya. Karena patung itu tergolong fasilitas umum, kita tidak bisa mencegah seseorang untuk jatuh cinta padanya.",
  ui_story_5043_50430201_42X1_dialog_content = "Jadi, tegasnya, ini adalah kasus untuk Divisi Percintaan.",
  ui_story_5043_50430201_43_dialog_content = "Saya juga mengirim orang untuk berbicara dengan terdakwa.",
  ui_story_5043_50430201_44_dialog_content = "Ada lubang dalam cerita Tn. Byron. Terdakwa dalam kasus tersebut mungkin bukan tersangka.",
  ui_story_5043_50430201_45_dialog_content = "Seperti yang Anda ketahui, di sini di Hall of Justice, kami menyelidiki sebanyak yang kami nilai. Leyn, kita harus mencari tahu apa yang terjadi sebelum kasusnya disidangkan.",
  ui_story_5043_50430201_46_dialog_content = "Jika tidak, kami hanya akan menunda kasus ini sampai sidang berikutnya. Dan Divisi Percintaan bahkan bukan pengaturan permanen, jadi itu bukan pilihan.",
  ui_story_5043_50430201_47_dialog_content = "Ya saya mengerti. Saya akan menyelesaikan kasus ini sebelum Divisi Percintaan ditutup, saya jamin.",
  ui_story_5043_50430201_48_dialog_content = "Saya senang mendengarnya. Dan dua kolega Anda akan membantu Anda.",
  ui_story_5043_50430201_49_dialog_content = "Salah satunya adalah teman lamamu, Tina. Dia setuju untuk membantu pagi ini.",
  ui_story_5043_50430201_50_dialog_content = "Saya telah memintanya untuk meninjau dokumennya, meskipun saya curiga dia sedang tidur sekarang.",
  ui_story_5043_50430201_51_dialog_content = "Yang lain... yah, dia pusing, tapi secara teknis dia <color=#FFB400>lebih berpengalaman</color> daripada Anda. Saya yakin dia akan memberi Anda beberapa petunjuk berguna.",
  ui_story_5043_50430201_52_dialog_content = "Anda bisa bertemu dengannya sekarang, di depan patung itu.",
  ui_story_5043_50430201_53_dialog_content = "Bandingkan catatan dengan Tina ketika Anda menyelesaikan penyelidikan Anda.",
  ui_story_5043_50430201_54_dialog_content = "Aku akan segera pergi.",
  ui_story_5043_50430201_55_dialog_content = "<color=#e8d9bb>Taman Lumopolis, dekat patung</color>",
  ui_story_5043_50430201_56_dialog_content = "(Saya bertanya-tanya siapa orang yang \"lebih berpengalaman\" yang dirahasiakan oleh Hakim Ketua ini...)",
  ui_story_5043_50430201_57_dialog_content = "Ya ampun, apakah Hall of Justice membiarkan orang biasa masuk sekarang?",
  ui_story_5043_50430201_58_dialog_content = "(Saya seharusnya sudah menebak ...)",
  ui_story_5043_50430201_59_dialog_content = "Menurut saya Leyn terlihat lebih seperti hakim yang tepat daripada Anda, Matthieu.",
  ui_story_5043_50430201_60_dialog_content = "Selamat siang, Kapten Carleen, dan harapan terbaik saya.",
  ui_story_5043_50430201_61_dialog_content = "Tolong, jangan berdiri pada upacara. Ini PlayerName. Matthieu di sini telah meminta kami berdua untuk membantu penyelidikan.",
  ui_story_5043_50430201_62_dialog_content = "Anda adalah Caelestite yang legendaris! Anda jauh lebih mudah didekati secara langsung!",
  ui_story_5043_50430201_63_dialog_content = "K-Kau sangat baik. Saya harap saya bisa membantu.",
  ui_story_5043_50430201_64_dialog_content = "<size=32>Apa yang di dunia rumor katakan tentang saya ...</size>",
  ui_story_5043_50430201_65_dialog_content = "Anda harus berterima kasih kepada Dewa Cahaya, orang biasa. Dengan bantuan kami, pekerjaan Anda pasti akan berjalan dengan cepat.",
  ui_story_5043_50430201_66_dialog_content = "Saya hanya akan kagum jika tidak berjalan buruk.",
  ui_story_5043_50430201_67_dialog_content = "Ada apa, pemula? Kamu sepertinya tidak bersemangat.",
  ui_story_5043_50430201_68_dialog_content = "Ini adalah salah satu kasus teraneh dalam sejarah Hall of Justice. Tunjukkan sedikit antusiasme!",
  ui_story_5043_50430201_69_dialog_content = "Ya. Patung yang aneh, kejahatan yang aneh, penggugat yang aneh. Dan mentor yang aneh.",
  ui_story_5043_50430201_70_dialog_content = "Awas, Nak! Tunjukkan sedikit rasa hormat.",
  ui_story_5043_50430201_71_dialog_content = "Sangat baik. Aku tidak datang ke sini untuk bertengkar denganmu. Saya menganggap Anda telah memeriksa patung itu?",
  ui_story_5043_50430201_72_dialog_content = "Hah? Oh, maksudmu kotak uang?",
  ui_story_5043_50430201_73_dialog_content = "Maaf, itu hanya tanpa kepala, itu mengingatkan saya pada sesuatu yang mungkin Anda simpan koin. Itu membuat saya ingin memasukkan Nightium.",
  ui_story_5043_50430201_74_dialog_content = "Bisa aja. Coba dan tanggapi ini dengan serius...",
  ui_story_5043_50430201_75_dialog_content = "<color=#e8d9bb>Patah-</color>",
  ui_story_5043_50430201_76_dialog_content = "Apa katamu?",
  ui_story_5043_50430201_77_dialog_content = "Graaaaaah! Mengaum!",
  ui_story_5043_50430201_78_dialog_content = "Apa-apaan ini?! Bagaimana Eclipsites masuk ke Lumopolis Gardens?",
  ui_story_5043_50430201_79_dialog_content = "Tidak mungkin! Lumopolis dijaga siang dan malam. Tidak mungkin Eclipsite bisa masuk...",
  ui_story_5043_50430201_80_dialog_content = "Penjaga!",
  ui_story_5043_50430201_81_dialog_content = "Officer!",
  ui_story_5043_50430201_82_dialog_content = "Saya akan memeriksa semua catatan masuk dan keluar. Dan beri tahu Nightwatch saya ingin laporan tentang semua aktivitas terbaru!",
  ui_story_5043_50430201_83_dialog_content = "Adapun Eclipsites ... PlayerName, saya anggap kalian berempat bisa menangani mereka?",
  ui_story_5043_50430201_84_dialog_content = "Tentu saja. Pergi, Carleen.",
  ui_story_5043_50430201_85_dialog_content = "Baiklah kalau begitu. Saatnya Eclipsites menerima putusan akhir mereka.",
  ui_story_5043_50430202_1_dialog_content = "Ini sudah berakhir! Tidak ada yang terluka, bukan?",
  ui_story_5043_50430202_2_dialog_content = "Saya baik-baik saja. Hanya sedikit jijik.",
  ui_story_5043_50430202_3_dialog_content = "Aku baru saja bekerja. Sekarang saya butuh mandi lagi.",
  ui_story_5043_50430202_4_dialog_content = "Hei, orang biasa, apakah kamu baik-baik saja?",
  ui_story_5043_50430202_5_dialog_content = "Terima kasih untuk bertanya. Kebetulan, saya tidak diberkati dengan kebutuhan yang sama untuk mandi terus-menerus seperti yang dinikmati bangsawan.",
  ui_story_5043_50430202_6_dialog_content = "Aku merasa sangat kasihan padamu. Meskipun saya kira itu berarti Loewe adalah germaphobe terbesar di sini.",
  ui_story_5043_50430202_7_dialog_content = "Anda selalu menutupi diri Anda dengan sangat ketat, Loewe. Saya curiga Anda bahkan menganggap udaranya kotor.",
  ui_story_5043_50430202_8_dialog_content = "Kalian mungkin bisa mundur jika patung itu rusak.",
  ui_story_5043_50430202_9_dialog_content = "Jangan abaikan aku!",
  ui_story_5043_50430202_10_dialog_content = "Oke, Anda sudah cukup melihat. Hall of Justice dapat menanganinya sekarang.",
  ui_story_5043_50430202_11_dialog_content = "Penting <color=#FFB400>bukti</color> tidak boleh dibiarkan duduk di tempat terbuka seperti ini.",
  ui_story_5043_50430202_12_dialog_content = "Menurut penggugat, ini adalah <color=#FFB400>korban</color>.",
  ui_story_5043_50430202_13_dialog_content = "Tunggu, biarkan aku melihat lebih dekat ...",
  ui_story_5043_50430202_14_dialog_content = "Hmm. Bagian patahan lebih bersih. Itu tidak terlihat seperti retakan lama yang akhirnya pecah.",
  ui_story_5043_50430202_15_dialog_content = "Ini lebih seperti seseorang dengan sengaja mematahkan kepalanya.",
  ui_story_5043_50430202_16_dialog_content = "PlayerName, ada saran ga?",
  ui_story_5043_50430202_17_dialog_content = "Ada satu hal yang aneh.",
  ui_story_5043_50430202_18_option_content = "Kepala yang hilang",
  ui_story_5043_50430202_19_dialog_content = "Itu tidak terlihat seperti vandalisme spontan. Istirahat terlalu bersih.",
  ui_story_5043_50430202_20_dialog_content = "Juga, tidak ada kerusakan lain. Hanya kepala yang hilang.",
  ui_story_5043_50430202_21_option_content = "Pecahan patung",
  ui_story_5043_50430202_22_dialog_content = "Lingkungannya terlalu bersih. Bukankah seharusnya ada bagian tambahan dari patung yang tergeletak di sekitar?",
  ui_story_5043_50430202_23_dialog_content = "Orang-orang yang dikirim untuk mengumpulkan bukti mungkin menyapu mereka.",
  ui_story_5043_50430202_24_dialog_content = "I-Itu masuk akal! Kalau begitu, kurasa yang aneh adalah—kepala yang hilang.",
  ui_story_5043_50430202_25_dialog_content = "Saya pikir Anda benar. Sepertinya seseorang mematahkan kepala patung itu agar bisa <color=#FFB400>curi itu</color>...",
  ui_story_5043_50430202_26_dialog_content = "Hei, tunggu. Apakah salah satu dari Anda melihat <color=#FFB400>itu</color>? Saya muncul begitu saja entah dari mana.",
  ui_story_5043_50430202_27_dialog_content = "Lihat, di samping jendela itu, di langit di atas Lumopolis...",
  ui_story_5043_50430202_28_dialog_content = "Ini adalah <color=#FFB400>bulan</color>.",
  ui_story_5043_50430202_29_dialog_content = "Saya melihatnya!",
  ui_story_5043_50430202_30_dialog_content = "Hal-hal aneh terus saja terjadi. Apa yang sedang terjadi di dunia ini?",
  ui_story_5043_50430202_31_dialog_content = "Sangat menarik. Haruskah kita melihatnya?",
  ui_story_5043_50430202_32_dialog_content = "Tunggu ... Kami masih memiliki pekerjaan yang harus dilakukan!",
  ui_story_5043_50430202_33_dialog_content = "Oh, kalian semua di sini?",
  ui_story_5043_50430202_34_dialog_content = "Hai, Tina. Ini PlayerName. Caelestite.",
  ui_story_5043_50430202_35_dialog_content = "Heheh. Sebenarnya kami bertemu bulan lalu, pada Hari Mahkota Bulan.",
  ui_story_5043_50430202_36_dialog_content = "Selamat pagi, PlayerName. Senang bertemu denganmu lagi.",
  ui_story_5043_50430202_37_dialog_content = "Halo, Tina. Meskipun ini bukan pagi lagi...",
  ui_story_5043_50430202_38_dialog_content = "Tina selalu berpikir itu pagi ketika dia bangun.",
  ui_story_5043_50430202_39_dialog_content = "Anda memiliki waktu yang tepat, Tina. Mari berbagi catatan tentang investigasi.",
  ui_story_5043_50430202_40_dialog_content = "Lalu... mari kita berdua mengatakan apa yang kita miliki pada saat yang sama. Sejauh ini, saya telah menemukan—",
  ui_story_5043_50430202_41_dialog_content = "Bukan apa-apa.",
  ui_story_5043_50430202_42_dialog_content = "Mendesah. Jadi Anda belum membuat kemajuan juga?",
  ui_story_5043_50430202_43_dialog_content = "Saya berulang kali memeriksa dokumen kasus yang diberikan Ketua Hakim kepada saya.",
  ui_story_5043_50430202_44_dialog_content = "Tapi itu semua sangat tidak logis dan tidak konsisten. Saya tidak bisa memahami semua itu.",
  ui_story_5043_50430202_45_dialog_content = "Kami memiliki satu teori potensial, setidaknya.",
  ui_story_5043_50430202_46_dialog_content = "PlayerName dan saya curiga kepala patung itu dicuri.",
  ui_story_5043_50430202_47_dialog_content = "Benar... Mengapa ada orang yang melakukan itu?",
  ui_story_5043_50430202_48_dialog_content = "Siapa tahu! Mungkin Judge Jr. memutuskan untuk membeli sendiri tutup kepala baru.",
  ui_story_5043_50430202_49_dialog_content = "Jika kita tidak membuat kemajuan, mungkin kita harus berhenti untuk hari ini?",
  ui_story_5043_50430202_50_dialog_content = "Tunggu! Sebenarnya, aku... Erm...",
  ui_story_5043_50430202_51_dialog_content = "Masalahnya, saya ingin meminta nasihat dari Anda semua tentang masalah pribadi.",
  ui_story_5043_50430202_52_dialog_content = "Uh, masalah pribadi seperti apa tepatnya? Saya tidak yakin saya ingin terlibat ...",
  ui_story_5043_50430202_53_dialog_content = "F-Baik. Saya mengalami sedikit masalah akhir-akhir ini dan ingin pendapat kedua.",
  ui_story_5043_50430202_54_dialog_content = "Oooh. Masalah pribadi, di saat seperti ini?",
  ui_story_5043_50430202_55_dialog_content = "Biarkan saya berani menebak. Ini masalah romantis, bukan?",
  ui_story_5043_50430202_56_dialog_content = "Anda terlalu bersemangat tentang ini.",
  ui_story_5043_50430202_57_dialog_content = "Mmm. Omong-omong, bisakah saya mengundang Anda semua untuk datang ke tempat saya? Saya sudah menyiapkan teh dan kue.",
  ui_story_5043_50430202_58_dialog_content = "PlayerName, Saya ingin Anda datang juga.",
  ui_story_5043_50430202_59_dialog_content = "Saya mendengar Anda Caelestites sangat pandai memahami emosi orang. Jadi kau harus membantuku.",
  ui_story_5043_50430202_60_dialog_content = "Itu akan menjadi suatu kehormatan. Meskipun saya tidak yakin kami memiliki kemampuan khusus itu ...",
  ui_story_5043_50430301_1_dialog_content = "<color=#e8d9bb>Taman Lumopolis, rumah Tina</color>",
  ui_story_5043_50430301_2_dialog_content = "Oke, inilah yang terjadi.",
  ui_story_5043_50430301_3_dialog_content = "Pada Hari Mahkota Bulan bulan lalu, saya mendapat hadiah dari <color=#FFB400>dia</color>.",
  ui_story_5043_50430301_4_dialog_content = "Itu hanya beberapa hal biasa, tapi aku tahu itu <color=#FFB400>Dia</color> sangat peduli padaku.",
  ui_story_5043_50430301_5_dialog_content = "W-Wah! Tunggu, Tina. Apakah kamu sedang jatuh cinta?",
  ui_story_5043_50430301_6_dialog_content = "Hah? Tidak, saya tidak berpikir itu saja ...",
  ui_story_5043_50430301_7_dialog_content = "Nah, ini terdengar seperti hal yang dilakukan kekasih.",
  ui_story_5043_50430301_8_dialog_content = "Kalau menurutmu juga begitu...",
  ui_story_5043_50430301_9_dialog_content = "Oh, lupakan itu! Biarkan aku menyelesaikan ceritanya.",
  ui_story_5043_50430301_10_dialog_content = "Sudah hampir sebulan sejak Hari Mahkota Bulan, dan menurut tradisi, saya harus mengirim <color=#FFB400>dia</color> hadiah sebagai balasannya.",
  ui_story_5043_50430301_11_dialog_content = "Jadi saya membuat beberapa kue untuk <color=#FFB400>dia</color>. Saya bahkan membuat setiap kue dalam bentuk yang berbeda.",
  ui_story_5043_50430301_12_dialog_content = "Jadi kue sudah siap dikirim. Tetapi...",
  ui_story_5043_50430301_13_dialog_content = "Tetapi <color=#FFB400>Dia</color> belum membalas suratku lagi.",
  ui_story_5043_50430301_14_dialog_content = "Saya belum punya kesempatan untuk diam-diam bertemu dengan <color=#FFB400>dia</color>. Dan sekarang saya bahkan tidak mendapatkan surat apapun.",
  ui_story_5043_50430301_15_dialog_content = "Aku sangat khawatir. Itu membuatku tetap terjaga. Saya hanya tidur 16 jam semalam!",
  ui_story_5043_50430301_16_dialog_content = "Sungguh pria yang tercela!",
  ui_story_5043_50430301_17_dialog_content = "Ya. Dia terdengar lebih buruk daripada Matthieu.",
  ui_story_5043_50430301_18_dialog_content = "Saya sarankan Anda menyerah saja padanya.",
  ui_story_5043_50430301_19_dialog_content = "Tidak, saya belum bisa melakukannya. Aku yakin dia punya alasannya.",
  ui_story_5043_50430301_20_dialog_content = "Lagipula, <color=#FFB400>Dia</color> memiliki tampilan yang cukup unik. Orang-orang memperhatikan <color=#FFB400>dia</color> kemanapun dia pergi. Jadi mungkin dia tidak bisa tetap berhubungan sebanyak yang dia mau.",
  ui_story_5043_50430301_21_dialog_content = "Uh oh. Tina punya kasus cinta yang buruk.",
  ui_story_5043_50430301_22_dialog_content = "Hmm…?",
  ui_story_5043_50430301_23_dialog_content = "<size=32>Hai, PlayerName, Matthieu, Loew. aku punya teori...</size>",
  ui_story_5043_50430301_24_dialog_content = "<size=32>Ini <color=#FFB400>pria</color> Tina berbicara tentang suara yang tidak asing!</size>",
  ui_story_5043_50430301_25_dialog_content = "<size=32>BENAR! Seseorang yang diperhatikan kemanapun dia pergi...</size>",
  ui_story_5043_50430301_26_dialog_content = "<size=32>Dan hanya melakukan sedikit usaha untuk membuat pengagumnya senang...</size>",
  ui_story_5043_50430301_27_dialog_content = "<size=32>Dan kejam, dangkal, terobsesi pada diri sendiri, egois...</size>",
  ui_story_5043_50430301_28_dialog_content = "<size=32>Sepertinya dia bisa jadi kembaranmu.</size>",
  ui_story_5043_50430301_29_dialog_content = "<size=32>Bagaimanapun, orang yang dibicarakan Tina ini pasti <color=#FFB400>Schwab</color>, Kanan?</size>",
  ui_story_5043_50430301_30_dialog_content = "Hei, apa yang kamu bisikkan?",
  ui_story_5043_50430301_31_dialog_content = "Ahem. Oke, Tina. Kami tahu siapa naksir Anda.",
  ui_story_5043_50430301_32_dialog_content = "Apa? Anda sudah menebaknya? Aku berharap untuk merahasiakannya...",
  ui_story_5043_50430301_33_dialog_content = "(Seperti Tina tidak punya pilihan selain mengakuinya ...)",
  ui_story_5043_50430301_34_dialog_content = "Pertama kali saya melihatnya di Salar Manor.",
  ui_story_5043_50430301_35_dialog_content = "Saya diundang ke pesta dansa di sana.",
  ui_story_5043_50430301_36_dialog_content = "Tapi saya datang sedikit lebih awal dan saya diantar ke taman untuk menunggu.",
  ui_story_5043_50430301_37_dialog_content = "Tapi tentu saja, Salar memiliki taman yang luar biasa, dan saya tersesat di labirin pagar.",
  ui_story_5043_50430301_38_dialog_content = "Surga tahu berapa lama saya menghabiskan waktu di sana. Kemudian, tiba-tiba, saya menemukan sebuah paviliun kecil, dan dia sedang duduk di dalamnya.",
  ui_story_5043_50430301_39_dialog_content = "Dia terkejut melihat ada orang di sana. Dan kami menghabiskan waktu begitu lama untuk saling menatap di bawah langit biru yang indah itu...",
  ui_story_5043_50430301_40_dialog_content = "Itu adalah pertama kalinya saya menyadari betapa lembut dan baiknya dia. Dia tampak menyatu dengan pepohonan dan bunga di sekelilingnya.",
  ui_story_5043_50430301_41_dialog_content = "Dia akhirnya pergi sebelum saya. Tapi saya tidak bisa memperhatikan orang lain hari itu.",
  ui_story_5043_50430301_42_dialog_content = "Heheh. Sangat romantis.",
  ui_story_5043_50430301_43_dialog_content = "(Salar Manor. Maka itu pasti Schwab Salar.)",
  ui_story_5043_50430301_44_dialog_content = "(\"Lembut\"? \"Baik\"?! Orang itu?? Kalau menurutmu begitu...)",
  ui_story_5043_50430301_45_dialog_content = "Mengingat Anda sudah tahu siapa dia, saya minta bantuan Anda semua.",
  ui_story_5043_50430301_46_dialog_content = "Aku membutuhkanmu untuk membantuku <color=#FFB400>Operasi Acci-Meet</color>.",
  ui_story_5043_50430301_47_dialog_content = "Apa sebenarnya Acci-Meet itu?",
  ui_story_5043_50430301_48_dialog_content = "Yah, saya ingin merekayasa sebanyak mungkin <color=#FFB400>pertemuan yang tidak disengaja</color> bersamanya mungkin. Terima. Pintar, ya?",
  ui_story_5043_50430301_49_dialog_content = "Anda tidak akan menyerah, kan? Bahkan jika kami tidak membantu Anda.",
  ui_story_5043_50430301_50_dialog_content = "Tidak. Maaf...",
  ui_story_5043_50430301_51_dialog_content = "Sangat baik. Saya selalu senang membantu rekan kerja.",
  ui_story_5043_50430301_52_dialog_content = "Iya, aku juga.",
  ui_story_5043_50430301_53_dialog_content = "Gaah... Graaah...",
  ui_story_5043_50430301_54_dialog_content = "Eclipsite!",
  ui_story_5043_50430301_55_dialog_content = "Ah, benarkah! Pelayan! Pelayan!",
  ui_story_5043_50430301_56_dialog_content = "Sudahlah. Sudah lama sejak saya melatih Tangan Ilahi.",
  ui_story_5043_50430301_57_dialog_content = "Aku akan membersihkan kotoran ini sendiri.",
  ui_story_5043_50430301_58_dialog_content = "Bukankah ini rumahmu sendiri? Anda bertingkah seperti ini hanya beberapa kecoak!",
  ui_story_5043_50430302_1_dialog_content = "Pertarungan yang mendebarkan... *Menguap*",
  ui_story_5043_50430302_2_dialog_content = "Saya tidak memperhatikan sebelumnya, tetapi apakah Anda kidal?",
  ui_story_5043_50430302_3_dialog_content = "Ha ha. Ya, benar. Saya dilatih dengan cara ini untuk menangani kekuatan Tangan Ilahi.",
  ui_story_5043_50430302_4_dialog_content = "Tapi aku selalu merasa sangat lelah setelah bertengkar...",
  ui_story_5043_50430302_5_dialog_content = "Jika Anda akan tidur sekarang, maka kami akan pergi.",
  ui_story_5043_50430302_6_dialog_content = "Tempat tidur? TIDAK! Saya penuh energi.",
  ui_story_5043_50430302_7_dialog_content = "Mari kita kembali ke bisnis. Saya membutuhkan Anda semua untuk membantu saya dengan Operasi Accimeet.",
  ui_story_5043_50430302_8_dialog_content = "Oke, tapi... bagaimana?",
  ui_story_5043_50430302_9_dialog_content = "Yah... Sejujurnya, aku belum pernah mengejar siapa pun sebelumnya. Itu sebabnya aku butuh bantuanmu.",
  ui_story_5043_50430302_10_dialog_content = "Apa yang harus saya lakukan?",
  ui_story_5043_50430302_11_dialog_content = "Biarkan saya berpikir... Saya pernah membaca di sebuah buku bahwa langkah pertama untuk berubah adalah mengakui kekurangan Anda sendiri.",
  ui_story_5043_50430302_12_dialog_content = "Saya pikir cara terbaik untuk memenangkan hatinya adalah—<color=#FFB400> untuk mengakui cintamu</color>.",
  ui_story_5043_50430302_13_dialog_content = "Pergi ke suatu tempat dia kemungkinan akan muncul dan menunggunya.",
  ui_story_5043_50430302_14_dialog_content = "Dan ketika dia muncul, Anda menyerang! Kejutkan dia!",
  ui_story_5043_50430302_15_dialog_content = "Oh. Jadi begitu...",
  ui_story_5043_50430302_16_dialog_content = "Salah lagi, orang biasa. Tina tidak bisa hanya mengandalkan mengambil inisiatif. Dia juga perlu belajar <color=#FFB400>seni penyembunyian</color>.",
  ui_story_5043_50430302_17_dialog_content = "Dia harus menyembunyikan perasaannya yang sebenarnya. Dia tidak bisa diizinkan untuk melihat betapa cemasnya dia.",
  ui_story_5043_50430302_18_dialog_content = "Jika Anda memiliki keberanian untuk mendekatinya namun terlalu gugup untuk menatap matanya, berpura-puralah malu.",
  ui_story_5043_50430302_19_dialog_content = "Oh begitu! Saya mengerti.",
  ui_story_5043_50430302_20_dialog_content = "Dan juga-<color=#FFB400>pengintaian</color>.",
  ui_story_5043_50430302_21_dialog_content = "Anda harus memperhatikan sikapnya saat mendiskusikan topik yang tampaknya tidak berbahaya.",
  ui_story_5043_50430302_22_dialog_content = "Anda akan bisa mengetahui perasaannya yang sebenarnya dalam dua atau tiga percakapan.",
  ui_story_5043_50430302_23_dialog_content = "Kedengarannya sulit. Tapi aku akan melakukan yang terbaik...",
  ui_story_5043_50430302_24_dialog_content = "Setelah mempertimbangkan dengan hati-hati, saya pikir yang terbaik adalah adil <color=#FFB400>jujur</color>.",
  ui_story_5043_50430302_25_dialog_content = "Selama suatu hubungan, semua kebiasaan dan kekurangan Anda akan terungkap kepada orang lain.",
  ui_story_5043_50430302_26_dialog_content = "Anda tidak akan bisa menutupinya selamanya. Jadi, kejujuran adalah hal yang paling penting.",
  ui_story_5043_50430302_27_dialog_content = "Kamu benar! Meskipun saya berharap kita bahkan bisa sampai ke tahap itu ...",
  ui_story_5043_50430302_28_dialog_content = "Terimakasih semuanya! Saya akan mengingat semua saran Anda.",
  ui_story_5043_50430302_29_dialog_content = "Omong-omong... apakah kalian berbicara dari pengalaman?",
  ui_story_5043_50430302_30_dialog_content = "Ehem...",
  ui_story_5043_50430302_31_dialog_content = "Saya khawatir saya tidak memiliki pengalaman praktis, tidak ...",
  ui_story_5043_50430302_32_dialog_content = "A-aku tidak bermaksud mengkritik siapa pun. Hanya saja... Kurasa aku hanya perlu mencobanya sendiri.",
  ui_story_5043_50430302_33_dialog_content = "Tapi dimana aku bisa menemukannya?",
  ui_story_5043_50430302_34_dialog_content = "Jika itu dia, kemungkinan besar di suatu tempat yang sibuk, di suatu tempat yang penuh dengan orang.",
  ui_story_5043_50430302_35_dialog_content = "Oh. Oke...",
  ui_story_5043_50430302_36_dialog_content = "Berbicara tentang tempat-tempat sibuk, ada pilihan yang jelas.",
  ui_story_5043_50430302_37_dialog_content = "Tempat di mana para bangsawan dan orang biasa berkumpul. Tepat di bawah \"bulan\".",
  ui_story_5043_50430302_38_dialog_content = "K-Kenapa!?",
  ui_story_5043_50430302_39_dialog_content = "Saya mendengar beberapa berita tentang \"bulan\" sebelumnya. Saya pikir kita harus pergi dan menyelidiki.",
  ui_story_5043_50430302_40_dialog_content = "Anda hanya ingin pergi dan melihatnya.",
  ui_story_5043_50430302_41_dialog_content = "Jangankan dia, aku juga penasaran. Ayo pergi sekarang!",
  ui_story_5043_50430302_42_dialog_content = "Oh tidak. Tunggu sebentar!",
  ui_story_5043_50430302_43_dialog_content = "Saya ingin memakai <color=#FFB400>sarung tangan</color> Saya memakainya saat pertama kali bertemu dan berpegangan tangan.",
  ui_story_5043_50430302_44_dialog_content = "Dan saya harus mengambil kue yang saya buat untuknya juga.",
  ui_story_5043_50430401_1_dialog_content = "<color=#e8d9bb>Taman Lumopolis, Distrik Perumahan</color>",
  ui_story_5043_50430401_2_dialog_content = "Jadi, balon udara yang terlihat seperti bulan ini telah melayang di sana selama berhari-hari?",
  ui_story_5043_50430401_3_dialog_content = "Aku bahkan tidak menyadarinya...",
  ui_story_5043_50430401_4_dialog_content = "Saya kira saya tidak membayangkan akan ada apa pun di atas sana, kecuali Lumopolis Gardens dan matahari.",
  ui_story_5043_50430401_5_dialog_content = "Sangat normal bagi Anda untuk melewatkannya. Orang biasa seperti Anda tidak akan pernah berpikir untuk mengangkat kepala dan menghargai keindahan langit.",
  ui_story_5043_50430401_6_dialog_content = "Hei, katakan itu lagi!",
  ui_story_5043_50430401_7_dialog_content = "Baiklah baiklah. Tolong lebih banyak berjalan, kurangi berkelahi.",
  ui_story_5043_50430401_8_dialog_content = "Saya ingat ketika saya masih kecil, ibu saya membawa saya ke Stairway to the Skies dan berkata bahwa itulah satu-satunya tempat kami dapat melihat bintang.",
  ui_story_5043_50430401_9_dialog_content = "Dengan setiap langkah, Anda melihat satu bintang. Naiki semua anak tangga, Anda melihat seribu.",
  ui_story_5043_50430401_10_dialog_content = "Saya sangat bersemangat! Aku berlari sampai ke puncak.",
  ui_story_5043_50430401_11_dialog_content = "Berapa banyak bintang yang kamu lihat?",
  ui_story_5043_50430401_12_dialog_content = "Tidak ada. Hanya matahari. Saat itu tengah hari.",
  ui_story_5043_50430401_13_dialog_content = "Anda setidaknya bisa menunggu sampai malam!",
  ui_story_5043_50430401_14_dialog_content = "Tapi saat aku tidur...",
  ui_story_5043_50430401_15_dialog_content = "...",
  ui_story_5043_50430401_16_dialog_content = "Omong-omong Matthieu, apa yang kamu dengar tentang \"bulan\"?",
  ui_story_5043_50430401_17_dialog_content = "Oh, itu hanya beberapa acara yang dibuat oleh para penggemar Mooncrown Day itu.",
  ui_story_5043_50430401_18_dialog_content = "Mereka mengirim balon udara panas yang terlihat seperti bulan ke langit di atas Lumopolis, untuk mengumumkan pemerintahan cinta bebas.",
  ui_story_5043_50430401_19_dialog_content = "Dan saat balon naik, semua orang tahu untuk berkumpul di bawahnya untuk salon dadakan.",
  ui_story_5043_50430401_20_dialog_content = "Semua bangsawan yang mengikuti tren menyukainya.",
  ui_story_5043_50430401_21_dialog_content = "Jadi begitu. aku ingat Carleen mengatakan sesuatu tentang penggemar Mooncrown Day.",
  ui_story_5043_50430401_22_dialog_content = "Itulah mengapa mereka menggunakan balon yang terlihat seperti bulan... karena ini adalah Hari Mahkota Bulan.",
  ui_story_5043_50430401_23_dialog_content = "Betapa pintarnya kalian para bangsawan.",
  ui_story_5043_50430401_24_dialog_content = "Saya pikir itu masuk akal karena bulan dan cinta adalah hal yang murni dan indah.",
  ui_story_5043_50430401_25_dialog_content = "Saya yakin itulah yang dipikirkan oleh siapa pun yang merencanakan acara ini.",
  ui_story_5043_50430401_26_dialog_content = "Apa hal untuk mengatakan. Seperti inikah perempuan saat sedang jatuh cinta?",
  ui_story_5043_50430401_27_dialog_content = "Aku bilang aku tidak jatuh cinta! Terserah, berhenti menggodaku, oke?",
  ui_story_5043_50430401_28_dialog_content = "Ngomong-ngomong, sepertinya balonnya ada di atas Halaman Lumopolis, jadi pasti di situlah pestanya.",
  ui_story_5043_50430401_29_dialog_content = "Aduh. Kenapa kita harus berjalan lebih jauh lagi? Kapan Penjaga akan menempatkan gerbong di Stairway to the Skies?",
  ui_story_5043_50430401_30_dialog_content = "Tidak semua orang mampu naik gerbong, lho.",
  ui_story_5043_50430401_31_dialog_content = "Stairway to the Skies adalah rute utama dari Halaman Lumopolis ke Taman Lumopolis.",
  ui_story_5043_50430401_32_dialog_content = "Apakah Anda siap terjun ke dunia rakyat jelata, Matthieu?",
  ui_story_5043_50430401_33_dialog_content = "Diam!",
  ui_story_5043_50430401_34_dialog_content = "<color=#e8d9bb>Halaman Lumopolis, Lapangan Padang Rumput</color>",
  ui_story_5043_50430401_35_dialog_content = "Asyik!",
  ui_story_5043_50430401_36_dialog_content = "Saya tidak tahu Halaman Lumopolis memiliki ruang hijau yang begitu indah. Ini cantik.",
  ui_story_5043_50430401_37_dialog_content = "Saya pikir itu baru dibangun musim semi ini. Mereka menggunakan Luminatics untuk memeliharanya.",
  ui_story_5043_50430401_38_dialog_content = "Hei, kau dengar itu?",
  ui_story_5043_50430401_39_dialog_content = "Sepertinya mereka sedang memainkan musik di tengah alun-alun, tepat di bawah balon.",
  ui_story_5043_50430401_39X1_dialog_content = "Menurut apa yang saya dengar, ada tiga bagian salon: pertemuan, tarian, dan sesi apresiasi puisi.",
  ui_story_5043_50430401_40_dialog_content = "Mm... musik dansa yang cukup standar. Rasa yang mengejutkan bisa diterima.",
  ui_story_5043_50430401_40X1_dialog_content = "Anak muda, apakah ini pertama kalinya Anda menghadiri Moonlight Salon?",
  ui_story_5043_50430401_40X2_dialog_content = "Jangan hanya berdiri saja! Datang datang!",
  ui_story_5043_50430401_40X3_dialog_content = "Hai! Tunggu, jangan tarik aku... Astaga, aku tidak tahan ini!",
  ui_story_5043_50430401_41_dialog_content = "Kita pasti tiba tepat waktu untuk berdansa!",
  ui_story_5043_50430401_42_dialog_content = "Tidak sopan hanya berdiri di satu sisi dengan punggung menempel ke dinding. Mari bergabung dengan mereka dan amati kerumunan seperti yang kita lakukan!",
  ui_story_5043_50430401_43_dialog_content = "T-Tapi... aku tidak tahu apa-apa tentang tarian atau adat istiadat yang mulia!",
  ui_story_5043_50430401_44_dialog_content = "Dan saya memiliki dua kaki kiri.",
  ui_story_5043_50430401_45_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5043_50430401_46_dialog_content = "Jadi... Kenapa aku yang terjebak berdansa dengan orang biasa? Aku merasa sakit!",
  ui_story_5043_50430401_47_dialog_content = "Kau pikir aku menikmati ini?!",
  ui_story_5043_50430401_48_dialog_content = "Aduh!",
  ui_story_5043_50430401_49_dialog_content = "Perhatikan di mana Anda meletakkan kaki Anda, bodoh — aduh!",
  ui_story_5043_50430401_50_dialog_content = "Anda melakukannya dengan sengaja!",
  ui_story_5043_50430401_51_dialog_content = "Hei, apa yang kaulakukan?",
  ui_story_5043_50430401_52_dialog_content = "Hentikan! Jangan tarik rambutku!",
  ui_story_5043_50430401_53_dialog_content = "Ha ha ha! Mereka terlihat seperti sedang bersenang-senang.",
  ui_story_5043_50430401_54_dialog_content = "PlayerName, kamu gugup?",
  ui_story_5043_50430401_55_dialog_content = "Tidak, tidak, aku baik-baik saja.",
  ui_story_5043_50430401_56_dialog_content = "Ke kiri, angkat kakiku, kembali ke kanan, belok...",
  ui_story_5043_50430401_57_dialog_content = "HHH-Bagaimana tanganku memukulmu!?",
  ui_story_5043_50430401_58_dialog_content = "Jangan khawatir, itu hanya tarian persahabatan.",
  ui_story_5043_50430401_59_dialog_content = "Mengapa kita tidak mencobanya lagi?",
  ui_story_5043_50430401_60_dialog_content = "Oke. Aku akan melakukan yang lebih baik kali ini.",
  ui_story_5043_50430401_61_dialog_content = "Ha ha. Bisa kan.",
  ui_story_5043_50430401_62_dialog_content = "Anda cepat belajar.",
  ui_story_5043_50430401_63_dialog_content = "Fiuh! Menari adalah latihan nyata.",
  ui_story_5043_50430401_64_dialog_content = "Aku jadi tidak ingin melakukan ini lagi...",
  ui_story_5043_50430401_65_dialog_content = "Tch, jika aku tidak begitu baik, aku akan menuntutmu.",
  ui_story_5043_50430401_66_dialog_content = "Kemana Loewe menghilang?",
  ui_story_5043_50430401_67_dialog_content = "Sepertinya aku melewatkan semua kesenangan.",
  ui_story_5043_50430401_68_dialog_content = "Saya melihat beberapa karakter mencurigakan di luar sebelumnya. Jelas bukan peserta salon.",
  ui_story_5043_50430401_69_dialog_content = "Saya pergi untuk menyelidiki dan bertemu dengan Lady Carleen.",
  ui_story_5043_50430401_70_dialog_content = "Terima kasih telah menunjukkan jalannya. Dan karakter mencurigakan itu bersamaku, sebenarnya.",
  ui_story_5043_50430401_71_dialog_content = "Wow! Wanita Carleen, kamu juga datang!",
  ui_story_5043_50430401_72_dialog_content = "Apa yang terbaru, Carleen? Adakah kemajuan dalam serangan Eclipsite?",
  ui_story_5043_50430401_73_dialog_content = "Tidak, tapi saya telah menghilangkan beberapa kemungkinan.",
  ui_story_5043_50430401_74_dialog_content = "Semua tiket perjalanan sudah beres, jadi mereka tidak mungkin menyelinap ke Lumopolis dengan menyamar.",
  ui_story_5043_50430401_75_dialog_content = "Nightwatch telah melakukan tugasnya dan tidak ada lubang di perisai di atas Lumopolis.",
  ui_story_5043_50430401_76_dialog_content = "Ada lebih banyak pergerakan barang dan tentara akhir-akhir ini, karena semua festival.",
  ui_story_5043_50430401_77_dialog_content = "Jadi mungkin saja para penjaga belum memeriksa kiriman barang dengan benar dan Eclipsites menyelinap ke sana.",
  ui_story_5043_50430401_78_dialog_content = "Hah? Anda sedang mencari penyusupan Eclipsites?",
  ui_story_5043_50430401_79_dialog_content = "Kalau begitu... Aku harus menemukannya secepat mungkin.",
  ui_story_5043_50430401_80_dialog_content = "Saya pikir Anda tidak perlu khawatir tentang dia. Aku yakin dia sangat aman.",
  ui_story_5043_50430401_81_dialog_content = "S-sungguh...?",
  ui_story_5043_50430401_82_dialog_content = "(Kekhawatiran Tina sepertinya sangat aneh...)",
  ui_story_5043_50430401_83_dialog_content = "Nah, kepala Eclipsite pasti tahu semacam itu <color=#FFB400>keterampilan kamuflase</color> untuk dapat berbaur dengan orang banyak.",
  ui_story_5043_50430401_84_dialog_content = "Saya belum mengotorisasi pencarian penuh karena saya tidak ingin menimbulkan kepanikan.",
  ui_story_5043_50430401_85_dialog_content = "Saya baru saja menempatkan beberapa penjaga dengan pakaian biasa dan mengatakan kepada mereka untuk mengawasi area yang sibuk, untuk berjaga-jaga.",
  ui_story_5043_50430401_86_dialog_content = "Kamu tahu, Carleen, kedengarannya sangat mirip dengan apa yang dilakukan Penguasa Kota dengan kasus Hari Mahkota Bulan.",
  ui_story_5043_50430401_87_dialog_content = "... Saya tidak menganggap itu sebagai pujian.",
  ui_story_5043_50430401_88_dialog_content = "Erm... Maaf. Bagaimana kalau saya minta maaf dengan membantu sedikit?",
  ui_story_5043_50430401_89_dialog_content = "Setidaknya aku bisa memastikan bahwa tidak ada Eclipsites di keramaian di sini..",
  ui_story_5043_50430401_90_option_content = "Force Boost",
  ui_story_5043_50430401_91_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5043_50430401_92_dialog_content = "Dengan baik? Ada yang tidak biasa?",
  ui_story_5043_50430401_93_dialog_content = "Anu…",
  ui_story_5043_50430401_94_dialog_content = "Maaf. Di sini terlalu ramai dan berisik. Ini tidak bekerja.",
  ui_story_5043_50430401_95_dialog_content = "Wanita Carleen! PlayerName! Hai!",
  ui_story_5043_50430401_96_dialog_content = "Jangan hanya berdiri di sana. Kesini!",
  ui_story_5043_50430401_97_dialog_content = "Karena aku sudah disini... mari kita lihat apa yang terjadi.",
  ui_story_5043_50430401_98_dialog_content = "Balon itu sangat mengesankan dari dekat.",
  ui_story_5043_50430401_99_dialog_content = "Wanita Carleen, apakah menurutmu juga begitu?",
  ui_story_5043_50430401_100_dialog_content = "Padang rumput musim semi, pasangan yang saling mencintai, paduan suara bernyanyi di latar belakang...",
  ui_story_5043_50430401_101_dialog_content = "Dan di bawah bulan yang jarang terlihat, semua orang menaiki tangga saat mereka bertukar pemikiran intelektual, terlepas dari kelas mereka ...",
  ui_story_5043_50430401_102_dialog_content = "Mengapa, itu seperti sesuatu dari dongeng.",
  ui_story_5043_50430401_103_dialog_content = "Pikiran intelektual, pantatku. Ini hanyalah festival cinta yang cengeng untuk pasangan yang sedang berkencan.",
  ui_story_5043_50430401_104_dialog_content = "Dan saya belum pernah melihat begitu banyak orang biasa di satu tempat sebelumnya. Tempat itu berbau Lumopolis Bawah. ih.",
  ui_story_5043_50430401_105_dialog_content = "Yah, sudah terlambat sekarang.",
  ui_story_5043_50430401_106_dialog_content = "Hei, orang biasa. Apa yang kamu lihat?",
  ui_story_5043_50430401_107_dialog_content = "Aku hanya berpikir... balon bulan itu agak aneh.",
  ui_story_5043_50430401_108_dialog_content = "Itu tidak ditambatkan ke tanah namun tetap di satu tempat. Saya ingin tahu apakah mereka mengendalikannya dengan Luminatics.",
  ui_story_5043_50430401_109_dialog_content = "Sudahlah. Hanya keprihatinan bodoh dari rakyat jelata biasa. Mengapa repot-repot bertanya apa yang saya pikirkan?",
  ui_story_5043_50430401_110_dialog_content = "Anda benar, Pak. Dan apa lagi...",
  ui_story_5043_50430401_111_dialog_content = "Luminatics juga mempertahankan <color=#FFB400>hadiah dari festival kuno</color> di dalam balon.",
  ui_story_5043_50430401_112_dialog_content = "Maaf, Anda...?",
  ui_story_5043_50430401_113_dialog_content = "Oh, hanya seorang biarawati dari Lumopolis. Kalian cukup memanggilku Kakak.",
  ui_story_5043_50430401_114_dialog_content = "Saya penyelenggara Salon Sinar Bulan ini.",
  ui_story_5043_50430401_115_dialog_content = "Dan aku tidak percaya aku pernah melihatmu di sini sebelumnya. Saya harap Anda menikmatinya.",
  ui_story_5043_50430401_116_dialog_content = "Y-Yah aku belum lama di sini. Semuanya tampak sangat menarik.",
  ui_story_5043_50430401_117_dialog_content = "Tidak terasa seperti Lumopolis yang saya kenal.",
  ui_story_5043_50430401_118_dialog_content = "Heheh. Terima kasih, dan semoga Dewa Cahaya memberkati Anda. Aku akan meninggalkan Anda untuk menikmati diri sendiri.",
  ui_story_5043_50430401_119_dialog_content = "Harap bantu diri Anda sendiri untuk teh dan makanan penutup. Dan jangan lupa untuk menikmati paduan suara.",
  ui_story_5043_50430401_120_dialog_content = "(Paduan suara itu... tolong jangan bilang...)",
  ui_story_5043_50430401_121_dialog_content = "Jadi Anda datang ke pesta di bulan. ♪",
  ui_story_5043_50430401_122_dialog_content = "Tapi itu balon. ♪",
  ui_story_5043_50430401_123_dialog_content = "Kami melihat Anda berkeliaran dan berbaur. ♪",
  ui_story_5043_50430401_124_dialog_content = "Apakah kamu masih lajang? Masih lajang? ♪",
  ui_story_5043_50430401_125_dialog_content = "Melihat? Anak-anak yang lucu.",
  ui_story_5043_50430401_126_dialog_content = "Imut-imut? Seolah olah!",
  ui_story_5043_50430401_127_dialog_content = "Coba tusuk! Fatty meledak! ♪",
  ui_story_5043_50430401_128_dialog_content = "Bergantung di sana, tinggi di atas! ♪",
  ui_story_5043_50430401_129_dialog_content = "Apa yang muncul begitu cepat? ♪",
  ui_story_5043_50430401_130_dialog_content = "Mungkin bangsawan, mungkin balon. ♪",
  ui_story_5043_50430401_131_dialog_content = "Ah, mereka mendapatkan Dawn Paduan suara akademi untuk bernyanyi untuk mereka, ya?",
  ui_story_5043_50430401_132_dialog_content = "Saya melihat mereka tetap dengan gaya mereka yang biasa.",
  ui_story_5043_50430401_133_dialog_content = "Pria dan wanita menggoda di bawah sinar bulan. ♪",
  ui_story_5043_50430401_134_dialog_content = "Bangsawan dan rakyat jelata berbagi meja dan tidak berkelahi. ♪",
  ui_story_5043_50430401_135_dialog_content = "Oh biarawati yang terhormat, biarawati yang baik! ♪",
  ui_story_5043_50430401_136_dialog_content = "Salon Anda pasti menyenangkan! ♪",
  ui_story_5043_50430401_137_dialog_content = "Saya tidak yakin lirik mereka masuk akal, tapi mereka penyanyi yang bagus...",
  ui_story_5043_50430401_138_dialog_content = "Mendengarkan paduan suara selalu membuat saya ingin berdoa.",
  ui_story_5043_50430401_139_dialog_content = "Malam Putih di atas, oh, Dewa Cahaya, izinkan saya untuk menemukannya.",
  ui_story_5043_50430401_140_dialog_content = "Saya tidak sepenuhnya yakin Dewa Cahaya bertanggung jawab atas hal-hal seperti itu ...",
  ui_story_5043_50430401_141_dialog_content = "Semua yang ada di Lumopolis dapat memuji Dewa Cahaya. ♪",
  ui_story_5043_50430401_142_dialog_content = "Tapi seorang bangsawan menikah dengan orang biasa? Itu tidak benar! ♪",
  ui_story_5043_50430401_143_dialog_content = "Oh biarawati yang terhormat, biarawati yang malang! ♪",
  ui_story_5043_50430401_144_dialog_content = "Bencana datang. Anda! Sebaiknya! Berlari! ♪",
  ui_story_5043_50430401_145_dialog_content = "Tunggu apa?!",
  ui_story_5043_50430401_146_dialog_content = "Bersihkan area! Saya ingin semua orang yang menghadiri pertemuan ilegal ini ditangkap.",
  ui_story_5043_50430401_147_dialog_content = "Dan bawakan saya penyelenggara!",
  ui_story_5043_50430401_148_dialog_content = "Eek!",
  ui_story_5043_50430401_149_dialog_content = "Penjaga dari Taman Lumopolis! Berlari!",
  ui_story_5043_50430401_150_dialog_content = "Aku seorang bangsawan dari Uptown. Mereka tidak akan berani...",
  ui_story_5043_50430401_151_dialog_content = "Ehhhh?!",
  ui_story_5043_50430401_152_dialog_content = "Ah! -ku <color=#FFB400>kue</color>!",
  ui_story_5043_50430401_153_dialog_content = "SAYA <color=#FFB400>hilang</color> kue yang akan kuberikan padanya!",
  ui_story_5043_50430401_154_dialog_content = "<color=#e8d9bb>*Kerumunan bergumam*</color>",
  ui_story_5043_50430401_155_dialog_content = "(Ini tidak mungkin. Ini bukan pengawalku!)",
  ui_story_5043_50430401_156_dialog_content = "Saya tidak memberi perintah seperti itu! Siapa berani...",
  ui_story_5043_50430401_157_dialog_content = "Kapten Carleen!",
  ui_story_5043_50430401_158_dialog_content = "Mereka bukan Penjaga dari Taman Lumopolis.",
  ui_story_5043_50430401_159_dialog_content = "Tetapi hanya sedikit bangsawan lain yang memiliki kekuatan seperti itu.",
  ui_story_5043_50430401_160_dialog_content = "Para pengunjung pesta akan menganggap penyerbuan ini telah dipesan oleh Lumopolis Gardens!",
  ui_story_5043_50430401_161_dialog_content = "Saya mengerti apa yang Anda katakan. Tapi kita perlu memulihkan ketertiban terlebih dahulu.",
  ui_story_5043_50430401_162_dialog_content = "Tolong, jangan panik. Ikuti aku!",
  ui_story_5043_50430401_163_dialog_content = "<color=#e8d9bb>Menghancurkan-!</color>",
  ui_story_5043_50430401_164_dialog_content = "(Suara apa itu?!)",
  ui_story_5043_50430401_165_dialog_content = "PlayerName, Whirling Paladin, saya butuh bantuan Anda.",
  ui_story_5043_50430401_166_dialog_content = "Bergabunglah dengan penjaga berpakaian preman saya dan atasi para prajurit ini, siapa pun mereka!",
  ui_story_5043_50430401_167_dialog_content = "Saya senang bisa membantu!",
  ui_story_5043_50430401_168_dialog_content = "Mau mu!",
  ui_story_5043_50430501_1_dialog_content = "Penjaga itu benar-benar lari cepat!",
  ui_story_5043_50430501_2_dialog_content = "Kapten, haruskah aku mengejar?",
  ui_story_5043_50430501_3_dialog_content = "Jangan repot-repot. Anda punya pekerjaan lain yang harus dilakukan.",
  ui_story_5043_50430501_4_dialog_content = "Sayang sekali. Moonlight Salon hancur dan kami tidak menemukan siapa yang kami cari.",
  ui_story_5043_50430501_5_dialog_content = "Oh? Siapa yang kamu cari?",
  ui_story_5043_50430501_6_dialog_content = "Tina ingin menemukan Schwab dan memberinya sesuatu sebagai imbalan atas hadiah Mooncrown Day-nya.",
  ui_story_5043_50430501_7_dialog_content = "Oh, aku tidak tahu mereka berdua memiliki hubungan seperti ini.",
  ui_story_5043_50430501_8_dialog_content = "Jadi itulah kekuatan Mooncrown Day. Kaum muda jatuh cinta tanpa keluarga mereka membuat pengaturan sebelumnya.",
  ui_story_5043_50430501_9_dialog_content = "Tapi... Jika boleh jujur, apa yang dia lihat dari playboy itu?",
  ui_story_5043_50430501_10_dialog_content = "Saya tau...?",
  ui_story_5043_50430501_11_dialog_content = "Hei, apakah ada yang melihat Loewe?",
  ui_story_5043_50430501_12_dialog_content = "Aku belum melihatnya sejak penjaga itu melarikan diri.",
  ui_story_5043_50430501_13_dialog_content = "Saya mengirimnya untuk mencari tahu dari mana mereka berasal. Anda harus terus menyelidiki kasus Anda.",
  ui_story_5043_50430501_14_dialog_content = "Aku punya ide bagus tentang apa yang sudah terjadi. Tapi yang terbaik adalah memastikan.",
  ui_story_5043_50430501_15_dialog_content = "I-Ini tidak baik.",
  ui_story_5043_50430501_16_dialog_content = "Saya tahu saya tahu. Cookie Anda hilang, bukan?",
  ui_story_5043_50430501_17_dialog_content = "Mari kita cari mereka. Mereka mungkin terlibat dengan semua kekacauan ini.",
  ui_story_5043_50430501_18_dialog_content = "Oh, saya berharap itu satu-satunya masalah!",
  ui_story_5043_50430501_19_dialog_content = "Itu adalah patung di pintu masuk alun-alun. Dia...",
  ui_story_5043_50430501_20_dialog_content = "Itu didapat <color=#FFB400>rusak</color> selama semua kekacauan.",
  ui_story_5043_50430501_21_dialog_content = "Apa!?",
  ui_story_5043_50430501_22_dialog_content = "Saya mendengar sesuatu pecah saat semua orang bergegas.",
  ui_story_5043_50430501_23_dialog_content = "Anehnya, itu pecah dengan cara yang persis sama seperti yang terjadi di Hall of Justice.",
  ui_story_5043_50430501_24_dialog_content = "Sepertinya ada pemenggal kepala patung sedang bekerja.",
  ui_story_5043_50430501_25_dialog_content = "Hmm... kupikir kita harus pergi dan melapor ke hakim ketua sementara kita.",
  ui_story_5043_50430501_26_dialog_content = "Ya. Dan jika dia tidak ada di sini di Moonlight Salon, maka dia pasti—",
  ui_story_5043_50430501_27_dialog_content = "<color=#e8d9bb>Taman Lumopolis, Kantor Schwab</color>",
  ui_story_5043_50430501_28_dialog_content = "Mmm... Oke, saya mengerti.",
  ui_story_5043_50430501_29_dialog_content = "Aku senang kau kembali. Saya ingin Anda mengesampingkan kasus patung untuk saat ini, sampai penggugat memperbarui permintaan mereka.",
  ui_story_5043_50430501_30_dialog_content = "Kami punya kasus percintaan baru yang akan dimulai. Jadi bersiaplah, bawahanku tersayang.",
  ui_story_5043_50430501_31_dialog_content = "Itu saja?",
  ui_story_5043_50430501_32_dialog_content = "Inilah kehidupan di Divisi Percintaan. Bergerak terus ke depan, seperti gerbong bertenaga Luminatics.",
  ui_story_5043_50430501_33_dialog_content = "Sangat sulit bagimu untuk mengerti, dandelion kecilku, karena kamu bukan hakim ketua.",
  ui_story_5043_50430501_34_dialog_content = "L-Dandelion kecil ???",
  ui_story_5043_50430501_35_dialog_content = "(Apakah dia baru saja memanggilku dandelion kecil? Sungguh memuakkan.)",
  ui_story_5043_50430501_36_dialog_content = "Anda akan terbiasa dengan itu, PlayerName...",
  ui_story_5043_50430501_37_dialog_content = "Sebenarnya, Ketua Hakim Schwab, Tina memiliki sesuatu yang dia ingin—",
  ui_story_5043_50430501_38_dialog_content = "Saya tidak yakin ini adalah waktu terbaik untuk itu.",
  ui_story_5043_50430501_39_dialog_content = "(Ya. Apa Leyn sedang mengerjakan? Saya tidak punya apa-apa untuk dikatakan kepada Schwab.)",
  ui_story_5043_50430501_40_dialog_content = "Hmm? Sepertinya bawahan saya bekerja sama dengan sangat baik sehingga mereka bahkan memiliki sedikit rahasia dari saya.",
  ui_story_5043_50430501_41_dialog_content = "Bagaimanapun, inilah dakwaan dan semua dokumennya. Semuanya sangat mudah. Sampai jumpa di pengadilan!",
  ui_story_5043_50430501_42_dialog_content = "Dia benar, itu memang terlihat mudah. Dan ini ada hubungannya dengan Moonlight Salon tempat kita berada...",
  ui_story_5043_50430501_43_dialog_content = "Hah? Tunggu sebentar! Semuanya, lihat alasan kasusnya!",
  ui_story_5043_50430501_44_dialog_content = "<color=#e8d9bb>Hall of Justice, Divisi Percintaan</color>",
  ui_story_5043_50430501_45_dialog_content = "Tuan Kota tidak melakukan hal-hal secara setengah-setengah. Lihatlah ukuran tempat ini!",
  ui_story_5043_50430501_46_dialog_content = "Dan mengingat jumlah kasus yang kami tangani pada hari pertama kami, dia juga mendapatkan nilai uang yang baik.",
  ui_story_5043_50430501_47_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50430501_48_dialog_content = "Pengadilan sedang berlangsung!",
  ui_story_5043_50430501_49_dialog_content = "Pertama, izinkan kami memperkenalkan pihak-pihak yang terlibat dalam litigasi hari ini!",
  ui_story_5043_50430501_50_dialog_content = "Penggugat adalah... laki-laki dari Lumopolis Bawah, yang tidak dapat disebutkan namanya karena alasan privasi.",
  ui_story_5043_50430501_51_dialog_content = "Terdakwa adalah... seorang wanita dari Lumopolis Bawah, yang tidak dapat disebutkan namanya karena alasan privasi.",
  ui_story_5043_50430501_52_dialog_content = "(Saya tidak mendengar semua itu!)",
  ui_story_5043_50430501_53_dialog_content = "Saya, Schwab Salar, akan memimpin sebagai hakim ketua dalam persidangan hari ini.",
  ui_story_5043_50430501_54_dialog_content = "Majelis hakim terdiri dari Matthieu Penggergaji, Tina Campbell, dan Leyn...",
  ui_story_5043_50430501_55_dialog_content = "Serta beberapa anggota dewan lainnya.",
  ui_story_5043_50430501_56_dialog_content = "(Wow! Schwab sebenarnya tampak cukup kompeten ketika dia memikirkannya...)",
  ui_story_5043_50430501_57_dialog_content = "Jika tidak ada yang keberatan dengan semua itu, kita dapat melanjutkan.",
  ui_story_5043_50430501_58_dialog_content = "Tunggu sebentar. Kenapa kita semua hanya \"beberapa anggota pengadilan\"?",
  ui_story_5043_50430501_59_dialog_content = "Tidak ada objek? Sangat bagus, mari kita mulai.",
  ui_story_5043_50430501_60_dialog_content = "Jika penggugat dapat menceritakan kembali fakta-fakta kasusnya kepada kita?",
  ui_story_5043_50430501_61_dialog_content = "*Menangis* Inilah yang terjadi...",
  ui_story_5043_50430501_62_dialog_content = "Tunangan saya—terdakwa—dan saya pergi ke Meadow Square di Lumopolis Courtyard untuk Moonlight Salon...",
  ui_story_5043_50430501_63_dialog_content = "T-Tapi dia...",
  ui_story_5043_50430501_64_dialog_content = "Tolong jangan menangis. Katakan saja apa yang terjadi.",
  ui_story_5043_50430501_65_dialog_content = "Aku sangat mencintainya. Kami sudah bersama selama empat tahun! Dia suka minum kopi dengan cokelat dan—",
  ui_story_5043_50430501_66_dialog_content = "Jika Anda dapat tetap berpegang pada hal-hal yang relevan, silakan.",
  ui_story_5043_50430501_67_dialog_content = "M-Maaf. Oh, aku selalu mengacaukan segalanya...",
  ui_story_5043_50430501_68_dialog_content = "Kami pergi ke Moonlight Salon dan bersenang-senang. Tapi kemudian dia tiba-tiba marah dan berkata dia ingin putus denganku!",
  ui_story_5043_50430501_69_dialog_content = "Maksudku... Apa yang akan kukatakan pada keluargaku? *Menangis*",
  ui_story_5043_50430501_70_dialog_content = "Sangat baik. Selanjutnya terdakwa.",
  ui_story_5043_50430501_71_dialog_content = "Saya punya alasan.",
  ui_story_5043_50430501_72_dialog_content = "Pria ini, penggugat, mengajak saya berkencan.",
  ui_story_5043_50430501_73_dialog_content = "Namun berani menerima hadiah dari orang lain!",
  ui_story_5043_50430501_74_dialog_content = "(Dia bertingkah seperti dia penggugat.)",
  ui_story_5043_50430501_75_dialog_content = "aku tidak...",
  ui_story_5043_50430501_76_dialog_content = "Lalu bisakah Anda menjelaskan di mana keranjang itu <color=#FFB400>kue</color> berasal dari?",
  ui_story_5043_50430501_77_dialog_content = "(Cookie? Apakah itu...)",
  ui_story_5043_50430501_78_dialog_content = "Di sana! Itu buktinya!",
  ui_story_5043_50430501_79_dialog_content = "Anda menempatkan mereka di kursi Anda. Dan ada kartu.",
  ui_story_5043_50430501_80_dialog_content = "Dan itu semakin buruk. Siapa pun yang menulis kartu menggunakan hal yang sama <color=#FFB400>nama binatang peliharaan</color> untukmu yang aku lakukan!",
  ui_story_5043_50430501_81_dialog_content = "Oh, aku sudah selesai.",
  ui_story_5043_50430501_82_dialog_content = "Kami benar. Keduanya menemukan cookie itu Tina telah hilang.",
  ui_story_5043_50430501_83_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk!</color>",
  ui_story_5043_50430501_84_dialog_content = "Memesan!",
  ui_story_5043_50430501_85_dialog_content = "Setiap warga Lumopolis yang ditemukan menghina pengadilan akan dihukum mati... Bercanda!",
  ui_story_5043_50430501_86_dialog_content = "<size=32>Hai, Tina. Apakah itu sekeranjang kue yang hilang?</size>",
  ui_story_5043_50430501_87_dialog_content = "<size=32>Eh? Apakah itu PlayerName?</size>",
  ui_story_5043_50430501_88_dialog_content = "<size=32>Anda tidak dapat berbicara dengan saya ketika pengadilan sedang berlangsung!</size>",
  ui_story_5043_50430501_89_dialog_content = "<size=32>Dalam hal itu...</size>",
  ui_story_5043_50430501_90_option_content = "Force Boost!",
  ui_story_5043_50430501_91_dialog_content = "Oh wow! Apakah ini kemampuan Caelestite Anda? Saya selalu bertanya-tanya tentang hal itu.",
  ui_story_5043_50430501_92_dialog_content = "Sudahlah sekarang. Jadi itu cookie Anda, bukan?",
  ui_story_5043_50430501_93_dialog_content = "Ya, mereka milikku! Aku tidak percaya aku telah menyebabkan begitu banyak masalah pada orang-orang yang tidak bersalah ini...",
  ui_story_5043_50430501_94_dialog_content = "PlayerName, menurut Anda apa yang harus saya lakukan?",
  ui_story_5043_50430501_95_option_content = "Jujur",
  ui_story_5043_50430501_96_dialog_content = "Saya pikir Anda harus mengakui apa yang terjadi. Kue-kue itu milik Anda tetapi dimaksudkan untuk diberikan kepada orang lain.",
  ui_story_5043_50430501_97_dialog_content = "Tapi kurasa ini bukan waktu terbaik bagi Schwab untuk mendengar kebenarannya.",
  ui_story_5043_50430501_98_dialog_content = "Jadi saya akan mengerti jika Anda tidak terlalu tertarik pada gagasan itu.",
  ui_story_5043_50430501_99_dialog_content = "Hah? Schwab? Dengar kebenaran apa?",
  ui_story_5043_50430501_100_option_content = "Tunggu dan lihat",
  ui_story_5043_50430501_101_dialog_content = "Saya pikir Anda harus menunggu dan melihat bagaimana hasilnya.",
  ui_story_5043_50430501_102_dialog_content = "Jika Anda mulai berbicara sekarang, Anda berisiko dianggap menghina pengadilan.",
  ui_story_5043_50430501_103_dialog_content = "Jadi apa yang akan dilakukan pengadilan selanjutnya?",
  ui_story_5043_50430501_104_dialog_content = "Selanjutnya kita mendengar argumen dari kedua belah pihak.",
  ui_story_5043_50430501_105_dialog_content = "Saya tidak yakin mengapa PlayerName sangat tertarik. Tapi saya akan membiarkan Schwab melanjutkan kasus ini.",
  ui_story_5043_50430501_106_dialog_content = "Karena penggugat dan tergugat tampaknya sangat ingin melanjutkan, sekarang kita akan mendengar argumen lebih lanjut.",
  ui_story_5043_50430501_107_dialog_content = "<size=32>Dengar, orang biasa! Ini bukan cara untuk pergi tentang hal-hal.</size>",
  ui_story_5043_50430501_108_dialog_content = "<size=32>Kita perlu melakukan sesuatu. Tapi kita tidak bisa mempermalukan Tina.</size>",
  ui_story_5043_50430501_109_dialog_content = "<size=32>Saya setuju. Tapi kami tidak tahu apa Tina ingin dilakukan.</size>",
  ui_story_5043_50430501_110_dialog_content = "<size=32>Dia tidak berbicara untuk dirinya sendiri. Jadi... bagaimana jika kita membantu Schwab mengetahuinya sendiri?</size>",
  ui_story_5043_50430501_111_dialog_content = "<size=32>Tidak buruk, nak! Ide bagus.</size>",
  ui_story_5043_50430501_112_dialog_content = "Sekarang para juri akan memulai dengan pemeriksaan silang.",
  ui_story_5043_50430501_113_dialog_content = "Ahem. Penggugat, Anda mengatakan sekeranjang kue ini bukan milik Anda. Bisakah Anda memberi tahu kami milik siapa?",
  ui_story_5043_50430501_114_dialog_content = "Aku... aku tidak tahu. Tiba-tiba muncul di atas meja di depan saya.",
  ui_story_5043_50430501_115_dialog_content = "Saya hanya bisa berasumsi <color=#FFB400>seseorang meninggalkannya di sana</color>.",
  ui_story_5043_50430501_116_dialog_content = "Jadi Anda akan mengatakan seseorang yang menghadiri Moonlight Salon kehilangan sekeranjang kue?",
  ui_story_5043_50430501_117_dialog_content = "Dan saya yakin kita semua bisa membayangkan untuk apa itu dimaksudkan.",
  ui_story_5043_50430501_118_dialog_content = "Ya. Maksud saya, itu pasti dimaksudkan sebagai a <color=#FFB400>hadiah</color>.",
  ui_story_5043_50430501_119_dialog_content = "Tapi bukan hadiah untukku. Saya tidak ada hubungannya dengan itu.",
  ui_story_5043_50430501_120_dialog_content = "Lalu saya ingin bertanya kepada terdakwa, mengapa anda begitu yakin bahwa kekasih anda tidak setia?",
  ui_story_5043_50430501_121_dialog_content = "Pasti sudah jelas. Siapa pun dapat melihat bahwa sekeranjang kue adalah hadiah dari a <color=#FFB400>wanita</color>.",
  ui_story_5043_50430501_122_dialog_content = "Dia tidak akan berani menerima hadiah seperti itu kecuali dia berencana untuk putus denganku.",
  ui_story_5043_50430501_123_dialog_content = "Dan inilah inti masalahnya. Penggugat bersikeras bahwa dia tidak menerima hadiah apa pun. Anda percaya dia melakukannya.",
  ui_story_5043_50430501_124_dialog_content = "Tapi pesan di <color=#FFB400>kartu</color> jelas dari kekasih...",
  ui_story_5043_50430501_125_dialog_content = "Oh baiklah. Mungkin aku terlalu terburu-buru. Tapi lalu, untuk siapa cookie itu ditujukan?",
  ui_story_5043_50430501_126_dialog_content = "Itu adalah pertanyaan krusial!",
  ui_story_5043_50430501_127_dialog_content = "Dan penerima yang dituju ada di sini!",
  ui_story_5043_50430501_128_dialog_content = "Disini...?",
  ui_story_5043_50430501_129_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk!</color>",
  ui_story_5043_50430501_130_dialog_content = "Hakim Leyn, Hakim Matthieu, tolong jangan membuat pernyataan yang bersifat memimpin kepada terdakwa.",
  ui_story_5043_50430501_131_dialog_content = "Ini adalah pengadilan. Guilty artinya bersalah.",
  ui_story_5043_50430501_132_dialog_content = "Oh, tapi Ketua Hakim Schwab... Kamu sangat tampan, sangat populer di kalangan wanita. Bagaimana Anda tahan mengganggu pelayan yang begitu adil?",
  ui_story_5043_50430501_133_dialog_content = "Dan bukti cinta seorang wanita untukmu ada di sini tapi kamu gagal untuk menyadari siapa wanita itu.",
  ui_story_5043_50430501_134_dialog_content = "Oh! Saya pikir saya mengerti. Maksudmu cookie itu sebenarnya ditujukan untuk—",
  ui_story_5043_50430501_135_dialog_content = "Hah?",
  ui_story_5043_50430501_136_dialog_content = "Memesan!",
  ui_story_5043_50430501_137_dialog_content = "Diam di pengadilan! Saya ingin berbicara.",
  ui_story_5043_50430501_138_dialog_content = "Hakim Tina, Anda tidak dapat mengganggu urusan pengadilan seperti ini!",
  ui_story_5043_50430501_139_dialog_content = "Ketua Hakim Schwab, sebagai pemilik kue bukti, saya ingin membuat a <color=#FFB400>pernyataan saksi</color>.",
  ui_story_5043_50430501_140_dialog_content = "(Attagirl, Tina! Itulah semangat!)",
  ui_story_5043_50430501_141_dialog_content = "O-Oke. Pengadilan setuju. Anda dapat berbicara, saksi.",
  ui_story_5043_50430501_142_dialog_content = "Saya membuat kue.",
  ui_story_5043_50430501_143_dialog_content = "Saya membuatnya sendiri, dengan tangan penuh kasih dan hati yang berdebar.",
  ui_story_5043_50430501_144_dialog_content = "Saya mengocok mentega. Saya menyalurkan desain yang cantik. Saya memanggangnya sampai berwarna kuning keemasan dan memilih yang paling bagus.",
  ui_story_5043_50430501_145_dialog_content = "Semua agar aku bisa memberinya hadiah yang sempurna.",
  ui_story_5043_50430501_146_dialog_content = "Tapi kemudian saya kehilangan semuanya di Moonlight Salon.",
  ui_story_5043_50430501_147_dialog_content = "Dan kartu ini adalah buktinya!",
  ui_story_5043_50430501_148_dialog_content = "Saya membuat kartu itu sendiri. Saya dapat memberi tahu Anda nama di kartu dan semua yang tertulis di atasnya.",
  ui_story_5043_50430501_149_dialog_content = "Oh! Benar-benar? Sungguh aneh kita bertemu seperti ini...",
  ui_story_5043_50430501_150_dialog_content = "Ini seperti kisah cinta yang indah.",
  ui_story_5043_50430501_151_dialog_content = "Aku tidak tahu harus berbuat apa denganmu, cantikku. Kalian semua adalah beban yang menawan untuk kutanggung.",
  ui_story_5043_50430501_152_dialog_content = "Mungkin saksi dan terdakwa bisa membenarkan apa yang tertulis di kartu itu? Maka kita dapat menyimpulkan kasus ini.",
  ui_story_5043_50430501_153_dialog_content = "Oke. Mari kita baca bersama.",
  ui_story_5043_50430501_154_dialog_content = "Ide bagus. Tiga. Dua. Satu!",
  ui_story_5043_50430501_155_dialog_content = "<size=45><color=#FFB400>Toto</color>!</size>",
  ui_story_5043_50430501_X156_dialog_content = "Ha?",
  ui_story_5043_50430501_156_dialog_content = "Apa!?",
  ui_story_5043_50430501_157_dialog_content = "Mengapa, Ketua Hakim Schwab, saya selalu mendengar tentang betapa terkenal dan modisnya Anda.",
  ui_story_5043_50430501_158_dialog_content = "Saya tidak pernah membayangkan Anda akan memiliki nama panggilan kecil yang lucu.",
  ui_story_5043_50430501_159_dialog_content = "Itu membuat Anda tampak tidak terlalu mengintimidasi kami, orang-orang dari Lumopolis Bawah.",
  ui_story_5043_50430501_160_dialog_content = "Sayang, akhirnya aku mendapatkan kembali kepercayaanmu. *Menangis*",
  ui_story_5043_50430501_161_dialog_content = "Toto. hehe. Nama yang lucu.",
  ui_story_5043_50430501_162_dialog_content = "Schwab, apakah itu nama panggilan masa kecil? Sesuatu yang ibumu panggil kamu?",
  ui_story_5043_50430501_163_dialog_content = "Hahahahaha!",
  ui_story_5043_50430501_164_dialog_content = "Tapi ini...",
  ui_story_5043_50430501_165_dialog_content = "Berhenti! Apa yang sebenarnya terjadi!?",
  ui_story_5043_50430501_166_dialog_content = "Ya, apa yang terjadi?",
  ui_story_5043_50430501_167_dialog_content = "Apa hubungan kartu dan cookie dengan Chief Judge Schwab?",
  ui_story_5043_50430601_1_dialog_content = "Jadi... Saya kira itulah yang terjadi.",
  ui_story_5043_50430601_2_dialog_content = "Saya membuat kue untuk Toto. Tapi sepertinya terdakwa salah paham...",
  ui_story_5043_50430601_3_dialog_content = "Aku tidak pernah membayangkan hal seperti ini akan terjadi. Setidaknya kami telah membereskan kesalahpahaman antara dua kekasih.",
  ui_story_5043_50430601_4_dialog_content = "Ha?",
  ui_story_5043_50430601_5_dialog_content = "Mereka bukan satu-satunya yang salah paham.",
  ui_story_5043_50430601_6_dialog_content = "Jadi siapa Toto ini? Kami pikir Anda menyukai ketua juri kami yang idiot!",
  ui_story_5043_50430601_7_dialog_content = "Ya, meskipun itu tidak pernah masuk akal. Tapi di mana kita salah?",
  ui_story_5043_50430601_8_dialog_content = "Ini adalah kesalahanku. Ini situasi yang memalukan jadi aku bersikap sangat kabur.",
  ui_story_5043_50430601_9_dialog_content = "Saya seharusnya menjelaskan semuanya dengan lebih baik sebelum meminta Anda semua untuk membantu.",
  ui_story_5043_50430601_10_dialog_content = "Meskipun saya tidak mengerti bagaimana Anda salah, Schwab.",
  ui_story_5043_50430601_11_dialog_content = "Kami bahkan hampir tidak berbicara selain dari pekerjaan normal dan obrolan sosial.",
  ui_story_5043_50430601_12_dialog_content = "Maksudku, sudah jelas ketika seseorang menyukaimu, bukan? Itu hanya sesuatu yang orang bisa katakan.",
  ui_story_5043_50430601_13_dialog_content = "Cukup. Tolong jangan katakan lagi.",
  ui_story_5043_50430601_14_dialog_content = "Ini semua ... tidak relevan. Hal penting yang dihadapi adalah...",
  ui_story_5043_50430601_15_dialog_content = "<size=45>Semua orang di Hall of Justice mengira nama panggilanku adalah Toto!!!</size>",
  ui_story_5043_50430601_16_dialog_content = "<size=45>Judge Jr. dan para asisten hakim di panel itu pasti sudah memberi tahu semua orang!!!</size>",
  ui_story_5043_50430601_17_dialog_content = "<size=45>Dan segera setiap bangsawan di masyarakat Lumopolis Gardens akan mendengar beritanya!!!</size>",
  ui_story_5043_50430601_18_dialog_content = "<size=45>Dan itu semua karena kamu dan kue-kue bodoh itu dan kartu bodoh itu!!!</size>",
  ui_story_5043_50430601_19_dialog_content = "<size=45>Kalian sekelompok orang bodoh yang kecanduan cinta! Dan wanita bermasalah yang melekat ...</size>",
  ui_story_5043_50430601_20_dialog_content = "<size=45>Kalian semua sama!</size>",
  ui_story_5043_50430601_21_dialog_content = "Aku sangat menyesal!",
  ui_story_5043_50430601_22_dialog_content = "Hai. Tina mungkin telah melakukan kesalahan. Tapi kau terlalu kasar padanya, Schwab.",
  ui_story_5043_50430601_23_dialog_content = "Saya tidak begitu yakin apa yang sedang terjadi. aku lega Tina tidak naksir Schwab sekalipun.",
  ui_story_5043_50430601_24_dialog_content = "...",
  ui_story_5043_50430601_25_dialog_content = "Huh...",
  ui_story_5043_50430601_26_dialog_content = "Oke, mari kita kembali ke bisnis.",
  ui_story_5043_50430601_27_dialog_content = "Patung yang rusak di Halaman Lumopolis tidak ada hubungannya dengan Tuan Byron.",
  ui_story_5043_50430601_28_dialog_content = "Yang beruntung untuk Anda. Saya tidak ingin melihat dia muncul dengan dakwaan baru.",
  ui_story_5043_50430601_29_dialog_content = "Sekarang pergi dan bersiaplah untuk sidang kasus. Ayo, keluar!",
  ui_story_5043_50430601_30_dialog_content = "<color=#e8d9bb>Di luar Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50430601_31_dialog_content = "Ptui!",
  ui_story_5043_50430601_32_dialog_content = "Hei, apakah kamu memperhatikan ekspresi Schwab?",
  ui_story_5043_50430601_33_dialog_content = "Kamu hebat, Tina. Sangat kejam!",
  ui_story_5043_50430601_34_dialog_content = "Heheh. Aku yakin dia tidak pernah punya wanita berbicara dengannya seperti itu sebelumnya.",
  ui_story_5043_50430601_35_dialog_content = "Ah, tolong jangan menggodaku...",
  ui_story_5043_50430601_36_dialog_content = "Saya minta maaf. Aku membuat kita semua dalam masalah.",
  ui_story_5043_50430601_37_dialog_content = "Itu tidak masalah. Tapi yang ingin saya ketahui adalah—",
  ui_story_5043_50430601_38_dialog_content = "Tina, Anda memberi tahu kami bahwa Anda bertemu pria ini di taman di manor Schwab?",
  ui_story_5043_50430601_39_dialog_content = "Jadi kalau bukan Schwab, siapa itu?",
  ui_story_5043_50430601_40_dialog_content = "Oh, kesalahpahaman yang mengerikan ini semua salahku.",
  ui_story_5043_50430601_41_dialog_content = "Biarkan saya mencoba dan menjelaskannya dengan benar ...",
  ui_story_5043_50430601_42_dialog_content = "Saya berada di taman di Salar Manor. Dan saya bertemu dengan Schwab. Dia duduk sendirian, membaca dan minum teh.",
  ui_story_5043_50430601_43_dialog_content = "Dia langsung memperhatikan saya dan terkejut bahwa ada orang yang muncul di tempat terpencil seperti itu.",
  ui_story_5043_50430601_44_dialog_content = "Tetapi ketika dia memperhatikan saya, dia gagal melihat ada tamu tak terduga lainnya di dekatnya.",
  ui_story_5043_50430601_45_dialog_content = "Di semak-semak di belakang Schwab, saya melihat kepala kecil berbulu Toto mencuat dari dedaunan. Dia gemetar saat dia menatapku.",
  ui_story_5043_50430601_46_dialog_content = "Saya pikir dia khawatir saya akan memberikan tempat persembunyiannya. Lagi pula, tidak ada yang menginginkan Eclipsite di pagar mereka.",
  ui_story_5043_50430601_47_dialog_content = "Tapi dia sangat imut dan dia jelas tidak berbahaya. Makhluk malang itu tersesat di taman besar itu.",
  ui_story_5043_50430601_48_dialog_content = "Nyatanya, aku bahkan pernah melihatnya menyikat beberapa lalat dari cangkir teh Schwab. Itu sebelum Schwab melihatku.",
  ui_story_5043_50430601_49_dialog_content = "Setelah Moonlight Salon, saya bergegas kembali ke taman. Saya mengambil tangannya dan membawanya dengan aman keluar dari Salar Manor.",
  ui_story_5043_50430601_50_dialog_content = "Saya harus memakai sarung tangan baru untuk memastikan Lumina dan Darkflow miliknya tidak bertabrakan.",
  ui_story_5043_50430601_51_dialog_content = "Dia bisa mengerti Universese, meski dia hanya bisa mengucapkan beberapa kata dasar. Dan pada Hari Mahkota Bulan, tak lama setelah kami bertemu, saya menerima hadiah darinya.",
  ui_story_5043_50430601_52_dialog_content = "Itu dia. Itulah keseluruhan ceritanya.",
  ui_story_5043_50430601_53_dialog_content = "(Wow. Jadi Eclipsite kecil biasa pun punya nama...)",
  ui_story_5043_50430601_54_dialog_content = "Tunggu sebentar. Bukankah Anda mengatakan sesuatu tentang dia tidak membalas surat Anda?",
  ui_story_5043_50430601_55_dialog_content = "Yah, dia tidak akan punya alamat di Lumopolis, kan? Saya menulis kembali ke alamat pengirim di masa sekarang tetapi tidak pernah mendengar kabar apa pun.",
  ui_story_5043_50430601_56_dialog_content = "Dan Anda bilang Anda tidak punya kesempatan untuk diam-diam bertemu dengannya?",
  ui_story_5043_50430601_57_dialog_content = "Ya. Kami sama sekali tidak bertemu satu sama lain. Saya tidak dapat menemukannya di mana pun.",
  ui_story_5043_50430601_58_dialog_content = "Dan saat kau bilang dia diperhatikan kemanapun dia pergi...",
  ui_story_5043_50430601_59_dialog_content = "Tentunya Anda bisa mengerti itu. Sebuah Eclipsite di Lumopolis pasti akan menimbulkan kepanikan.",
  ui_story_5043_50430601_60_dialog_content = "Jadi... saat kau menyangkal kau sedang jatuh cinta...",
  ui_story_5043_50430601_61_dialog_content = "Eclipsites hidup untuk menyerang Aurorian. Apakah ada yang namanya Eclipsite yang tidak berbahaya?",
  ui_story_5043_50430601_62_dialog_content = "Jika ada, saya ingin melihatnya sendiri.",
  ui_story_5043_50430601_63_dialog_content = "Saya pikir itu semacam perasaan yang tidak perlu, ya. Tapi terlalu aneh untuk menyebutnya cinta.",
  ui_story_5043_50430601_64_dialog_content = "Saya tidak akan membicarakannya dalam istilah romantis. Aku hanya ingin menjaganya.",
  ui_story_5043_50430601_64X1_dialog_content = "Tapi bagaimanapun, aku juga tidak tahan dengan Eclipsites.",
  ui_story_5043_50430601_64X2_dialog_content = "*mengendus*",
  ui_story_5043_50430601_64X3_dialog_content = "Merindukan Tina, Saya tidak mencoba untuk mengingatkan siapa pun, tetapi Anda tampaknya memiliki bau Eclipsite tentang Anda.",
  ui_story_5043_50430601_64X4_dialog_content = "Hah? Anda masih bisa mencium baunya setelah sekian lama...? Maaf...",
  ui_story_5043_50430601_65_dialog_content = "Seperti yang saya katakan sebelumnya, hukum adalah hukum di Lumopolis. Saya tidak bisa membiarkan slide ini.",
  ui_story_5043_50430601_66_dialog_content = "Tidak ada tanda-tanda Eclipsite yang kau sebutkan di lembar penangkapan manapun dari para penjaga.",
  ui_story_5043_50430601_67_dialog_content = "Jadi, haruskah masalah ini dibawa ke kesimpulannya di sini?",
  ui_story_5043_50430601_68_dialog_content = "Oh. Terima kasih, Nyonya Carleen. Dan sebagai bagian dari Balai Kehakiman, saya tahu taruhannya.",
  ui_story_5043_50430601_69_dialog_content = "Bagi orang Aurorian, mengadopsi Eclipsite bukanlah fantasi yang tidak biasa.",
  ui_story_5043_50430601_69X1_dialog_content = "Saya minta maaf telah menyebabkan masalah seperti itu kepada semua orang... Mari kita kembali ke kasus ini dan mencoba yang terbaik untuk menyelidiki lebih lanjut.",
  ui_story_5043_50430601_69X2_dialog_content = "Ini bukan seolah-olah semua yang Anda bawa adalah masalah. Bukankah sesuatu yang menarik terjadi sebagai akibat dari semua ini?",
  ui_story_5043_50430601_70_dialog_content = "Tina, kamu... kamu benar-benar mempermainkan semua orang di Divisi Percintaan untuk orang bodoh.",
  ui_story_5043_50430601_71_dialog_content = "Hahahahaha! Benar! Saya pasti membuat keputusan yang tepat ketika saya memilih untuk bekerja dengan Anda.",
  ui_story_5043_50430601_72_dialog_content = "Saya benar-benar menemukan jauh lebih banyak daripada yang saya harapkan.",
  ui_story_5043_50430601_74_dialog_content = "Ha ha. Yah, kami mungkin tidak membuat banyak kemajuan dengan kasus ini, tetapi cookie saya pasti menimbulkan hiburan.",
  ui_story_5043_50430601_75_dialog_content = "Tetapi! Aku merasakan hal yang sama seperti kalian semua...",
  ui_story_5043_50430601_76_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50430601_77_dialog_content = "Tina!? Tina!",
  ui_story_5043_50430601_78_dialog_content = "Ada apa dengannya... Hei, jangan hanya berdiri di sana, datang dan bantu!",
  ui_story_5043_50430601_79_dialog_content = "Fiuh! Jangan khawatir, dia baru saja tertidur.",
  ui_story_5043_50430601_80_dialog_content = "Ini hari yang sangat menyenangkan. Dia pasti kelelahan.",
  ui_story_5043_50430601_81_dialog_content = "Aku akan menyuruh salah satu pelayanku menjemputnya dengan kereta dan membawanya pulang.",
  ui_story_5043_50430601_82_dialog_content = "Huff Puff. Wanita Carleen...",
  ui_story_5043_50430601_83_dialog_content = "Ah, Loew. Anda harus melakukan yang lebih baik dari ini jika Anda ingin menjadi pelayan Salar.",
  ui_story_5043_50430601_84_dialog_content = "Muntahkan!",
  ui_story_5043_50430601_85_dialog_content = "Wanita Carleen, kamu benar.",
  ui_story_5043_50430601_86_dialog_content = "Para penjaga itu semua mengenakan lambang Troy.",
  ui_story_5043_50430601_87_dialog_content = "Dan ada yang aneh juga dengan Moonlight Salon.",
  ui_story_5043_50430601_88_dialog_content = "Apa?",
  ui_story_5043_50430601_89_dialog_content = "Selalu ada serangan Eclipsite saat salah satu salon itu berakhir.",
  ui_story_5043_50430601_90_dialog_content = "Dan kepala patung di dekatnya selalu hilang.",
  ui_story_5043_50430601_91_dialog_content = "Maaf, hanya itu yang bisa saya ketahui.",
  ui_story_5043_50430601_92_dialog_content = "...",
  ui_story_5043_50430601_93_dialog_content = "Anda telah melakukan pekerjaan hebat, Loewe.",
  ui_story_5043_50430601_94_dialog_content = "Dan Anda akan segera beristirahat. Tapi belum!",
  ui_story_5043_50430702_1_dialog_content = "Karena kita tahu dari mana para penjaga itu berasal, aku tidak bisa membiarkannya begitu saja.",
  ui_story_5043_50430702_2_dialog_content = "PlayerName, saya perlu bertemu dengan Penjaga dan memutuskan apa yang harus dilakukan selanjutnya.",
  ui_story_5043_50430702_3_dialog_content = "Maka saya harus memberi tahu Tuan Kota tentang masalah Eclipsite baru-baru ini.",
  ui_story_5043_50430702_4_dialog_content = "Pergilah. Kami dapat menangani hal-hal di sini.",
  ui_story_5043_50430702_5_dialog_content = "Oke. Aku akan menyusulmu sebelum sidang paling lambat.",
  ui_story_5043_50430702_6_dialog_content = "Hati-hati di jalan.",
  ui_story_5043_50430702_7_dialog_content = "Kita semua mengalami hari yang sibuk. Kita harus pulang dan istirahat.",
  ui_story_5043_50430702_8_dialog_content = "Adapun besok ...",
  ui_story_5043_50430702_9_dialog_content = "Yah, kita semua tahu apa yang perlu kita lakukan, bukan?",
  ui_story_5043_50430702_10_dialog_content = "Saya yakin penyelenggara Moonlight Salons yang aneh itu akan segera diadili.",
  ui_story_5043_50430702_11_dialog_content = "Sepertinya ada sesuatu yang aneh terjadi...",
  ui_story_5043_50430702_12_dialog_content = "Dengar, kenapa kita tidak pergi dan mencari suster itu besok? Yang perlu kita lakukan hanyalah mengikuti balon.",
  ui_story_5043_50430702_13_dialog_content = "Bisakah seseorang memberi tahu saya apa yang terjadi?",
  ui_story_5043_50430702_14_dialog_content = "Dan mengapa Tina tertidur lagi?",
  ui_story_5043_50430702_15_dialog_content = "Ceritanya panjang. Aku akan mengisi Anda dalam perjalanan kembali.",
  ui_story_5043_50430702_16_dialog_content = "Kereta ada di sini. Kami akan mengambil Tina rumah. PlayerName, Leyn, baik, sampai jumpa besok.",
  ui_story_5043_50430702_17_dialog_content = "Eh?",
  ui_story_5043_50430702_18_dialog_content = "Apa?",
  ui_story_5043_50430702_19_dialog_content = "Anda tidak memanggil saya orang biasa sekali pun.",
  ui_story_5043_50430702_20_dialog_content = "Oh, diamlah!",
  ui_story_5043_50430702_21_dialog_content = "<color=#e8d9bb>Keesokan harinya</color>",
  ui_story_5043_50430702_22_dialog_content = "Oh, sekarang aku mengerti.",
  ui_story_5043_50430702_23_dialog_content = "Kamu benar. Saya memilih lokasi untuk Salon Cahaya Bulan kami dengan sangat hati-hati.",
  ui_story_5043_50430702_24_dialog_content = "Saya suka tempat-tempat dengan rasa budaya. Tempat dengan patung sangat ideal.",
  ui_story_5043_50430702_25_dialog_content = "Saya tidak keberatan apakah patung itu orang tua, anak-anak, laki-laki, atau—seperti dua yang rusak—perempuan.",
  ui_story_5043_50430702_26_dialog_content = "Mereka semua adalah blok bangunan peradaban Lumopolis.",
  ui_story_5043_50430702_27_dialog_content = "Tetapi Anda tidak dapat menyangkal bahwa Moonlight Salon tampaknya menyebabkan kerusakan pada patung-patung tersebut.",
  ui_story_5043_50430702_28_dialog_content = "Oh, saya tidak bermaksud menyangkal bahwa ada sedikit kekacauan. Dan jelas saya berada di dekatnya ketika patung-patung itu rusak.",
  ui_story_5043_50430702_29_dialog_content = "Tapi aku bisa bersumpah pada Malam Putih di atas bahwa aku tidak ada hubungannya dengan patung yang rusak atau serangan Eclipsite.",
  ui_story_5043_50430702_30_dialog_content = "(Biarawati ini pasti terlihat dan terdengar tenang dan sama sekali tidak peduli.)",
  ui_story_5043_50430702_31_dialog_content = "(Dan dia memiliki aura yang sangat kuat. Mungkin karena keyakinannya?)",
  ui_story_5043_50430702_32_dialog_content = "(Naluri saya mengatakan bahwa dia tidak ada hubungannya dengan kasus kami.)",
  ui_story_5043_50430702_33_dialog_content = "Tut. Jalan buntu lainnya, dan kurasa kita tidak bisa seenaknya menangkap orang berdasarkan firasat kita.",
  ui_story_5043_50430702_34_dialog_content = "Saudari, jika semua yang Anda katakan itu benar ...",
  ui_story_5043_50430702_35_dialog_content = "Apakah Saudara bersedia menghadiri sidang sebagai saksi?",
  ui_story_5043_50430702_36_dialog_content = "Yah, aku terburu-buru mengatur Moonlight Salons, tapi jika itu yang diinginkan Hall of Justice, maka ya.",
  ui_story_5043_50430702_37_dialog_content = "Saya akan melakukan semua yang saya bisa untuk membantu.",
  ui_story_5043_50430702_38_dialog_content = "Namun…",
  ui_story_5043_50430702_39_dialog_content = "(Bagaimana jika membawanya ke Hall of Justice menyebabkan lebih banyak masalah...)",
  ui_story_5043_50430702_40_dialog_content = "Ya? Nona muda, ada yang ingin kau katakan?",
  ui_story_5043_50430702_41_dialog_content = "Aku hanya ingin tahu bagaimana kamu bisa tetap tenang.",
  ui_story_5043_50430702_42_dialog_content = "Saya tidak keberatan dengan Moonlight Salons. Saya menikmatinya—mereka membuat Lumopolis tampak seperti tempat yang berbeda.",
  ui_story_5043_50430702_43_dialog_content = "Tapi kebiasaan Lumopolis bahkan tidak menerima perceraian. Apalagi cinta bebas.",
  ui_story_5043_50430702_44_dialog_content = "Dan sebagai wanita beriman, seseorang yang jelas sangat taat...",
  ui_story_5043_50430702_45_dialog_content = "Bagaimana Anda memutuskan untuk mengatur salon-salon ini untuk orang-orang Lumopolis?",
  ui_story_5043_50430702_46_dialog_content = "Dan Anda tidak takut menginjakkan kaki di dalam Hall of Justice? Sangat... mengagumkan.",
  ui_story_5043_50430702_47_dialog_content = "Tina...",
  ui_story_5043_50430702_48_dialog_content = "Heheh... Anakku, apakah kamu mungkin bertanya tentang kekhawatiranmu sendiri?",
  ui_story_5043_50430702_49_dialog_content = "Masalahnya, ketika Anda mencapai usia saya, Anda berhenti terlalu khawatir dan terlalu banyak berpikir.",
  ui_story_5043_50430702_50_dialog_content = "Yang saya lakukan hanyalah mendengarkan kehendak Dewa Cahaya.",
  ui_story_5043_50430702_51_dialog_content = "Sepanjang sejarahnya yang panjang, Lumopolis telah mengembangkan sistem etiket yang rumit untuk mengendalikan keinginan kita.",
  ui_story_5043_50430702_52_dialog_content = "Namun awalnya didirikan oleh pria dan wanita biasa. Aurorian yang sederhana dan murni.",
  ui_story_5043_50430702_53_dialog_content = "Selama bertahun-tahun, ajaran Dewa Cahaya ditafsirkan ulang berulang kali.",
  ui_story_5043_50430702_54_dialog_content = "Tapi di hati mereka, ajaran itu sederhana dan baik.",
  ui_story_5043_50430702_55_dialog_content = "Dan itulah berkat sejati Dewa Cahaya. Pelajaran sejatinya.",
  ui_story_5043_50430702_56_dialog_content = "Yang saya lakukan hanyalah membawa Aurorian kembali ke asalnya, ke keinginan mereka yang sebenarnya.",
  ui_story_5043_50430702_57_dialog_content = "Tidak ada dosa dalam hal ini. Itu hanyalah sesuatu yang aturan dan kebiasaan kita tidak mengerti.",
  ui_story_5043_50430702_58_dialog_content = "Keyakinan dan cinta... pada akarnya, mereka adalah satu.",
  ui_story_5043_50430702_59_dialog_content = "Saya rasa saya mengerti. Terima kasih banyak.",
  ui_story_5043_50430702_60_dialog_content = "Lalu aku akan pergi.",
  ui_story_5043_50430702_61_dialog_content = "Dan beri tahu saya jika saya dapat membantu penyelidikan Anda lebih lanjut.",
  ui_story_5043_50430702_62_dialog_content = "Meskipun jika saya dapat menawarkan saran kecil ke Hall of Justice?",
  ui_story_5043_50430702_63_dialog_content = "Oh...?",
  ui_story_5043_50430702_64_dialog_content = "Jika Anda benar-benar ingin mempelajari lebih lanjut sebelum sidang pengadilan dimulai, daripada sekadar menjalani proses Anda...",
  ui_story_5043_50430702_65_dialog_content = "Maka Anda harus berhenti bekerja secara mekanis. Pikirkan tentang apa yang sebenarnya diinginkan penggugat.",
  ui_story_5043_50430702_66_dialog_content = "Terima kasih atas sarannya. Kami akan memikirkan hal ini...",
  ui_story_5043_50430702_67_dialog_content = "Tentu. Itu semuanya. Sampai Lain waktu.",
  ui_story_5043_50430801_1_dialog_content = "<color=#e8d9bb>Hari Berikutnya</color>",
  ui_story_5043_50430801_2_dialog_content = "Apa, ini semua yang kamu temukan?",
  ui_story_5043_50430801_3_dialog_content = "Jadi kau belum memecahkan kasus aslinya, tapi kau berhasil menemukan patung tanpa kepala lainnya!?",
  ui_story_5043_50430801_4_dialog_content = "Saya minta maaf. Kami masih menyelidiki tetapi belum memiliki terobosan sejauh ini...",
  ui_story_5043_50430801_5_dialog_content = "Tidak ada terobosan!? Anda tidak membuat kemajuan sama sekali!",
  ui_story_5043_50430801_6_dialog_content = "Apakah ini yang terbaik yang bisa dilakukan oleh Hall of Justice yang hebat?",
  ui_story_5043_50430801_7_dialog_content = "Saya mungkin juga menyerahkan kasus ini kepada anjing buta. Mungkin itu bisa mengendus penjahat!",
  ui_story_5043_50430801_8_dialog_content = "Saya minta maaf. Kami akan berusaha lebih keras...",
  ui_story_5043_50430801_9_dialog_content = "Saya dapat melihat sekarang bahwa Balai Kehakiman tidak tertarik pada masalah romantis warga negara.",
  ui_story_5043_50430801_10_dialog_content = "Dan \"Divisi Romantis\" ini hanyalah rumah bagi para freeloader!",
  ui_story_5043_50430801_11_dialog_content = "Semua mengambil paket gaji yang montok dan bekerja keras—tidur!",
  ui_story_5043_50430801_12_dialog_content = "Saya tidak dapat menyangkal bahwa kami memiliki karyawan seperti itu.",
  ui_story_5043_50430801_13_dialog_content = "T-Tapi tidur membantuku bekerja lebih baik...",
  ui_story_5043_50430801_14_dialog_content = "Saya kehilangan kesabaran. Sidang dalam dua hari!",
  ui_story_5043_50430801_15_dialog_content = "Saya tidak akan mengatakan apa-apa lagi sekarang. Jika Anda tidak dapat menemukan sesuatu yang baru besok, saya tidak punya pilihan selain terus menuntut tetangga saya.",
  ui_story_5043_50430801_16_dialog_content = "Dan saya akan mengeluh kepada Lady Irridon!",
  ui_story_5043_50430801_17_dialog_content = "Apa gunanya membayar Anda semua begitu banyak jika Anda tidak dapat menyelesaikan masalah kami? Mengapa, Lumopolis akan lebih baik jika kita menghancurkan seluruh bangunan!",
  ui_story_5043_50430801_18_dialog_content = "Menghancurkan?",
  ui_story_5043_50430801_19_dialog_content = "Hei, itu agak kasar, bukan?",
  ui_story_5043_50430801_20_dialog_content = "Tuan Byron, tolong jangan terburu-buru.",
  ui_story_5043_50430801_21_dialog_content = "Hmph. Anda semua harus berbuat lebih baik!",
  ui_story_5043_50430801_22_dialog_content = "D-Dia pergi.",
  ui_story_5043_50430801_23_dialog_content = "Ini tidak bagus. Divisi Percintaan mungkin lebih bermasalah daripada yang kukira.",
  ui_story_5043_50430801_24_dialog_content = "Oh bagus. Kami sudah selesai untuk saat ini.",
  ui_story_5043_50430801_25_dialog_content = "Hakim Ketua Irridon benci umpan balik buruk dari publik. Jika dia mendapat keluhan...",
  ui_story_5043_50430801_26_dialog_content = "Ya, dia akan sangat marah.",
  ui_story_5043_50430801_27_dialog_content = "Dan ini hanya pengaturan sementara. Jika bos memutuskan Divisi Percintaan tidak melakukan tugasnya...",
  ui_story_5043_50430801_28_dialog_content = "Kita bisa kehilangan semua ini.",
  ui_story_5043_50430801_29_dialog_content = "Saya kira saya benar sebelumnya ...",
  ui_story_5043_50430801_30_dialog_content = "Melihat keadaan, Anda benar-benar bisa kehilangan pekerjaan.",
  ui_story_5043_50430801_31_dialog_content = "Kehilangan pekerjaan kita!?",
  ui_story_5043_50430801_32_dialog_content = "Itu tidak boleh terjadi. Dan semuanya tidak seburuk itu!",
  ui_story_5043_50430801_33_dialog_content = "T-Tolong jangan menyarankannya.",
  ui_story_5043_50430801_34_dialog_content = "Jika saya kehilangan pekerjaan, saya akan mati karena bosan tinggal di rumah sepanjang hari. Saya tidak bisa keluar dan bersenang-senang!",
  ui_story_5043_50430801_35_dialog_content = "Tunggu, hanya itu yang kau khawatirkan? Bersenang senang?",
  ui_story_5043_50430801_36_dialog_content = "Di mana saya akan menemukan tempat yang cukup tenang untuk tidur di siang hari?",
  ui_story_5043_50430801_37_dialog_content = "Anda tidak dimaksudkan untuk tidur di tempat kerja!",
  ui_story_5043_50430801_38_dialog_content = "Dan jika saya tidak punya pekerjaan, mereka akan membuat saya pulang.",
  ui_story_5043_50430801_39_dialog_content = "Mereka akan memaksa saya untuk bergabung dengan bisnis keluarga.",
  ui_story_5043_50430801_40_dialog_content = "Ya. Itu keluarga. Tidak ada apa-apa selain sekumpulan orang tua yang membosankan.",
  ui_story_5043_50430801_41_dialog_content = "Siapa di dunia yang ingin duduk di sana membantu mereka menghitung Nightium mereka?",
  ui_story_5043_50430801_42_dialog_content = "Aku bisa melihat kalian para bangsawan tidak perlu aku mengkhawatirkan kalian...",
  ui_story_5043_50430801_43_dialog_content = "Jadi bagaimana jika Anda kehilangan pekerjaan? Kamu akan baik-baik saja! Bergembiralah, semuanya.",
  ui_story_5043_50430801_44_dialog_content = "Ya. Bahkan jika kita kehilangan pekerjaan kita, hidup akan terus berjalan.",
  ui_story_5043_50430801_45_dialog_content = "Meski tanpa gaji... Aku harus membeli kentang dan sayuran.",
  ui_story_5043_50430801_46_dialog_content = "Dan dikurangi menjadi satu kali makan sehari.",
  ui_story_5043_50430801_47_dialog_content = "Tunggu, kenapa keadaan menjadi begitu suram saat kami mendatangimu?",
  ui_story_5043_50430801_48_dialog_content = "Karena kehidupan di Lumopolis suram, itu sebabnya.",
  ui_story_5043_50430801_49_dialog_content = "Membeli makanan, mengikuti masyarakat. Hidup itu tidak gratis, Anda tahu.",
  ui_story_5043_50430801_50_dialog_content = "Jika saya kehilangan gaji, saya harus mulai menghitung setiap sen.",
  ui_story_5043_50430801_51_dialog_content = "Wow. Hidup itu keras...",
  ui_story_5043_50430801_52_dialog_content = "Tapi ini belum waktunya untuk menyerah! Kita masih punya satu hari. Mari manfaatkan dengan baik!",
  ui_story_5043_50430801_53_dialog_content = "Ya. Jika kita benar-benar melakukan sesuatu, kita mungkin membuat beberapa kemajuan.",
  ui_story_5043_50430801_54_dialog_content = "Tetapi masalahnya adalah—kami tidak memiliki satu petunjuk pun untuk diikuti.",
  ui_story_5043_50430801_55_dialog_content = "Jalur penyelidikan apa yang harus kita ambil?",
  ui_story_5043_50430801_56_dialog_content = "Hadirin sekalian... Saya punya ide!",
  ui_story_5043_50430801_57_dialog_content = "Aku sudah memikirkan semuanya. Pendekatan kami terlalu sempit.",
  ui_story_5043_50430801_58_dialog_content = "Kasus pemenggalan patung berantai bukanlah kejahatan biasa.",
  ui_story_5043_50430801_59_dialog_content = "Korbannya adalah patung. Itu berarti kita tidak dapat melihat lingkaran sosial mereka untuk menemukan seseorang dengan motif tertentu.",
  ui_story_5043_50430801_60_dialog_content = "Demikian pula, tidak ada peluang untuk menemukan pelaku di antara anggota keluarga korban.",
  ui_story_5043_50430801_61_dialog_content = "BENAR. Faktor-faktor ini menghambat penyelidikan kami.",
  ui_story_5043_50430801_62_dialog_content = "Tapi mari kita berpikir di luar kotak sejenak.",
  ui_story_5043_50430801_63_dialog_content = "Ada satu faktor krusial yang menyebabkan kerusakan pada patung menjadi kasus di pengadilan ini—",
  ui_story_5043_50430801_64_dialog_content = "<color=#FFB400>Cinta</color>!",
  ui_story_5043_50430801_65_dialog_content = "Ya. Cintalah yang menjadikan ini kasus untuk Divisi Percintaan.",
  ui_story_5043_50430801_66_dialog_content = "Dan ketika cinta terlibat, tidak mungkin lagi mengambil pendekatan yang murni logis.",
  ui_story_5043_50430801_67_dialog_content = "Kami tidak dihadapkan dengan kasus biasa. Ini urusan hati.",
  ui_story_5043_50430801_68_dialog_content = "Oh! Oh! Ini membuat semuanya lebih jelas!",
  ui_story_5043_50430801_69_dialog_content = "Tunggu sebentar. Saya tidak yakin saya mengikuti ...",
  ui_story_5043_50430801_70_dialog_content = "... Bisakah kamu mendengar dirimu sendiri?",
  ui_story_5043_50430801_71_dialog_content = "Kami tidak punya petunjuk. Tapi mungkin kita tidak butuh petunjuk.",
  ui_story_5043_50430801_72_dialog_content = "Teman-teman terkasih, dalam hal cinta tidak perlu memahami segalanya.",
  ui_story_5043_50430801_73_dialog_content = "Yang penting adalah hati.",
  ui_story_5043_50430801_74_dialog_content = "Pikirkan apa yang dikatakan biarawati itu.",
  ui_story_5043_50430801_75_dialog_content = "\"Jika Anda benar-benar ingin mempelajari lebih lanjut sebelum sidang dimulai, daripada hanya melalui proses Anda...",
  ui_story_5043_50430801_76_dialog_content = "Maka Anda harus berhenti bekerja secara mekanis. Pikirkan tentang apa yang sebenarnya diinginkan penggugat.\"",
  ui_story_5043_50430801_77_dialog_content = "Dan kita bisa menyelesaikan kasus ini dengan... hati?",
  ui_story_5043_50430801_78_dialog_content = "Untuk bekerja, teman!",
  ui_story_5043_50430801_79_dialog_content = "Kami akan menemukan jawaban yang dibutuhkan penggugat, dengan cinta!",
  ui_story_5043_50430801_80_dialog_content = "<color=#e8d9bb>Keesokan harinya</color>",
  ui_story_5043_50430801_81_dialog_content = "Hei, kenapa kau menghalangi jalan?",
  ui_story_5043_50430801_82_dialog_content = "Biarkan aku masuk!",
  ui_story_5043_50430801_83_dialog_content = "Mohon tunggu sebentar, Tn. Byron.",
  ui_story_5043_50430801_84_dialog_content = "Para hakim saat ini sibuk di ruang sidang.",
  ui_story_5043_50430801_85_dialog_content = "Kami akan membiarkan Anda lewat segera setelah mereka punya waktu untuk berbicara dengan Anda.",
  ui_story_5043_50430801_86_dialog_content = "Sibuk? Jangan konyol. Mereka sibuk dengan kasusku!",
  ui_story_5043_50430801_87_dialog_content = "Jika mereka ingin bersembunyi dariku, setidaknya mereka bisa memberikan alasan yang lebih baik!",
  ui_story_5043_50430801_88_dialog_content = "Pak Byron, para juri benar-benar...",
  ui_story_5043_50430801_89_dialog_content = "Aku tidak peduli apa yang mereka lakukan. Ini adalah jam kerja pengadilan.",
  ui_story_5043_50430801_90_dialog_content = "S-Tuan, harap tunggu!",
  ui_story_5043_50430801_91_dialog_content = "Menyingkir!",
  ui_story_5043_50430801_92_dialog_content = "Ah, tapi...",
  ui_story_5043_50430801_93_dialog_content = "<size=45>Hakim Matthieu! Dia masuk!!!</size>",
  ui_story_5043_50430801_94_dialog_content = "<color=#e8d9bb>Pop! Pop! Pop!</color>",
  ui_story_5043_50430801_95_dialog_content = "Selamat, Tuan Byron!",
  ui_story_5043_50430801_96_dialog_content = "Aku sangat bahagia untuk kalian berdua!",
  ui_story_5043_50430801_97_dialog_content = "Betapa indahnya bagi Anda untuk dipersatukan kembali dengan cinta sejati Anda pada hari yang biasa-biasa saja ini!",
  ui_story_5043_50430801_98_dialog_content = "Eh? Bukankah...",
  ui_story_5043_50430801_99_dialog_content = "Kami butuh satu hari penuh, tetapi kami membuat patung Anda menjadi kepala baru.",
  ui_story_5043_50430801_100_dialog_content = "Jika kami memiliki sedikit lebih banyak waktu, kami akan membuatnya terlihat lebih baik!",
  ui_story_5043_50430801_101_dialog_content = "Ya. Kami menyadari bahwa kami perlu mengambil pendekatan yang lebih romantis dan ini adalah solusi kami.",
  ui_story_5043_50430801_102_dialog_content = "Pertanyaannya bukanlah apa yang telah hilang dari Anda. Itu yang masih bisa Anda dapatkan.",
  ui_story_5043_50430801_103_dialog_content = "Lagi pula, tentunya kehilangan kepala saja tidak akan menghalangi cintamu?",
  ui_story_5043_50430801_104_dialog_content = "Tidak. Anda masih perlu mencintai. Tapi bisa dimengerti kalau ketidaklengkapannya membuatmu sedih.",
  ui_story_5043_50430801_105_dialog_content = "Dan untuk menghilangkan kesedihan itu dari hatimu, kami harus membuatnya lengkap sekali lagi.",
  ui_story_5043_50430801_106_dialog_content = "Heheh. Sebuah kisah indah tentang kehilangan dan pemulihan...",
  ui_story_5043_50430801_107_dialog_content = "Ka-Kau...",
  ui_story_5043_50430801_108_dialog_content = "<size=45>Apa yang telah kau lakukan!?</size>",
  ui_story_5043_50430801_109_dialog_content = "Benjolan mengerikan apa di leher Galatea itu? Apakah Anda mencoba untuk menghina saya?",
  ui_story_5043_50430801_110_dialog_content = "Ini? Mengerikan?",
  ui_story_5043_50430801_111_dialog_content = "Kamu sepertinya tidak senang...",
  ui_story_5043_50430801_112_dialog_content = "Tut. Aku tahu kita seharusnya tidak memercayai orang biasa dalam hal estetika.",
  ui_story_5043_50430801_113_dialog_content = "Jika Anda tidak senang dengan penampilan barunya, kita bisa membuat...",
  ui_story_5043_50430801_114_dialog_content = "Hentikan! Kalian orang bodoh telah mengolok-olok cintaku!",
  ui_story_5043_50430801_115_dialog_content = "Apa yang akan Anda ketahui tentang cinta sejati !?",
  ui_story_5043_50430801_116_dialog_content = "Cinta itu unik dan benar! Cinta adalah pilihan yang tidak pernah bisa berubah!",
  ui_story_5043_50430801_117_dialog_content = "Dan saat Galatea kehilangan akal, cintaku mati!",
  ui_story_5043_50430801_118_dialog_content = "Bahkan jika Anda dapat membuat replika persis kepalanya, dia tidak akan menjadi Galatea saya!",
  ui_story_5043_50430801_119_dialog_content = "Dia tidak akan menjadi orang yang aku cintai!",
  ui_story_5043_50430801_120_dialog_content = "Ah. Jadi begitu cara kerjanya...",
  ui_story_5043_50430801_121_dialog_content = "Erm, jadi saya salah paham?",
  ui_story_5043_50430801_122_dialog_content = "Kita gagal. Saya kira Divisi Percintaan hancur ...",
  ui_story_5043_50430801_123_dialog_content = "Oh, lupakan semua itu untuk saat ini.",
  ui_story_5043_50430801_124_dialog_content = "Aku punya hal yang lebih penting untuk didiskusikan denganmu.",
  ui_story_5043_50430801_125_dialog_content = "-ku <color=#FFB400>istri</color> berada dalam bahaya besar saat ini.",
  ui_story_5043_50430801_126_dialog_content = "Demi cinta kita, saya mohon Anda mengirim orang untuk melindunginya!",
  ui_story_5043_50430801_127_dialog_content = "T-Tunggu! Istrimu dalam bahaya besar?",
  ui_story_5043_50430801_128_dialog_content = "Bukankah ini istrimu?",
  ui_story_5043_50430801_129_dialog_content = "Tidak, Anda salah. Galatea adalah milikku <color=#FFB400>kekasih</color>!",
  ui_story_5043_50430801_130_dialog_content = "Orang yang berada dalam bahaya fana adalah milikku <color=#FFB400>istri</color>. Mereka bukan orang yang sama.",
  ui_story_5043_50430801_131_dialog_content = "Apa!?",
  ui_story_5043_50430801_132_dialog_content = "Istri Anda dan kekasih Anda adalah orang yang berbeda?",
  ui_story_5043_50430801_133_dialog_content = "Istri saya adalah patung cantik yang berbeda. Dia disebut Aphrodite.",
  ui_story_5043_50430801_134_dialog_content = "Dan apa yang terjadi dengan cinta yang unik dan benar?",
  ui_story_5043_50430801_135_dialog_content = "Tentu saja!",
  ui_story_5043_50430801_136_dialog_content = "Jadi kenapa kamu jatuh cinta dengan dua patung yang berbeda?",
  ui_story_5043_50430801_137_dialog_content = "Cinta juga luas dan menerima.",
  ui_story_5043_50430801_138_dialog_content = "Saya cinta istri saya. Dan aku mencintai kekasihku. Dua cinta yang berbeda dan unik.",
  ui_story_5043_50430801_139_dialog_content = "Pertimbangkan ini. Kau mencintai ibumu, bukan? Dan kamu juga mencintai ayahmu?",
  ui_story_5043_50430801_140_dialog_content = "Saya kira itu masuk akal ...",
  ui_story_5043_50430801_141_dialog_content = "Itu tidak! Itu adalah jenis hubungan yang sangat berbeda.",
  ui_story_5043_50430801_142_dialog_content = "Dengar, aku tidak punya waktu untuk mendidik kalian anak-anak tentang sifat cinta.",
  ui_story_5043_50430801_143_dialog_content = "Saya baru saja melihat balon bulan melayang di atas Stairway to the Skies.",
  ui_story_5043_50430801_144_dialog_content = "Dan di situlah istri saya berada.",
  ui_story_5043_50430801_145_dialog_content = "Kamu pasti sudah tahu kalau balon artinya akan ada Moonlight Salon. Dan Moonlight Salon berarti sebuah patung akan kehilangan kepalanya.",
  ui_story_5043_50430801_146_dialog_content = "Dan jika sesuatu terjadi pada istriku... Aku tidak akan punya siapa-siapa lagi untuk dicintai.",
  ui_story_5043_50430801_147_dialog_content = "Tentunya itu tugas Anda untuk melindungi hak warga negara untuk mencintai?",
  ui_story_5043_50430801_148_dialog_content = "Nah, kami telah menerima kasus Anda. Jadi kurasa kita perlu melindungi cintamu.",
  ui_story_5043_50430801_149_dialog_content = "Tut, atau setengah dari cintanya, setidaknya.",
  ui_story_5043_50430801_150_dialog_content = "Dan ada kemungkinan kami akan menemukan petunjuk baru untuk membantu kasus kami.",
  ui_story_5043_50430801_151_dialog_content = "Kita harus pergi untuk menyelesaikan kasus pemenggalan patung berantai.",
  ui_story_5043_50430801_152_dialog_content = "Jadi tunggu apa lagi? Bergerak!",
  ui_story_5043_50430801_153_dialog_content = "Salon Cahaya Bulan akan segera dimulai!",
  ui_story_5043_50430801_154_dialog_content = "<color=#e8d9bb>Halaman Lumopolis, dekat Stairway to the Skies</color>",
  ui_story_5043_50430801_155_dialog_content = "Ah, kita hampir sampai.",
  ui_story_5043_50430801_156_dialog_content = "Pak Byron bilang istrinya ada di sini. Jadi dia pasti...",
  ui_story_5043_50430801_157_dialog_content = "Mengerti. Pasti yang ini!",
  ui_story_5043_50430801_158_dialog_content = "Oh. Dan masih utuh.",
  ui_story_5043_50430801_159_dialog_content = "Jadi yang perlu kita lakukan hanyalah melindungi patung itu?",
  ui_story_5043_50430801_160_dialog_content = "Ya. Penjahat mungkin mencoba menyerang selama salon.",
  ui_story_5043_50430801_161_dialog_content = "Tapi di mana semua pengunjung salon?",
  ui_story_5043_50430801_162_dialog_content = "Aku melihat mereka. Mereka semua ada di bawah tangga.",
  ui_story_5043_50430801_163_dialog_content = "Jadi mereka. Apakah mereka tidak datang?",
  ui_story_5043_50430801_164_dialog_content = "Ah, ini berarti kita beruntung.",
  ui_story_5043_50430801_165_dialog_content = "Jika salonnya ada di bawah sana, akan lebih mudah melindungi patung di atas sini.",
  ui_story_5043_50430801_166_dialog_content = "Luar biasa. Kita bisa melakukan apa yang diminta Tuan Byron.",
  ui_story_5043_50430801_167_dialog_content = "Oh, saya melihat para juri ada di sini.",
  ui_story_5043_50430801_168_dialog_content = "Saudari! Aku tidak menyangka akan bertemu denganmu lagi secepat ini.",
  ui_story_5043_50430801_169_dialog_content = "Di mana lagi Anda berharap menemukan saya, jika tidak di bawah balon bulan?",
  ui_story_5043_50430801_170_dialog_content = "Dan sekarang Anda di sini, mengapa tidak ikut merayakannya?",
  ui_story_5043_50430801_171_dialog_content = "Apakah salon diadakan di bagian bawah tangga?",
  ui_story_5043_50430801_172_dialog_content = "Kami ingin membantu, tapi kami punya...",
  ui_story_5043_50430801_173_dialog_content = "Oh tidak. Acara hari ini bukan salon.",
  ui_story_5043_50430801_174_dialog_content = "Hah? Terus...",
  ui_story_5043_50430801_175_dialog_content = "<size=45>Apakah semua orang siap?</size>",
  ui_story_5043_50430801_176_dialog_content = "<size=45>Biarkan pawai dimulai!</size>",
  ui_story_5043_50430901_1_dialog_content = "Kami di sini untuk bernyanyi memuji cinta! ♪",
  ui_story_5043_50430901_2_dialog_content = "Di sini, di Lumopolis yang suci! ♪",
  ui_story_5043_50430901_3_dialog_content = "Di sini terlihat semua kekasih! ♪",
  ui_story_5043_50430901_4_dialog_content = "Bernyanyilah untuk memuji keindahan sejati cinta! ♪",
  ui_story_5043_50430901_5_dialog_content = "Kami bernyanyi untuk memuji cinta! ♪",
  ui_story_5043_50430901_6_dialog_content = "Bernyanyilah untuk memuji cinta! ♪",
  ui_story_5043_50430901_7_dialog_content = "Pawai ... berbaris!",
  ui_story_5043_50430901_8_dialog_content = "Wow? Ada kerumunan besar orang yang menaiki tangga.",
  ui_story_5043_50430901_9_dialog_content = "Ini tidak baik, bukan?",
  ui_story_5043_50430901_10_dialog_content = "Ya. Jika mereka melewati patung itu, akan lebih sulit untuk menjaganya tetap aman.",
  ui_story_5043_50430901_11_dialog_content = "Dan jika patung itu rusak lagi di bawah hidung Anda, pekerjaan Anda sama saja dengan hilang.",
  ui_story_5043_50430901_12_dialog_content = "Kita perlu mencari cara untuk menghentikan pawai.",
  ui_story_5043_50430901_13_dialog_content = "Hentikan pawai? Mengapa, apakah kita telah melakukan sesuatu yang salah?",
  ui_story_5043_50430901_14_dialog_content = "Ini membutuhkan banyak pengorganisasian. Anda tidak dapat menghentikannya tanpa alasan yang kuat.",
  ui_story_5043_50430901_15_dialog_content = "Mereka bergerak cepat. Waktu kita tidak lama.",
  ui_story_5043_50430901_16_dialog_content = "Saya akan mencoba dan menghentikan mereka. Anda menjelaskan kepada biarawati!",
  ui_story_5043_50430901_17_dialog_content = "Oh, mengapa rakyat jelata selalu begitu tergesa-gesa...",
  ui_story_5043_50430901_18_dialog_content = "Kakak, dengar. Kami tidak ingin menghentikan pawai.",
  ui_story_5043_50430901_19_dialog_content = "Tapi kita harus. Untuk cinta.",
  ui_story_5043_50430901_20_dialog_content = "Cinta?",
  ui_story_5043_50430901_21_dialog_content = "Seseorang akan menggunakan pawai sebagai kedok untuk melakukan kejahatan.",
  ui_story_5043_50430901_22_dialog_content = "Dan saya yakin Anda tidak ingin acara Anda mendapat reputasi menyebabkan patah hati, bukan?",
  ui_story_5043_50430901_23_dialog_content = "Kami! Memuji! Cinta!",
  ui_story_5043_50430901_24_dialog_content = "Bebas! Cinta!",
  ui_story_5043_50430901_25_dialog_content = "Wow! Tahan, semuanya!",
  ui_story_5043_50430901_26_dialog_content = "Saya pikir kita salah jalan.",
  ui_story_5043_50430901_27_dialog_content = "Kami seharusnya pergi ke distrik perumahan di Halaman Lumopolis!",
  ui_story_5043_50430901_28_dialog_content = "Kita harus berbalik dan kembali.",
  ui_story_5043_50430901_29_dialog_content = "Ya! Kembali!",
  ui_story_5043_50430901_30_dialog_content = "Hah? Kita salah jalan?",
  ui_story_5043_50430901_31_dialog_content = "Itu tidak benar. Kami disuruh mendaki Stairway to the Skies bersama-sama.",
  ui_story_5043_50430901_32_dialog_content = "Kita pasti salah. Mungkin seseorang salah mendengar instruksi.",
  ui_story_5043_50430901_33_dialog_content = "Distrik perumahan?",
  ui_story_5043_50430901_34_dialog_content = "Kudengar itu alun-alun di Halaman Lumopolis!",
  ui_story_5043_50430901_35_dialog_content = "Itu bermil-mil jauhnya! Cepat, ayo berbalik dan pergi!",
  ui_story_5043_50430901_36_dialog_content = "Tepat! Berbalik dan pergi!",
  ui_story_5043_50430901_37_dialog_content = "Kembali? Tapi kita sudah sejauh ini...",
  ui_story_5043_50430901_38_dialog_content = "Ya!",
  ui_story_5043_50430901_39_dialog_content = "Tapi kita dimaksudkan untuk pergi ke distrik perumahan.",
  ui_story_5043_50430901_40_dialog_content = "TIDAK! Ini alun-alun!",
  ui_story_5043_50430901_41_dialog_content = "Tunggu. Saya ingat dengan sangat jelas diberi tahu bahwa kami akan mendaki Stairway to the Skies.",
  ui_story_5043_50430901_42_dialog_content = "Benar! Dan jika tidak, mengapa kita semua bertemu di bawah tangga?",
  ui_story_5043_50430901_43_dialog_content = "Kalian yang mau ke kawasan perumahan atau alun-alun, dapat info dari mana?",
  ui_story_5043_50430901_44_dialog_content = "Seorang pria dengan rambut putih diikat ekor kuda. Dia tampak bisa dipercaya.",
  ui_story_5043_50430901_45_dialog_content = "Seorang pria berpenampilan dapat dipercaya dengan rambut putih diikat ekor kuda.",
  ui_story_5043_50430901_46_dialog_content = "Hei, itu orang yang sama. Anda telah ditipu!",
  ui_story_5043_50430901_47_dialog_content = "Apa?!",
  ui_story_5043_50430901_48_dialog_content = "Hei, itu dia! Lihat, dia punya rambut putih dan kuncir kuda!",
  ui_story_5043_50430901_49_dialog_content = "Apa? Aku? Tidak, aku hanya lewat...",
  ui_story_5043_50430901_50_dialog_content = "Itu dia!",
  ui_story_5043_50430901_51_dialog_content = "Dia yang memberitahuku!",
  ui_story_5043_50430901_52_dialog_content = "Jadi siapa orang asing ini yang mencoba merusak Parade Cinta kita?",
  ui_story_5043_50430901_53_dialog_content = "Bawa dia ke Divisi Percintaan!",
  ui_story_5043_50430901_54_dialog_content = "T-Tidak perlu. Aku tetap pergi ke sana...",
  ui_story_5043_50430901_55_dialog_content = "Ayo! Terus berbaris menaiki tangga!",
  ui_story_5043_50430901_56_dialog_content = "Dan jangan biarkan orang itu pergi.",
  ui_story_5043_50430901_57_dialog_content = "(Sial. Ide cemerlang saya tidak sebaik yang saya harapkan.)",
  ui_story_5043_50430901_58_dialog_content = "(Dan orang-orang telah berangkat lagi. Apa yang harus saya lakukan?)",
  ui_story_5043_50430901_59_dialog_content = "Ya ampun, oh sayang! Saya telah menjatuhkan ember susu dan madu!",
  ui_story_5043_50430901_60_dialog_content = "Ya ampun, betapa kikuknya aku.",
  ui_story_5043_50430901_61_dialog_content = "Apa? Lihatlah semua susu yang mengalir menuruni tangga.",
  ui_story_5043_50430901_62_dialog_content = "Dari mana asalnya?",
  ui_story_5043_50430901_63_dialog_content = "Dan kenapa ada madu yang tercampur di dalam susu!?",
  ui_story_5043_50430901_64_dialog_content = "(I-Itu terlihat seperti salah satu strategi Matthieu yang lebih langsung!)",
  ui_story_5043_50430901_65_dialog_content = "(Itu adalah ide yang aneh tetapi tampaknya berhasil. Orang-orang telah berhenti.)",
  ui_story_5043_50430901_66_dialog_content = "Wow. Segalanya tampak salah hari ini.",
  ui_story_5043_50430901_67_dialog_content = "Kita tidak bisa menyerah. Seperti yang dikatakan Dewa Cahaya, jalan menuju tanah yang diberkati adalah salah satu cobaan dan kesengsaraan!",
  ui_story_5043_50430901_68_dialog_content = "Tepat! Susu dan madu menunjukkan bahwa kita berada di jalan yang benar!",
  ui_story_5043_50430901_69_dialog_content = "Maju terus, semuanya. Tapi hati-hati jangan sampai terpeleset.",
  ui_story_5043_50430901_70_dialog_content = "(Mereka sudah mulai lagi?)",
  ui_story_5043_50430901_71_dialog_content = "(Mereka benar-benar sekelompok yang bertekad...)",
  ui_story_5043_50430901_72_dialog_content = "<size=45>Ahhh!</size>",
  ui_story_5043_50430901_73_dialog_content = "<size=45>Tangganya sangat licin!!!</size>",
  ui_story_5043_50430901_74_dialog_content = "Ada apa?!",
  ui_story_5043_50430901_75_dialog_content = "Saya pikir seseorang jatuh.",
  ui_story_5043_50430901_76_dialog_content = "Huhuuu... sakit banget...",
  ui_story_5043_50430901_77_dialog_content = "Saya melihat bintang-bintang, bahkan jika itu siang hari.",
  ui_story_5043_50430901_78_dialog_content = "S-Dia tampaknya terluka parah.",
  ui_story_5043_50430901_79_dialog_content = "Langkah-langkah ini agak berbahaya sekarang ...",
  ui_story_5043_50430901_80_dialog_content = "Mungkin... kita harus berhenti hari ini?",
  ui_story_5043_50430901_81_dialog_content = "Ya. Kita bisa berparade di tempat lain.",
  ui_story_5043_50430901_82_dialog_content = "Jangan hanya berdiri di sana menghalangi jalan. Temukan seseorang untuk membawa gadis malang ini ke dokter.",
  ui_story_5043_50430901_83_dialog_content = "Mereka mundur!",
  ui_story_5043_50430901_84_dialog_content = "Kinerja Luar Biasa, Tina!",
  ui_story_5043_50430901_85_dialog_content = "Ya, sangat meyakinkan!",
  ui_story_5043_50430901_86_dialog_content = "hehe. Jika saya kehilangan pekerjaan saya di Hall of Justice, mungkin saya akan naik ke panggung.",
  ui_story_5043_50430901_87_dialog_content = "Dan bagaimana dengan trik saya? Pintar, ya?",
  ui_story_5043_50430901_88_dialog_content = "Itu luar biasa. Sempurna.",
  ui_story_5043_50430901_89_dialog_content = "Kalian anak-anak... itu sesuatu yang lain.",
  ui_story_5043_50430901_90_dialog_content = "Tapi karena itu semua untuk melindungi reputasi acara ini, biarlah.",
  ui_story_5043_50430901_91_dialog_content = "Semua cinta layak dilindungi. Bahkan cinta patung.",
  ui_story_5043_50430901_92_dialog_content = "Saya bisa mengerti mengapa Anda menjalankan salon Anda. Terima kasih sudah begitu pengertian, Kakak.",
  ui_story_5043_50430901_93_dialog_content = "Saya harus pergi. Saya akan mengarahkan orang-orang pawai ke arah yang berbeda.",
  ui_story_5043_50430901_94_dialog_content = "Dan kami juga akan melakukan yang terbaik dalam pekerjaan kami.",
  ui_story_5043_50430901_95_dialog_content = "Oh tidak! Semuanya, berhenti!",
  ui_story_5043_50430901_96_dialog_content = "Kita harus kembali ke tangga!",
  ui_story_5043_50430901_97_dialog_content = "Apa yang sedang terjadi? Ada semacam keributan!",
  ui_story_5043_50430901_98_dialog_content = "Gerhana! Dari mana mereka berasal!?",
  ui_story_5043_50430901_99_dialog_content = "Cepat! Naik tangga!",
  ui_story_5043_50430901_100_dialog_content = "Apa? Dari mana datangnya Eclipsites ini?",
  ui_story_5043_50430901_101_dialog_content = "Aku melihat mereka! Hanya beberapa, meskipun.",
  ui_story_5043_50430901_102_dialog_content = "Leyn sudah menangani mereka!",
  ui_story_5043_50430901_103_dialog_content = "Ayo bantu dia, stat!",
  ui_story_5043_50430901_104_dialog_content = "Jangan lupakan patungnya! Kerumunan itu akan menyerbu melewati.",
  ui_story_5043_50430901_105_dialog_content = "Itu hanya beberapa Eclipsites. Satu orang tambahan sudah cukup.",
  ui_story_5043_50430901_106_dialog_content = "Tina, Anda pergi membantu Leyn. Semua orang tinggal di sini dengan patung itu.",
  ui_story_5043_50430901_107_dialog_content = "Saya akan menggunakan kemampuan psikis saya untuk membantu Anda melawan Eclipsites, Tina.",
  ui_story_5043_50430901_108_dialog_content = "Oke, kedengarannya bagus.",
  ui_story_5043_50430901_109_dialog_content = "Kalian pastikan kalian merawat patung itu!",
  ui_story_5043_50431001_1_dialog_content = "Itu yang terakhir di sana!",
  ui_story_5043_50431001_2_dialog_content = "Serahkan padaku!",
  ui_story_5043_50431001_3_dialog_content = "Oke. Itu semua tentang Eclipsites yang ditangani.",
  ui_story_5043_50431001_4_dialog_content = "Tapi... sepertinya semua orang berlari menaiki tangga.",
  ui_story_5043_50431001_5_dialog_content = "bagaimana ya PlayerName dan yang lainnya lakukan.",
  ui_story_5043_50431001_6_dialog_content = "Hai! Hati-hati semuanya!",
  ui_story_5043_50431001_7_dialog_content = "Ada patung yang sangat berharga di sini. Anda memecahkannya, Anda membelinya!",
  ui_story_5043_50431001_8_dialog_content = "Gerhana! Apa yang kamu tunggu!? Berlari!",
  ui_story_5043_50431001_9_dialog_content = "Semua orang bisa berhenti panik! Eclipsites telah ditangani!",
  ui_story_5043_50431001_10_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431001_11_dialog_content = "Ada apa?!",
  ui_story_5043_50431001_12_dialog_content = "Oh tidak! Seseorang menabrak patung itu!",
  ui_story_5043_50431001_13_dialog_content = "Syukurlah sepertinya tidak rusak.",
  ui_story_5043_50431001_14_dialog_content = "Ahhhhhhh!",
  ui_story_5043_50431001_15_dialog_content = "Mereka datang kembali!",
  ui_story_5043_50431001_16_dialog_content = "Matthieu, Hentikan mereka!",
  ui_story_5043_50431001_17_dialog_content = "Tentu, tapi bagaimana...",
  ui_story_5043_50431001_18_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431001_19_dialog_content = "Aduh!",
  ui_story_5043_50431001_20_dialog_content = "Kau baik-baik saja?",
  ui_story_5043_50431001_21_dialog_content = "Bagaimana kalau Anda membantu saya daripada mengajukan pertanyaan bodoh?",
  ui_story_5043_50431001_22_dialog_content = "Omong kosong! Ada Eclipsites di keramaian!",
  ui_story_5043_50431001_23_dialog_content = "Eclipsite?!",
  ui_story_5043_50431001_24_dialog_content = "Kamu benar. Saya dapat melihat beberapa dari mereka.",
  ui_story_5043_50431001_25_dialog_content = "Dari mana mereka berasal?",
  ui_story_5043_50431001_26_dialog_content = "Jangan panik! Aku akan sepatu mereka sampai mati!",
  ui_story_5043_50431001_27_dialog_content = "Bisakah Anda membunuh Eclipsite dengan sepatu?",
  ui_story_5043_50431001_28_dialog_content = "Tunggu! Itu akan mengenai patung itu!",
  ui_story_5043_50431001_29_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431001_30_dialog_content = "Kuharap Tn. Byron tidak keberatan dengan sedikit jejak kaki...",
  ui_story_5043_50431001_31_dialog_content = "Saya akan membantu! Menonton ini!",
  ui_story_5043_50431001_32_dialog_content = "Apa!? Yang lainnya?",
  ui_story_5043_50431001_33_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431001_34_dialog_content = "Hei, apakah patung itu baik-baik saja?",
  ui_story_5043_50431001_35_dialog_content = "Tampaknya baik-baik saja untuk saat ini, tetapi jika ini terus berlanjut ...",
  ui_story_5043_50431001_36_dialog_content = "Berhenti melempar sepatu. Anda bahkan tidak merusak patung!",
  ui_story_5043_50431001_37_dialog_content = "Apalagi mengalahkan Eclipsites!",
  ui_story_5043_50431001_38_dialog_content = "Dia benar. Apakah kita punya senjata yang lebih baik?",
  ui_story_5043_50431001_39_dialog_content = "Saya bersedia! Beberapa keju. Sangat keras!",
  ui_story_5043_50431001_40_dialog_content = "Orang macam apa yang membawa keju kemana-mana!?",
  ui_story_5043_50431001_41_dialog_content = "Oh tidak. Jika keju mengenai patung maka mungkin...",
  ui_story_5043_50431001_42_dialog_content = "Semuanya, tenanglah! Saya berkata, tenanglah! Berhenti melempar barang.",
  ui_story_5043_50431001_43_dialog_content = "Saya tidak ingin melihat lemparan lagi!",
  ui_story_5043_50431001_44_dialog_content = "Kakak!",
  ui_story_5043_50431001_45_dialog_content = "Semua orang berhenti melempar barang. Kita mungkin memukul Suster.",
  ui_story_5043_50431001_46_dialog_content = "Fiuh... Saya pikir kita telah menghindari bencana.",
  ui_story_5043_50431001_47_dialog_content = "Terima kasih, Suster.",
  ui_story_5043_50431001_48_dialog_content = "Tidak apa. Saya hanya melakukan tugas saya.",
  ui_story_5043_50431001_49_dialog_content = "Saya tidak bisa membiarkan acara bertema Mooncrown Day kami mendapatkan reputasi merusak cinta orang-orang!",
  ui_story_5043_50431001_50_dialog_content = "(Yah, mengingat bagaimana dia melindungi patung itu, kupikir kita bisa mengeliminasi dia dari penyelidikan kita.)",
  ui_story_5043_50431001_51_dialog_content = "Kerumunan akhirnya bubar.",
  ui_story_5043_50431001_52_dialog_content = "Sepertinya kita bisa santai.",
  ui_story_5043_50431001_53_dialog_content = "Ya.",
  ui_story_5043_50431001_54_dialog_content = "Kerumunan yang menyerbu itu lebih menakutkan daripada Eclipsites.",
  ui_story_5043_50431001_55_dialog_content = "Tentu saja. Jika aku tahu aku akan pergi dengan Tina.",
  ui_story_5043_50431001_56_dialog_content = "Hai! Mengapa Anda hanya berdiri di sana?",
  ui_story_5043_50431001_57_dialog_content = "Leyn, kamu kembali!",
  ui_story_5043_50431001_58_dialog_content = "Di belakangmu!",
  ui_story_5043_50431001_59_dialog_content = "Ada Eclipsites di belakang Anda!",
  ui_story_5043_50431002_1_dialog_content = "Eclipsites ini benar-benar tahu cara menyelinap ke orang-orang.",
  ui_story_5043_50431002_2_dialog_content = "Tapi mereka tidak bisa bertahan untuk pertarungan yang bagus.",
  ui_story_5043_50431002_3_dialog_content = "Jangan santai dulu. Masih ada beberapa yang tersisa.",
  ui_story_5043_50431002_4_dialog_content = "Ayo, mari habisi mereka.",
  ui_story_5043_50431002_5_dialog_content = "Tunggu!",
  ui_story_5043_50431002_6_dialog_content = "PlayerName, di samping Anda...",
  ui_story_5043_50431002_7_dialog_content = "Disampingku?",
  ui_story_5043_50431002_8_dialog_content = "Itu…",
  ui_story_5043_50431002_9_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5043_50431002_10_dialog_content = "Oh tidak! Patung...",
  ui_story_5043_50431002_11_dialog_content = "Siapa yang melakukan ini!?",
  ui_story_5043_50431002_12_dialog_content = "Aku punya tangan perusak!",
  ui_story_5043_50431002_13_dialog_content = "Cepat, tarik dia keluar dari tumpukan Eclipsites.",
  ui_story_5043_50431002_14_dialog_content = "Menyingkir! Anda semua menghalangi saya.",
  ui_story_5043_50431002_15_dialog_content = "Hah? Tidak ada orang di sini.",
  ui_story_5043_50431002_16_dialog_content = "Maaf. Dia lolos.",
  ui_story_5043_50431002_17_dialog_content = "Dia menyelinap keluar dari sarung tangannya dan melarikan diri. Seperti kadal yang meninggalkan ekornya...",
  ui_story_5043_50431002_18_dialog_content = "Ini mengerikan. Patung itu rusak tepat di bawah hidungku!",
  ui_story_5043_50431002_19_dialog_content = "Bagaimana saya akan menjelaskan ini?",
  ui_story_5043_50431002_20_dialog_content = "Yah... setidaknya kita punya sarung tangan pelakunya, kan?",
  ui_story_5043_50431002_21_dialog_content = "Itu petunjuk yang berharga.",
  ui_story_5043_50431002_22_dialog_content = "Saya kira kita bisa menyebutnya sebagai terobosan dalam penyelidikan kita.",
  ui_story_5043_50431002_23_dialog_content = "Tapi... Saya rasa Tuan Byron tidak akan melihatnya seperti itu.",
  ui_story_5043_50431002_24_dialog_content = "Hei, di mana Tina?",
  ui_story_5043_50431002_25_dialog_content = "Aku pikir dia bersamamu, Leyn?",
  ui_story_5043_50431002_26_dialog_content = "Saya kira dia tertinggal saat saya bergegas kembali.",
  ui_story_5043_50431002_27_dialog_content = "Hai? Apakah kalian semua baik-baik saja?",
  ui_story_5043_50431002_28_dialog_content = "Maaf, saya bertemu beberapa Eclipsites lagi saat menaiki tangga.",
  ui_story_5043_50431002_29_dialog_content = "Tunggu, patung itu... dimana kepalanya!?",
  ui_story_5043_50431002_30_dialog_content = "Huh...",
  ui_story_5043_50431002_31_dialog_content = "Ayo. Ayo kembali dan laporkan.",
  ui_story_5043_50431002_32_dialog_content = "<color=#e8d9bb>Balai Kehakiman, Taman Lumopolis</color>",
  ui_story_5043_50431002_33_dialog_content = "<size=45>Istriku! Istriku!</size>",
  ui_story_5043_50431002_34_dialog_content = "<size=45>Aphrodite sayangku!</size>",
  ui_story_5043_50431002_35_dialog_content = "...",
  ui_story_5043_50431002_36_dialog_content = "Kita sudah mati.",
  ui_story_5043_50431002_37_dialog_content = "Bagaimana... Mengapa ini harus terjadi?",
  ui_story_5043_50431002_38_dialog_content = "Saya sangat mencintaimu. Dan aku melakukan semua yang aku bisa untuk melindungimu.",
  ui_story_5043_50431002_39_dialog_content = "Namun... cintaku telah dicuri dariku...",
  ui_story_5043_50431002_40_dialog_content = "Mengapa saya tidak bisa menyelamatkan patung kesayangan saya? Bahkan tidak satu pun dari mereka...",
  ui_story_5043_50431002_41_dialog_content = "Saya tahu apa yang terjadi dan mengerti bagaimana perasaan Anda, Tuan Byron.",
  ui_story_5043_50431002_42_dialog_content = "Anda? Kamu mengerti?",
  ui_story_5043_50431002_43_dialog_content = "Anda tidak mengerti apa-apa!",
  ui_story_5043_50431002_44_dialog_content = "Tidak ada yang tersisa di dunia ini yang layak untuk cintaku!",
  ui_story_5043_50431002_45_dialog_content = "Oh God of Light, kenapa kau menghukumku seperti ini...",
  ui_story_5043_50431002_46_dialog_content = "Mungkin jika Anda tenang.",
  ui_story_5043_50431002_47_dialog_content = "Lagipula, apa yang sudah selesai sudah selesai.",
  ui_story_5043_50431002_48_dialog_content = "Tapi kami akan memastikan Anda mendapatkan keadilan.",
  ui_story_5043_50431002_49_dialog_content = "Ha. Hall of Justice tidak bisa membantu!",
  ui_story_5043_50431002_50_dialog_content = "Jika Balai Kehakiman dapat melakukan tugasnya, maka istri saya tidak akan mengalami nasib ini!",
  ui_story_5043_50431002_51_dialog_content = "Jangan pedulikan fakta bahwa tiga hakim Anda gagal menemukan pelakunya! Anda bahkan tidak bisa melindungi satu patung pun!",
  ui_story_5043_50431002_52_dialog_content = "Tunggu saja sampai Hakim Ketua Irridon mendengar kesuksesan besar Anda!",
  ui_story_5043_50431002_53_dialog_content = "Saya yakin dia tidak akan membiarkan satu divisi yang penuh dengan ketidakmampuan merusak nama baik Balai Kehakiman!",
  ui_story_5043_50431002_54_dialog_content = "Saya sangat menyesal kami sangat mengecewakan Anda, Tn. Byron.",
  ui_story_5043_50431002_55_dialog_content = "Kami tidak dapat melindungi patung atau menangkap pelakunya di tempat kejadian.",
  ui_story_5043_50431002_56_dialog_content = "Tapi... kami bisa mendapatkan sarung tangan yang dipakai pelakunya.",
  ui_story_5043_50431002_57_dialog_content = "Ya ampun! Jadi istriku telah kehilangan kepalanya yang cantik, dan sebagai imbalannya, kau punya sarung tangan?",
  ui_story_5043_50431002_58_dialog_content = "Tentunya Anda tidak berpikir ini adalah pertukaran yang berharga.",
  ui_story_5043_50431002_59_dialog_content = "Berapa banyak orang yang tinggal di Lumopolis? Berapa pasang sarung tangan yang mereka miliki?",
  ui_story_5043_50431002_60_dialog_content = "Dan apa yang akan Anda lakukan dengan sarung tangan ini, mengingat betapa tidak kompetennya seluruh Divisi Percintaan?",
  ui_story_5043_50431002_61_dialog_content = "Tuan Byron, tolong jangan bubarkan seluruh Divisi Percintaan karena kegagalan beberapa karyawan.",
  ui_story_5043_50431002_62_dialog_content = "Para juri tidak bekerja dengan baik. Tapi sebagai hakim ketua, saya memastikan bahwa setiap kasus mencapai kesimpulan yang adil.",
  ui_story_5043_50431002_63_dialog_content = "Kesimpulan yang adil? Simpan kata-kata cantik untuk Hakim Ketua Irridon!",
  ui_story_5043_50431002_64_dialog_content = "Kekasih dan istri saya telah rusak. Dan pihak yang bersalah tetap bebas.",
  ui_story_5043_50431002_65_dialog_content = "Kamu menyebut ini keadilan!?",
  ui_story_5043_50431002_66_dialog_content = "Belum, Tuan Byron. Tapi jangan terlalu terburu-buru.",
  ui_story_5043_50431002_67_dialog_content = "Pelakunya tidak lolos sampai palu jatuh.",
  ui_story_5043_50431002_68_dialog_content = "Oh, menurutmu kau bisa menangkap penjahatnya sebelum kasusnya selesai?",
  ui_story_5043_50431002_69_dialog_content = "Hakim Leyn, tolong tunjukkan sarung tangannya.",
  ui_story_5043_50431002_70_dialog_content = "Tentu saja.",
  ui_story_5043_50431002_71_dialog_content = "Ini adalah sarung tangan yang diambil dari tangan pelaku di TKP. Apakah itu benar?",
  ui_story_5043_50431002_72_dialog_content = "Dia. Saya hampir menangkap pelakunya, tetapi dia melarikan diri dengan menyelinap keluar dari sarung tangan.",
  ui_story_5043_50431002_73_dialog_content = "Yang membuat segalanya sederhana. Siapa pun yang memiliki sarung tangan itu melepas kepala patung itu.",
  ui_story_5043_50431002_74_dialog_content = "Dan seperti yang terjadi, orang-orang saya telah menemukan <color=#FFB400>sarung tangan lainnya</color>.",
  ui_story_5043_50431002_75_dialog_content = "Seperti yang akan Anda lihat, kedua sarung tangan itu sepasang.",
  ui_story_5043_50431002_76_dialog_content = "Sarung tangan lainnya!?",
  ui_story_5043_50431002_77_dialog_content = "?!",
  ui_story_5043_50431002_78_dialog_content = "Tapi bagaimana caranya!?",
  ui_story_5043_50431002_79_dialog_content = "Di mana Anda menemukannya? Dan milik siapa itu?",
  ui_story_5043_50431002_80_dialog_content = "Dan sekarang kami memiliki sarung tangan, kami dapat dengan mudah membawa kasus ini ke kesimpulan yang adil.",
  ui_story_5043_50431002_81_dialog_content = "Penjaga! Berdiri siap!",
  ui_story_5043_50431002_82_dialog_content = "Dan tangkap... Tina Campbell!",
  ui_story_5043_50431002_83_dialog_content = "Apa? Menangkap Tina?",
  ui_story_5043_50431002_84_dialog_content = "Siap, Pak!",
  ui_story_5043_50431101_1_dialog_content = "Tunggu! Ini tidak benar.",
  ui_story_5043_50431101_2_dialog_content = "Bagaimana bisa Tina!",
  ui_story_5043_50431101_3_dialog_content = "Aku tahu. Itu tidak mungkin.",
  ui_story_5043_50431101_4_dialog_content = "Apakah Anda semacam idiot, Ketua Hakim Schwab?",
  ui_story_5043_50431101_5_dialog_content = "Anda menilai kurang penilaian. Bukankah saya sudah menjelaskan alasan saya dengan sangat jelas?",
  ui_story_5043_50431101_6_dialog_content = "Pemilik sarung tangan yang dikumpulkan oleh Hakim Leyn adalah pelakunya. Itu jelas.",
  ui_story_5043_50431101_7_dialog_content = "Dan setelah insiden terbaru ini, orang-orang saya dapat dengan cepat mengidentifikasi separuh pasangan lainnya.",
  ui_story_5043_50431101_8_dialog_content = "Dan ditemukan... di laci meja Hakim Tina.",
  ui_story_5043_50431101_9_dialog_content = "Apa!?",
  ui_story_5043_50431101_10_dialog_content = "Tina, apakah ini sarung tanganmu?",
  ui_story_5043_50431101_11_dialog_content = "Aku... Aku punya sepasang sarung tangan seperti itu.",
  ui_story_5043_50431101_12_dialog_content = "Tapi saya tidak mengerti bagaimana mereka muncul di tempat kejadian ...",
  ui_story_5043_50431101_13_dialog_content = "Hakim Tina, saya tidak yakin Anda mengerti betapa seriusnya situasi Anda.",
  ui_story_5043_50431101_14_dialog_content = "Mengingat Anda adalah tersangka utama kami, Anda harus memberi tahu kami bagaimana sarung tangan itu ada di sana.",
  ui_story_5043_50431101_15_dialog_content = "Dan saya tidak akan pernah mengharapkan hal kecil yang cantik seperti Anda untuk melakukan kejahatan kejam seperti itu.",
  ui_story_5043_50431101_16_dialog_content = "Ah, tragedi itu semua...",
  ui_story_5043_50431101_17_dialog_content = "Hai! Berhenti memfitnah miskin Tina!",
  ui_story_5043_50431101_18_dialog_content = "Tina bersama kami ketika semuanya terjadi. Melawan Eclipsite!",
  ui_story_5043_50431101_19_dialog_content = "Kita semua bisa memberinya alibi. Dia tidak bisa menjadi pelakunya!",
  ui_story_5043_50431101_20_dialog_content = "Leyn, ingatlah bahwa Anda harus bertanggung jawab atas pernyataan Anda sebagai hakim.",
  ui_story_5043_50431101_21_dialog_content = "Saya yakin Anda tidak membutuhkan saya untuk memberi tahu Anda hukuman untuk sumpah palsu.",
  ui_story_5043_50431101_22_dialog_content = "Tapi dia benar! Dan saya bisa membuktikannya!",
  ui_story_5043_50431101_23_dialog_content = "Benar-benar? Pikirkan baik-baik, kalian semua.",
  ui_story_5043_50431101_24_dialog_content = "Saat kejadian itu terjadi, adalah Hakim Tina sebenarnya di sisimu dalam perang melawan Eclipsites?",
  ui_story_5043_50431101_25_dialog_content = "Dia...",
  ui_story_5043_50431101_26_dialog_content = "Hei, di mana Tina?",
  ui_story_5043_50431101_27_dialog_content = "Aku pikir dia bersamamu, Leyn?",
  ui_story_5043_50431101_28_dialog_content = "Saya kira dia tertinggal saat saya bergegas kembali.",
  ui_story_5043_50431101_29_dialog_content = "Hai? Apakah kalian semua baik-baik saja?",
  ui_story_5043_50431101_30_dialog_content = "(Oh tidak... Dia benar-benar tidak bersama kami selama pertarungan!)",
  ui_story_5043_50431101_31_dialog_content = "Sepertinya kamu mengerti sekarang.",
  ui_story_5043_50431101_32_dialog_content = "Saat bersaksi di bawah sumpah, sangat penting bagi kita untuk memperhatikan setiap kata yang diucapkan.",
  ui_story_5043_50431101_33_dialog_content = "Jika Anda tidak dapat memahami konsep dasar seperti ini, saya khawatir Anda tidak akan pernah menjadi hakim yang layak di Balai Kehakiman.",
  ui_story_5043_50431101_34_dialog_content = "...",
  ui_story_5043_50431101_35_dialog_content = "Bagaimanapun, pelakunya telah ditangkap, jadi mari kita akhiri proses lucu hari ini.",
  ui_story_5043_50431101_36_dialog_content = "Apakah Anda puas dengan hasil kami hari ini, Tn. Byron?",
  ui_story_5043_50431101_37_dialog_content = "Saya tidak akan pernah berharap seorang hakim menjadi penyebab di balik semua ini ...",
  ui_story_5043_50431101_38_dialog_content = "Tidak heran kalian tidak melakukan apa-apa di sini!",
  ui_story_5043_50431101_39_dialog_content = "Bukan itu sama sekali, Tn. Byron...",
  ui_story_5043_50431101_40_dialog_content = "Aku cukup bodoh untuk menaruh kepercayaanku padamu...",
  ui_story_5043_50431101_41_dialog_content = "Dan apa yang saya dapatkan sebagai balasannya, eh? Sekelompok orang aneh bertengkar tentang cinta sambil menghancurkannya dan membuang-buang waktuku!",
  ui_story_5043_50431101_42_dialog_content = "Penjahat buruk ini lebih baik menjawab kejahatannya, Ketua Hakim Schwab! Saya sungguh-sungguh!",
  ui_story_5043_50431101_43_dialog_content = "Saya yakinkan Anda bahwa dia akan diadili, Tn. Byron... Hanya saja tidak hari ini.",
  ui_story_5043_50431101_44_dialog_content = "Jangan lupa bahwa sidang pemenggal patung akan diadakan besok.",
  ui_story_5043_50431101_45_dialog_content = "Pada saat itu, Anda dapat mengajukan klaim Anda ke pengadilan.",
  ui_story_5043_50431101_46_dialog_content = "Saya sangat menyadari itu!",
  ui_story_5043_50431101_47_dialog_content = "Kekasihku, istriku... Mereka adalah korban sebenarnya dari semua ini! Mereka tidak pantas menerima apa yang terjadi pada mereka!",
  ui_story_5043_50431101_48_dialog_content = "Berjanjilah padaku bahwa kau akan mencari keadilan untuk mereka, Ketua Hakim Schwab!",
  ui_story_5043_50431101_49_dialog_content = "Tapi tentu saja. Divisi Percintaan memiliki kewajiban untuk melindungi kesucian cinta.",
  ui_story_5043_50431101_50_dialog_content = "Penjaga! Bawa dia pergi!",
  ui_story_5043_50431101_51_dialog_content = "Tolong sebentar!",
  ui_story_5043_50431101_52_dialog_content = "Yang Mulia, saya ingin memeriksa sarung tangan itu sekali lagi.",
  ui_story_5043_50431101_53_dialog_content = "Tidak ada jalan Tina bisa melakukan kejahatan ini... Mungkin kita salah mengartikan beberapa bagian dari bukti?",
  ui_story_5043_50431101_54_dialog_content = "Either way, kita tidak bisa menahannya dengan tergesa-gesa!",
  ui_story_5043_50431101_55_dialog_content = "Dengar dengar! Hanya karena gaya sarung tangan yang sama, tidak berarti itu milik pasangan aslinya!",
  ui_story_5043_50431101_56_dialog_content = "Bahkan, saya diketahui membeli tujuh pasang sarung tangan yang sama persis dari waktu ke waktu!",
  ui_story_5043_50431101_57_dialog_content = "Leyn... Matthieu...",
  ui_story_5043_50431101_58_dialog_content = "Cukup, juri. Saya telah memenuhi spekulasi menggelikan selama satu hari.",
  ui_story_5043_50431101_59_dialog_content = "Jika Anda memiliki hal lain untuk dikatakan, saya sarankan Anda menyimpannya untuk uji coba besok.",
  ui_story_5043_50431101_60_dialog_content = "Tapi kenapa? Aku hanya ingin melihat-lihat...",
  ui_story_5043_50431101_61_dialog_content = "Saya bilang, CUKUP.",
  ui_story_5043_50431101_62_dialog_content = "Tersangka akan segera dibawa ke sel isolasi. Tidak ada yang akan diizinkan untuk melihatnya sampai dimulainya persidangan besok.",
  ui_story_5043_50431101_63_dialog_content = "Ruang isolasi?! Apa kau sudah gila?!",
  ui_story_5043_50431101_64_dialog_content = "Anda tidak berhak menempatkannya di sel isolasi sebelum diadili! Itu melanggar hukum!",
  ui_story_5043_50431101_65_dialog_content = "Sebagai hakim kepala Divisi Percintaan, saya telah diberikan otoritas tunggal untuk memukul kerikil dan memutuskan siapa yang bersalah.",
  ui_story_5043_50431101_66_dialog_content = "Menempatkannya di sel isolasi hanyalah langkah penting lainnya dalam proses, atau apakah Anda meragukan Balai Kehakiman dan hukumnya?",
  ui_story_5043_50431101_67_dialog_content = "Anda-",
  ui_story_5043_50431101_68_dialog_content = "J-Jangan terburu-buru, semuanya!",
  ui_story_5043_50431101_69_dialog_content = "Saya akan mengikuti keputusan Hakim Schwab untuk saat ini. Kami hanya harus membantah tuduhan di pengadilan besok.",
  ui_story_5043_50431101_70_dialog_content = "Tina...",
  ui_story_5043_50431101_71_dialog_content = "Saya seorang hakim, jadi saya harus percaya bahwa sistem peradilan Lumopolis tidak akan pernah salah menghukum orang yang tidak bersalah.",
  ui_story_5043_50431101_72_dialog_content = "Saya yakin kebenaran akan terungkap dengan sendirinya selama persidangan besok...",
  ui_story_5043_50431101_73_dialog_content = "Karena saya percaya pada Divisi Percintaan.",
  ui_story_5043_50431101_74_dialog_content = "Dan saya percaya pada kalian semua.",
  ui_story_5043_50431101_75_dialog_content = "...",
  ui_story_5043_50431101_76_dialog_content = "...",
  ui_story_5043_50431101_77_dialog_content = "Bawa dia pergi, penjaga.",
  ui_story_5043_50431101_78_dialog_content = "Siap, Pak!",
  ui_story_5043_50431101_79_dialog_content = "<color=#e8d9bb>Di luar Hall of Justice, Lumopolis Gardens</color>",
  ui_story_5043_50431101_80_dialog_content = "Mereka terkunci Tina ke atas. Apa yang akan kita lakukan?",
  ui_story_5043_50431101_81_dialog_content = "Anda tidak berpikir mereka akan menemukan dia bersalah besok, bukan?",
  ui_story_5043_50431101_82_dialog_content = "Jika semuanya tetap seperti sekarang ini... mereka akan melakukannya.",
  ui_story_5043_50431101_83_dialog_content = "K-Kita tidak bisa membiarkan itu terjadi! Dia tidak bersalah!",
  ui_story_5043_50431101_84_dialog_content = "Apakah hanya saya, atau apakah ada sesuatu tentang Schwab yang tampak aneh hari ini?",
  ui_story_5043_50431101_85_dialog_content = "Hah?",
  ui_story_5043_50431101_86_dialog_content = "Yah, aku selalu menganggapnya sebagai orang yang sangat aneh, tapi sekarang setelah kau menyebutkannya...",
  ui_story_5043_50431101_87_dialog_content = "Sikapnya hari ini memang tampak sedikit ekstrim.",
  ui_story_5043_50431101_88_dialog_content = "Dia sangat jelas menentang kami, ya.",
  ui_story_5043_50431101_89_dialog_content = "Dia membumbui setiap informasi yang terlibat Tina, dan mengabaikan semua bantahan kami.",
  ui_story_5043_50431101_90_dialog_content = "Dengan tepat. Terlalu banyak untuk menjadi kebetulan, bukan begitu?",
  ui_story_5043_50431101_91_dialog_content = "Saat kejadian itu terjadi, orang-orangnya kebetulan menemukan sarung tangan itu dan menyerahkannya sebagai bukti.",
  ui_story_5043_50431101_92_dialog_content = "Seolah-olah dia sudah tahu di mana sarung tangan satunya berada...",
  ui_story_5043_50431101_93_dialog_content = "Tidak hanya itu. Dia tampaknya memiliki pemahaman yang sangat rinci tentang apa yang terjadi di TKP.",
  ui_story_5043_50431101_94_dialog_content = "Ingat ekspresi menjijikkan dan puas diri yang dia miliki di wajahnya?",
  ui_story_5043_50431101_95_dialog_content = "Benar-benar? Pikirkan baik-baik, kalian semua.",
  ui_story_5043_50431101_96_dialog_content = "Saat kejadian itu terjadi, adalah Hakim Tina sebenarnya di sisimu dalam perang melawan Eclipsites?",
  ui_story_5043_50431101_97_dialog_content = "Dia tidak pernah ada di sana sejak awal, jadi apa yang memberinya kepercayaan diri untuk menanyakan hal itu kepada kita?",
  ui_story_5043_50431101_98_dialog_content = "Kau benar!",
  ui_story_5043_50431101_99_dialog_content = "Ketika Anda mempertimbangkan semua ini, proses pengadilan melawan Tina berjalan terlalu lancar hari ini.",
  ui_story_5043_50431101_100_dialog_content = "Semuanya menunjuk ke Tina bersalah tanpa keraguan...",
  ui_story_5043_50431101_101_dialog_content = "Tapi tidak satu pun dari hal-hal ini yang seaneh keputusan terakhirnya.",
  ui_story_5043_50431101_102_dialog_content = "Keputusan untuk mengurungnya.",
  ui_story_5043_50431101_103_dialog_content = "Saya sangat setuju.",
  ui_story_5043_50431101_104_dialog_content = "Menemukan sarung tangan itu, tahu persis apa yang terjadi di TKP... Dia bisa menjelaskan hal-hal ini dengan mudah—mungkin ada banyak saksi, atau itu hanya keberuntungan belaka.",
  ui_story_5043_50431101_105_dialog_content = "Semua prosedurnya sah, dan tidak akan ada jalan keluar dalam tuduhannya.",
  ui_story_5043_50431101_106_dialog_content = "Memang. Tapi dia sudah bosan membuktikan dirinya pada akhirnya.",
  ui_story_5043_50431101_107_dialog_content = "Dia melarang kami memeriksa barang bukti dan menguncinya Tina di sel isolasi tanpa memberikan alasan.",
  ui_story_5043_50431101_108_dialog_content = "Ini berarti dia menyembunyikan sesuatu, sesuatu yang dia tidak mampu membiarkan orang lain melihatnya.",
  ui_story_5043_50431101_109_dialog_content = "Terutama bukan kita.",
  ui_story_5043_50431101_110_dialog_content = "Itu pasti petunjuk penting, baginya untuk melanggar peraturan demi menutupinya.",
  ui_story_5043_50431101_111_dialog_content = "Sesuatu memberi tahu saya bahwa petunjuk adalah kunci untuk mengungkap kebenaran dan membuktikan bahwa Tina tidak bersalah!",
  ui_story_5043_50431101_112_dialog_content = "Wow! Deduksi yang brilian!",
  ui_story_5043_50431101_113_dialog_content = "Jaga omonganmu.",
  ui_story_5043_50431101_114_dialog_content = "Ini adalah gerbang Balai Kehakiman.",
  ui_story_5043_50431101_115_dialog_content = "O-Oh ya, kita harus menyimpannya.",
  ui_story_5043_50431101_116_dialog_content = "Jadi yang harus kita lakukan adalah mencari tahu apa yang disembunyikan Schwab dari kita, dan kita akan bisa membuktikan bahwa Tina tidak bersalah, bukan?",
  ui_story_5043_50431101_117_dialog_content = "Kedengarannya mudah jika Anda mengatakannya seperti itu, tetapi saya khawatir kami tidak akan dapat mengetahuinya tepat waktu.",
  ui_story_5043_50431101_118_dialog_content = "Hah?",
  ui_story_5043_50431101_119_dialog_content = "Schwab pasti akan menyelesaikan semua masalah sebelum persidangan besok.",
  ui_story_5043_50431101_120_dialog_content = "Dia tahu apa yang perlu dilakukan untuk menutupi jejaknya yang tidak kita ketahui.",
  ui_story_5043_50431101_121_dialog_content = "Saya yakin dia memiliki banyak kemungkinan yang disiapkan, jika terjadi kesalahan.",
  ui_story_5043_50431101_122_dialog_content = "Kemungkinan dia berhasil sangat menguntungkannya.",
  ui_story_5043_50431101_123_dialog_content = "Jadi apa, kita hanya menunggu sampai persidangan dan berharap yang terbaik?!",
  ui_story_5043_50431101_124_dialog_content = "Jika kita melakukannya, Tina pasti akan dinyatakan bersalah.",
  ui_story_5043_50431101_125_dialog_content = "Artinya kita perlu menggali beberapa petunjuk sebelum sidang dimulai.",
  ui_story_5043_50431101_126_dialog_content = "Jika kita tidak bisa mengungkap rahasia Schwab, kita harus mencari petunjuk lain.",
  ui_story_5043_50431101_127_dialog_content = "Hahaha, saran yang menarik!",
  ui_story_5043_50431101_128_dialog_content = "Dan sesuatu memberi tahu saya bahwa Anda sudah tahu harus mulai dari mana, bukan?",
  ui_story_5043_50431101_129_dialog_content = "Hei, kalian bertiga lebih baik tidak melakukan hal bodoh, kau dengar?",
  ui_story_5043_50431101_130_dialog_content = "Oh, ayolah, Loewe! Kami tidak akan pernah memimpikannya.",
  ui_story_5043_50431101_131_dialog_content = "... Saya masih memiliki penyelidikan lebih lanjut, jadi saya akan pergi sekarang.",
  ui_story_5043_50431101_132_dialog_content = "Jika kalian bertiga ketahuan melakukan sesuatu yang bodoh, aku tidak pernah di sini, dan kita tidak pernah melakukan percakapan ini. Memahami?",
  ui_story_5043_50431101_133_dialog_content = "Kamu...",
  ui_story_5043_50431101_134_dialog_content = "Lebih baik begini, Matthieu. Lebih banyak orang hanya akan menghalangi.",
  ui_story_5043_50431101_135_dialog_content = "Sekarang mendekatlah, kalian berdua.",
  ui_story_5043_50431101_136_dialog_content = "Tentu, apa itu?",
  ui_story_5043_50431101_137_dialog_content = "Jika Schwab bersedia melanggar aturan untuk menyembunyikan rahasianya...",
  ui_story_5043_50431101_138_dialog_content = "Kami harus melakukan hal yang sama jika ingin mengalahkannya.",
  ui_story_5043_50431101_139_dialog_content = "Tapi bagaimana tepatnya?",
  ui_story_5043_50431101_140_dialog_content = "Kita akan masuk ke rumah Schwab.",
  ui_story_5043_50431101_141_dialog_content = "Apa?!",
  ui_story_5043_50431101_142_dialog_content = "Jika kita tidak bisa mendekati tersangka atau buktinya, kita hanya harus melakukan hal terbaik berikutnya—Schwab sendiri.",
  ui_story_5043_50431101_143_dialog_content = "Dan rumahnya adalah tempat teraman untuk menyimpan rahasianya.",
  ui_story_5043_50431101_144_dialog_content = "Jika dia benar-benar menyembunyikan sesuatu yang penting, itu akan menjadi tempat terbaik untuk mulai mencari.",
  ui_story_5043_50431101_145_dialog_content = "Tapi... bukankah itu melanggar hukum?",
  ui_story_5043_50431101_146_dialog_content = "Ini menarik! Ide yang luar biasa!",
  ui_story_5043_50431101_147_dialog_content = "Maka itu menyelesaikannya! Ayo kita kunjungi rumah hakim yang baik!",
  ui_story_5043_50431101_148_dialog_content = "Kira saya satu-satunya yang peduli dengan hukum lagi ... Baik, saya ikut.",
  ui_story_5043_50431101_149_dialog_content = "Satu-satunya alasan kita dalam kesulitan ini adalah karena lawan kita melakukan hal yang sama kepada kita.",
  ui_story_5043_50431101_150_dialog_content = "Ketika saatnya tiba, saya dengan senang hati akan bertanggung jawab penuh untuk membobol rumahnya.",
  ui_story_5043_50431101_151_dialog_content = "Tapi yang paling penting saat ini adalah memastikannya Tina tidak dihukum atas kejahatan yang tidak dilakukannya.",
  ui_story_5043_50431101_152_dialog_content = "Hmph. Tanggung jawab penuh, katamu?",
  ui_story_5043_50431101_153_dialog_content = "Huh, kejujuran seperti itu hanya akan menimbulkan masalah bagimu di masa depan, lho.",
  ui_story_5043_50431101_154_dialog_content = "Anda benar... Membuktikan kepolosan Tina adalah yang utama!",
  ui_story_5043_50431101_155_dialog_content = "Jadi haruskah kita pergi sekarang?",
  ui_story_5043_50431101_156_dialog_content = "Masih ada satu hal terakhir yang harus kita lakukan sebelum itu.",
  ui_story_5043_50431101_157_dialog_content = "Saya tidak tahu apakah kalian berdua menyadarinya, tetapi para penjaga di belakang kami telah mengikuti kami selama beberapa waktu.",
  ui_story_5043_50431101_158_dialog_content = "Schwab pasti sudah memerintahkan mereka untuk mengawasi kita. Tidak mungkin dia membiarkan kita pergi begitu saja.",
  ui_story_5043_50431101_159_dialog_content = "Sepertinya kita harus menyingkirkan mereka, kalau begitu.",
  ui_story_5043_50431101_160_dialog_content = "Aku juga berpikir begitu.",
  ui_story_5043_50431101_161_dialog_content = "Seharusnya cukup mudah. Lagipula, aku ahli dalam hal melarikan diri.",
  ui_story_5043_50431101_162_dialog_content = "Jangan lupa, saya punya \"mata\" ekstra untuk mereka.",
  ui_story_5043_50431101_163_dialog_content = "Itu benar! Kami dapat menggunakan kemampuan psikis Anda pada mereka!",
  ui_story_5043_50431101_164_dialog_content = "Jadi sebagai seniman pelarian residen kita, apa yang harus menjadi langkah pertama kita?",
  ui_story_5043_50431101_165_dialog_content = "Sebenarnya cukup sederhana.",
  ui_story_5043_50431101_166_dialog_content = "Langkah pertama untuk melarikan diri—",
  ui_story_5043_50431101_167_dialog_content = "—adalah untuk mulai berlari!!!",
  ui_story_5043_50431102_1_dialog_content = "Belok kanan ke depan!",
  ui_story_5043_50431102_2_dialog_content = "Ah, ini benar-benar melelahkan.",
  ui_story_5043_50431102_3_dialog_content = "Dengan baik? Apakah ada penjaga yang mengikuti jejak kita?",
  ui_story_5043_50431102_4_dialog_content = "Tidak! Tidak satu pun!",
  ui_story_5043_50431102_5_dialog_content = "Apa? Lalu mengapa kita masih berlari?!",
  ui_story_5043_50431102_6_dialog_content = "A-Bukankah kita akan pergi ke rumah Schwab sekarang?",
  ui_story_5043_50431102_7_dialog_content = "Saya yakin ini jalan yang benar.",
  ui_story_5043_50431102_8_dialog_content = "Ya, tapi jika tidak ada yang mengejar kita, kita bisa berjalan sepanjang sisa perjalanan ke sana!",
  ui_story_5043_50431102_9_dialog_content = "Selain itu, bagaimana Anda tahu rumahnya seperti ini?",
  ui_story_5043_50431102_10_dialog_content = "Karena aku memberitahunya.",
  ui_story_5043_50431102_11_dialog_content = "Kami kekurangan waktu, jadi saya pikir lari ke sana akan lebih cepat.",
  ui_story_5043_50431102_12_dialog_content = "Anda setidaknya bisa memberi tahu saya bahwa kami kehilangan penjaga! Aku takut mereka mengejar kita selama ini!!",
  ui_story_5043_50431102_13_dialog_content = "Baiklah, baiklah, pelankan suaramu. Rumahnya ada di depan.",
  ui_story_5043_50431102_14_dialog_content = "Kenapa kamu...",
  ui_story_5043_50431102_15_dialog_content = "<color=#e8d9bb>Di luar Salar Manor, Lumopolis Gardens</color>",
  ui_story_5043_50431102_16_dialog_content = "Sepertinya mereka memiliki banyak penjaga dan pelayan yang ditempatkan di pintu masuk.",
  ui_story_5043_50431102_17_dialog_content = "Bagaimana kita bisa menghindarinya DAN mencari petunjuk?",
  ui_story_5043_50431102_18_dialog_content = "Anda benar, itu tidak akan mudah.",
  ui_story_5043_50431102_19_dialog_content = "Jika salah satu dari mereka melihat kami, kami akan duduk di sebelah Tina di dermaga besok.",
  ui_story_5043_50431102_20_dialog_content = "Mengetahui itu, apakah kalian berdua masih mau melakukan ini?",
  ui_story_5043_50431102_21_dialog_content = "Ini adalah satu-satunya pilihan kami jika kami ingin membuktikan Tina tidak bersalah...",
  ui_story_5043_50431102_22_dialog_content = "Kita harus melakukannya, tidak peduli betapa berbahayanya itu!",
  ui_story_5043_50431102_23_dialog_content = "Ada satu lapisan perak untuk skema sembrono ini. Rumah Schwab jelas cukup besar untuk memberi kita banyak tempat untuk bersembunyi.",
  ui_story_5043_50431102_24_dialog_content = "Dengan itu dan beberapa kemampuan psikis, kita seharusnya bisa menghindari bahaya dengan cukup baik.",
  ui_story_5043_50431102_25_dialog_content = "Aku akan memastikan untuk terus mengawasi lingkungan kita! Serahkan saja padaku!",
  ui_story_5043_50431102_26_dialog_content = "Jadi bagaimana tepatnya kita menginjakkan kaki di dalam manor?",
  ui_story_5043_50431102_27_dialog_content = "Saya tidak yakin kita punya cukup waktu untuk menunggu penjaga berganti shift...",
  ui_story_5043_50431102_28_dialog_content = "Tidak masalah, karena kita tidak akan masuk melalui gerbang depan.",
  ui_story_5043_50431102_29_dialog_content = "Oh? Apakah Anda kebetulan melihat gerbang lain?",
  ui_story_5043_50431102_30_dialog_content = "Tidak, tapi lihat taman di sana. Ini memiliki banyak pagar yang bisa kita gunakan untuk berlindung.",
  ui_story_5043_50431102_31_dialog_content = "Setelah kita cukup dekat, kita akan melompati tembok.",
  ui_story_5043_50431102_32_dialog_content = "Melompati tembok?!",
  ui_story_5043_50431102_33_dialog_content = "Kamu benar! Ini sempurna untuk tidak terlihat, dan lihat, dindingnya juga tidak terlalu tinggi!",
  ui_story_5043_50431102_34_dialog_content = "Ayo, mari bergerak.",
  ui_story_5043_50431102_35_dialog_content = "Baik!",
  ui_story_5043_50431102_36_dialog_content = "T-Tunggu sebentar, kalian berdua! Tidakkah menurutmu melompati tembok itu tidak pantas?",
  ui_story_5043_50431102_37_dialog_content = "Lagipula, aku adalah anggota Sawyer yang bangga—",
  ui_story_5043_50431102_38_dialog_content = "—Ugh, lupakan saja. Sejujurnya, kalian rakyat jelata akan menjadi kematianku.",
  ui_story_5043_50431201_1_dialog_content = "Ugh... Kenapa aku harus melakukan hal sebodoh itu...?",
  ui_story_5043_50431201_2_dialog_content = "Hanya tersenyum dan menanggungnya, Matthieu. Kami melakukan ini untuk membersihkan nama Tina.",
  ui_story_5043_50431201_3_dialog_content = "Melihat? Kami sudah berhasil masuk ke manor!",
  ui_story_5043_50431201_4_dialog_content = "Semuanya terlihat begitu elegan di sini...",
  ui_story_5043_50431201_5_dialog_content = "Jadi ini rumah Schwab, ya?",
  ui_story_5043_50431201_6_dialog_content = "Ya... Harus kuakui, itu membuatku merasa sedikit iri.",
  ui_story_5043_50431201_7_dialog_content = "Keluarga Salar adalah salah satu yang paling berpengaruh di seluruh Lumopolis.",
  ui_story_5043_50431201_8_dialog_content = "Apa yang kita lihat di sini hanyalah puncak gunung es dari kekayaan mereka, saya yakin—",
  ui_story_5043_50431201_9_dialog_content = "Baiklah, istirahatlah. Sepertinya aku melihat seseorang di depan.",
  ui_story_5043_50431201_10_dialog_content = "Mari kita lihat.",
  ui_story_5043_50431201_11_dialog_content = "Hei, aku juga melihat mereka!",
  ui_story_5043_50431201_12_dialog_content = "Tunggu, apa itu... Schwab?",
  ui_story_5043_50431201_13_dialog_content = "Maafkan kami, Tuan Schwab, kami kehilangan jejak mereka.",
  ui_story_5043_50431201_14_dialog_content = "Caelestite dan kedua juri menggunakan jalur berliku untuk keuntungan mereka, jadi kami tidak bisa mengejar mereka...",
  ui_story_5043_50431201_15_dialog_content = "Apakah ini sebabnya saya mempekerjakan Anda bodoh, hmm?",
  ui_story_5043_50431201_16_dialog_content = "Tidak berguna! Banyak dari Anda!",
  ui_story_5043_50431201_17_dialog_content = "Maafkan kami, tuanku!",
  ui_story_5043_50431201_18_dialog_content = "... Cukup. Apa yang dilakukan sudah selesai.",
  ui_story_5043_50431201_19_dialog_content = "Sekarang mereka dalam pelarian, mungkin ada kebaikan yang akan datang dari kesalahan bodohmu.",
  ui_story_5043_50431201_20_dialog_content = "Kembali ke posting Anda.",
  ui_story_5043_50431201_21_dialog_content = "Ya, Tuan Schwab!",
  ui_story_5043_50431201_22_dialog_content = "Jadi anak buahnya memata-matai kita... Hah! Seolah-olah aku akan membiarkan dia melakukan apa yang dia suka!",
  ui_story_5043_50431201_23_dialog_content = "Aku senang kita berhasil menemukan Schwab begitu cepat.",
  ui_story_5043_50431201_24_dialog_content = "Mari terus ikuti dia, dan lihat apa yang akan dia lakukan.",
  ui_story_5043_50431201_25_dialog_content = "Setiap perubahan dalam perilakunya mungkin memberi kita petunjuk yang kita butuhkan!",
  ui_story_5043_50431201_26_dialog_content = "Baik!",
  ui_story_5043_50431201_27_dialog_content = "Jangan sampai kalian berdua lupa, Schwab bukanlah pria yang mudah dipahami.",
  ui_story_5043_50431201_28_dialog_content = "Jika dia bersedia melanggar hukum di hadapan seluruh Dewan Kehakiman, siapa yang tahu tindakan tak terkatakan apa yang mampu dia lakukan dalam privasi rumahnya sendiri...",
  ui_story_5043_50431201_29_dialog_content = "O-Oke, sekarang kamu mulai membuatku takut.",
  ui_story_5043_50431201_30_dialog_content = "Bagus. Ketakutan Anda akan membuat Anda tetap waspada.",
  ui_story_5043_50431201_31_dialog_content = "Ayo, jangan lupakan dia.",
  ui_story_5043_50431201_32_dialog_content = "Teh Anda, tuanku.",
  ui_story_5043_50431201_33_dialog_content = "Bagus, berikan di sini.",
  ui_story_5043_50431201_34_dialog_content = "Dapur sedang menyiapkan beberapa makanan penutup. Haruskah saya membawakan Anda piring, Tuan?",
  ui_story_5043_50431201_35_dialog_content = "Itu tidak perlu. Saya memiliki hal-hal lain untuk menghadiri sekarang.",
  ui_story_5043_50431201_36_dialog_content = "Jangan ganggu saya sampai saya selesai dengan mereka.",
  ui_story_5043_50431201_37_dialog_content = "Y-Ya, Tuan Schwab!",
  ui_story_5043_50431201_38_dialog_content = "Dia menyuruh pelayannya pergi.",
  ui_story_5043_50431201_39_dialog_content = "Ssst... Mungkinkah hal-hal ini begitu jahat sehingga bahkan orang-orangnya sendiri tidak dapat mengetahuinya?",
  ui_story_5043_50431201_40_dialog_content = "Er... M-Mungkin dia hanya ingin sendiri sebentar?",
  ui_story_5043_50431201_41_dialog_content = "Sejujurnya, PlayerName... Apakah Anda tidak memiliki imajinasi?",
  ui_story_5043_50431201_42_dialog_content = "Apakah saya, atau saya tidak hanya mengatakan bahwa Schwab bukanlah orang yang mudah dipahami?",
  ui_story_5043_50431201_43_dialog_content = "Baik. Saya mengerti.",
  ui_story_5043_50431201_44_dialog_content = "Tetap saja, seberapa buruk itu? Apa yang bisa dilakukan oleh pria rumit seperti dia di kebunnya sendiri?",
  ui_story_5043_50431201_45_dialog_content = "Lihat! Dia mengangkat tangannya sekarang!",
  ui_story_5043_50431201_46_dialog_content = "Sepertinya dia memegang sesuatu.",
  ui_story_5043_50431201_47_dialog_content = "Ini jarum! Dia memiliki jarum di tangannya!",
  ui_story_5043_50431201_48_dialog_content = "Sebuah jarum?!",
  ui_story_5043_50431201_49_dialog_content = "Untuk tujuan apa? Apakah dia bermaksud menggunakannya pada dirinya sendiri ?!",
  ui_story_5043_50431201_50_dialog_content = "Tidak, bukan pada dirinya sendiri...",
  ui_story_5043_50431201_51_dialog_content = "<color=#e8d9bb>Menusuk!</color>",
  ui_story_5043_50431201_52_dialog_content = "Dia menggunakannya pada boneka di tangannya yang lain...",
  ui_story_5043_50431201_53_dialog_content = "Ke-Kenapa dia melakukan itu pada boneka?!",
  ui_story_5043_50431201_54_dialog_content = "Aku pernah mendengar ini sebelumnya... Jenis kutukan yang melibatkan penggunaan boneka.",
  ui_story_5043_50431201_55_dialog_content = "Sebuah kutukan?",
  ui_story_5043_50431201_56_dialog_content = "Ini bekerja dengan mengambil sesuatu dari tubuh seseorang, biasanya rambut atau darah, dan memasukkannya ke dalam boneka.",
  ui_story_5043_50431201_57_dialog_content = "Dengan melakukan itu, boneka itu terhubung secara spiritual dengan orang itu.",
  ui_story_5043_50431201_58_dialog_content = "Menusuk atau melukai boneka itu menimbulkan rasa sakit dan luka yang sama pada sasaran kutukan.",
  ui_story_5043_50431201_59_dialog_content = "Dan akhirnya, orang itu akan mati dengan kematian yang sangat menyakitkan!",
  ui_story_5043_50431201_60_dialog_content = "<color=#e8d9bb>Menusuk!</color>",
  ui_story_5043_50431201_61_dialog_content = "Ck, dia melakukannya lagi!",
  ui_story_5043_50431201_62_dialog_content = "Kurasa aku pernah mendengar kutukan seperti itu, tapi aku tidak pernah menyangka seseorang seperti Schwab mencoba-coba ilmu hitam...",
  ui_story_5043_50431201_63_dialog_content = "Yah, saya tidak menganggapnya mengejutkan sama sekali. Aku sudah lama melihat sandiwaranya yang lembut dan mulia!",
  ui_story_5043_50431201_64_dialog_content = "Saya tidak tahu... Kutukan seperti ini biasanya hanya takhayul yang menyeramkan, bukan?",
  ui_story_5043_50431201_65_dialog_content = "Selain itu, ini akan menjadi pelanggaran berat terhadap kepercayaan Lumopolis...",
  ui_story_5043_50431201_66_dialog_content = "Jadi begitu. Tidak masalah apakah kutukan itu nyata atau tidak. Yang penting adalah apakah orang percaya atau tidak.",
  ui_story_5043_50431201_67_dialog_content = "Dan jelas bagi saya bahwa Schwab mempercayainya.",
  ui_story_5043_50431201_68_dialog_content = "Yang berarti bahwa di suatu tempat di dunia... Ada orang yang cukup dibenci Schwab hingga ingin membunuh mereka...",
  ui_story_5043_50431201_69_dialog_content = "<color=#e8d9bb>Menusuk!</color>",
  ui_story_5043_50431201_70_dialog_content = "Tapi siapa? Siapa itu?!",
  ui_story_5043_50431201_71_dialog_content = "Siapa yang bisa sangat bersalah padanya, sehingga dia menginginkan kematian pada mereka?",
  ui_story_5043_50431201_72_dialog_content = "Saya tidak tahu... Tapi itu benar-benar membuat Anda bertanya-tanya, bukan?",
  ui_story_5043_50431201_73_dialog_content = "Secara umum, Schwab menjalani kehidupan yang hampir sempurna... Saya tidak dapat membayangkan siapa yang dapat menghancurkannya untuknya.",
  ui_story_5043_50431201_74_dialog_content = "Kecuali... kebenciannya berasal dari tempat di mana tak seorang pun dapat dengan mudah melihatnya.",
  ui_story_5043_50431201_75_dialog_content = "Ketika Anda mengatakannya seperti itu ... Ya, itu masuk akal sekarang!",
  ui_story_5043_50431201_76_dialog_content = "Jelas, kemarahannya bermula dari hal yang sudah lama hilang namun tak terlupakan <color=#FFB400>Cinta</color>!",
  ui_story_5043_50431201_77_dialog_content = "<color=#e8d9bb>Menusuk!</color>",
  ui_story_5043_50431201_78_dialog_content = "Jika itu benar, kita perlu melakukan sesuatu segera! Itu bisa berarti perbedaan antara hidup dan mati bagi seseorang di luar sana!",
  ui_story_5043_50431201_79_dialog_content = "Jangan terburu-buru. Kita harus menunggu dia menunjukkan bukti kesalahan yang jelas dan tak terbantahkan sebelum kita bisa ikut campur.",
  ui_story_5043_50431201_80_dialog_content = "Apa yang bisa kita lakukan sekarang, mengingat pengetahuan kita saat ini? Hentikan dia menusuk boneka malang itu?",
  ui_story_5043_50431201_81_dialog_content = "Hei, menurutmu takhayul itu benar... bukan?",
  ui_story_5043_50431201_82_dialog_content = "Maksudmu menggunakan boneka untuk mengutuk seseorang?",
  ui_story_5043_50431201_83_dialog_content = "Ya...",
  ui_story_5043_50431201_84_dialog_content = "Karena jika mereka, itu mungkin ...",
  ui_story_5043_50431201_85_dialog_content = "... bahwa kita menyaksikan adegan pembunuhan!",
  ui_story_5043_50431201_86_dialog_content = "Sekarang untuk sentuhan akhir...",
  ui_story_5043_50431201_87_dialog_content = "Biarlah keberadaan kecil dan malang ini...",
  ui_story_5043_50431201_88_dialog_content = "Kita harus menghentikannya! Buru-buru!",
  ui_story_5043_50431201_89_dialog_content = "<color=#e8d9bb>Menusuk!</color>",
  ui_story_5043_50431201_90_dialog_content = "—terlahir kembali!!!",
  ui_story_5043_50431201_91_dialog_content = "Astaga... Kamu lucu, bukan?",
  ui_story_5043_50431201_92_dialog_content = "Nah, apa yang harus saya beri nama Anda? Bagaimana dengan... kastanye?",
  ui_story_5043_50431201_93_dialog_content = "J-Jadi itu... boneka landak?",
  ui_story_5043_50431201_94_dialog_content = "Itu memang terlihat seperti landak.",
  ui_story_5043_50431201_95_dialog_content = "Dia bahkan memberinya nama yang pas. Melihat? Memang terlihat seperti kastanye kecil.",
  ui_story_5043_50431201_96_dialog_content = "<size=45>Jadi apa yang membuat kita panik?!?</size>",
  ui_story_5043_50431201_97_dialog_content = "Ssst! Diam, PlayerName!",
  ui_story_5043_50431201_98_dialog_content = "Sigh... Aku tidak percaya betapa bodohnya kita, berbicara tentang Schwab yang membunuh seseorang.",
  ui_story_5043_50431201_99_dialog_content = "Eh, coba-coba hanyalah bagian alami dari penyelidikan.",
  ui_story_5043_50431201_100_dialog_content = "Hanya dengan menghilangkan semua kemungkinan lain, kebenaran akan terungkap dengan sendirinya. Itu semua adalah bagian dari proses.",
  ui_story_5043_50431201_101_dialog_content = "Apa pun yang membantu Anda tidur di malam hari, Leyn...",
  ui_story_5043_50431201_102_dialog_content = "Ehem... Omong-omong, lupakan saja pembicaraan kita tadi dan fokus untuk membantu Tina.",
  ui_story_5043_50431201_103_dialog_content = "Schwab akan kembali ke dalam sekarang, kemungkinan besar untuk mempersiapkan sidang besok.",
  ui_story_5043_50431201_104_dialog_content = "Kita harus melihat lebih dekat.",
  ui_story_5043_50431201_105_dialog_content = "Huh, sepertinya eksperimen kecilku masih jauh dari selesai. Mungkin saya akan membuat lebih banyak kemajuan hari ini...?",
  ui_story_5043_50431201_106_dialog_content = "Apakah Anda mendengar itu? Eksperimen!",
  ui_story_5043_50431201_107_dialog_content = "Ya, apa yang mungkin dia teliti di sana?",
  ui_story_5043_50431201_108_dialog_content = "Tidak ada yang baik, saya kira. Lagipula, dia orang yang sulit dimengerti.",
  ui_story_5043_50431201_109_dialog_content = "Jangan ini lagi, Matthieu...",
  ui_story_5043_50431201_110_dialog_content = "Jangan langsung mengambil kesimpulan gila lagi. Tidak setelah terakhir kali.",
  ui_story_5043_50431201_111_dialog_content = "Mungkin itu hanya percobaan kecil di rumah? Bisa jadi hobi nya...",
  ui_story_5043_50431201_112_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_113_dialog_content = "Wow!",
  ui_story_5043_50431201_114_dialog_content = "Apa itu sebuah ledakan?! Apa yang dia lakukan di sana?!",
  ui_story_5043_50431201_115_dialog_content = "Aku tidak tahu. Haruskah kita mendekat dan melihat?",
  ui_story_5043_50431201_116_dialog_content = "Bagaimana? Tidak ada tempat untuk bersembunyi di ruangan itu!",
  ui_story_5043_50431201_117_dialog_content = "Jika kita lebih dekat dari sekarang, penyamaran kita akan terbongkar...",
  ui_story_5043_50431201_118_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_119_dialog_content = "Ledakan lain! Mungkinkah dia sedang membuat bom?!",
  ui_story_5043_50431201_120_dialog_content = "Sebuah bom?! T-Tunggu, kami melompat ke kesimpulan lagi!",
  ui_story_5043_50431201_121_dialog_content = "Dan kenapa tidak? Ini kurang lebih adalah bisnis keluarga Salar!",
  ui_story_5043_50431201_122_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_123_dialog_content = "Tapi mengapa dia meneliti bahan peledak?",
  ui_story_5043_50431201_124_dialog_content = "Nah, semakin rumit suatu tempat, semakin rentan terhadap bahan peledak. Lumopolis tidak terkecuali.",
  ui_story_5043_50431201_125_dialog_content = "Coba pikirkan: seseorang akan datang ke pengadilan untuk perusakan patung.",
  ui_story_5043_50431201_126_dialog_content = "Bagaimana jika itu adalah menara jam atau gereja? Konsekuensinya akan jauh lebih tak terbayangkan.",
  ui_story_5043_50431201_127_dialog_content = "Dengan memanfaatkan kekuatan bom yang merusak, mereka dapat menggunakan rasa takut untuk memaksa orang lain mematuhinya!",
  ui_story_5043_50431201_128_dialog_content = "Saya tidak tahu ... \"Bom\" -nya tidak menggores rumahnya.",
  ui_story_5043_50431201_129_dialog_content = "Itulah sebabnya dia menyebutnya \"eksperimen kecil\"!",
  ui_story_5043_50431201_130_dialog_content = "Begitu dia sepenuhnya memahami sains di baliknya, dia dapat menggunakan Luminatics untuk membuat bomnya seratus kali lebih kuat!",
  ui_story_5043_50431201_131_dialog_content = "Jika dia berhasil, Schwab dapat merusak seluruh masyarakat kita seperti yang kita ketahui!",
  ui_story_5043_50431201_132_dialog_content = "Semua Lumopolis bahkan bisa jatuh di bawah kendalinya...",
  ui_story_5043_50431201_133_dialog_content = "I-Apakah itu benar-benar serius ?!",
  ui_story_5043_50431201_134_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431201_135_dialog_content = "Uhuk, uhuk...",
  ui_story_5043_50431201_136_dialog_content = "Ah, upaya lain yang gagal.",
  ui_story_5043_50431201_137_dialog_content = "Siapa yang tahu pembuatan itu <color=#FFB400>puding karamel</color> bisa begitu sulit?",
  ui_story_5043_50431201_138_dialog_content = "...",
  ui_story_5043_50431201_139_dialog_content = "Jadi, maksudmu dia akan mengambil alih Lumopolis... dengan PUDDING?!?",
  ui_story_5043_50431201_140_dialog_content = "A-Apa dia semacam idiot?! Bagaimana dia bisa menghasilkan ledakan saat memanggang makanan penutup?!",
  ui_story_5043_50431201_141_dialog_content = "Inilah pertanyaan yang lebih baik: bagaimana kedua tebakan Anda bisa benar-benar salah?!",
  ui_story_5043_50431201_142_dialog_content = "Ssst! Dia kembali ke luar! Cepat, sembunyi!",
  ui_story_5043_50431201_143_dialog_content = "Sigh... Buang-buang waktu dan tenaga lagi.",
  ui_story_5043_50431201_144_dialog_content = "Mungkin sudah waktunya melakukan sesuatu yang lebih produktif? Sekarang di mana aku meletakkan kunci ruang bawah tanah itu... Ah, ini dia.",
  ui_story_5043_50431201_145_dialog_content = "Aku harus memeriksa hal-hal untuk terakhir kalinya sebelum sidang besok...",
  ui_story_5043_50431201_146_dialog_content = "Maafkan saya, Tuan Schwab, tapi makan malam sudah siap.",
  ui_story_5043_50431201_147_dialog_content = "Apakah saya tidak menjelaskan dengan sangat jelas bahwa saya tidak ingin diganggu saat ini?!",
  ui_story_5043_50431201_148_dialog_content = "M-Maafkan aku, Guru! Maksudku jangan tersinggung... Tapi makanannya sudah ada di meja...",
  ui_story_5043_50431201_149_dialog_content = "Ugh... Baiklah, tapi biarlah ini terakhir kalinya kau menggangguku!",
  ui_story_5043_50431201_150_dialog_content = "Schwab pergi makan malam. Saya tidak berpikir kita akan bisa mengikutinya ke sana, tidak dengan semua pelayan di sekitar.",
  ui_story_5043_50431201_151_dialog_content = "Apakah Anda mendengar apa yang dia katakan sebelum dia pergi?",
  ui_story_5043_50431201_152_dialog_content = "Biar kutebak, ada hubungannya dengan dia yang \"sulit dimengerti\"?",
  ui_story_5043_50431201_153_dialog_content = "Sangat lucu, tapi tidak—dia menyebutkan sesuatu tentang ruang bawah tanah.",
  ui_story_5043_50431201_154_dialog_content = "Gunakan otakmu sekali saja, ya? Tepat sebelum dia dipanggil untuk makan malam, dia mengeluarkan kunci ruang bawah tanah manor.",
  ui_story_5043_50431201_155_dialog_content = "Dan lihat! Dia meninggalkan kunci itu di lubang di sana!",
  ui_story_5043_50431201_156_dialog_content = "Haruskah kita melihat ke dalam? Siapa yang tahu rahasia apa yang akan kita temukan di balik pintu itu!",
  ui_story_5043_50431201_157_dialog_content = "Sepertinya ini kesempatan yang sempurna, tapi...",
  ui_story_5043_50431201_158_dialog_content = "Kami masih belum menemukan apa pun yang dapat membantu kami membuktikan bahwa Tina tidak bersalah! Saya tidak tahu apakah membobol ruang bawah tanah Schwab adalah ide yang tepat.",
  ui_story_5043_50431201_159_dialog_content = "Jika Anda benar-benar yakin dia tidak bersalah, maka kebenaran pasti ada di sini, di rumah Schwab, entah di mana.",
  ui_story_5043_50431201_160_dialog_content = "Bahkan jika dia hanya pion dalam semua ini, pasti ada semacam petunjuk yang tertinggal.",
  ui_story_5043_50431201_161_dialog_content = "Jika kita belum menemukannya, itu karena kita belum menggali cukup dalam!",
  ui_story_5043_50431201_162_dialog_content = "... Kamu benar. Tidak ada jalan kembali sekarang... Jadi mari kita lihat apa yang ada di ruang bawah tanah itu!",
  ui_story_5043_50431201_163_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5043_50431201_164_dialog_content = "Di sana gelap gulita... Aku tidak bisa melihat apa-apa!",
  ui_story_5043_50431201_165_dialog_content = "Tampaknya ada tangga menuju lebih jauh ke bawah. Kita bisa mencoba merasakan jalan kita ke depan...",
  ui_story_5043_50431201_166_dialog_content = "Tina? Tina! Apakah kamu di sini?",
  ui_story_5043_50431201_167_dialog_content = "Tunggu... pikirku PlayerName memiliki beberapa kekuatan psikis?",
  ui_story_5043_50431201_168_dialog_content = "Bisakah Anda menggunakannya untuk merasakan apa yang ada di depan?",
  ui_story_5043_50431201_169_dialog_content = "Aku bisa mencoba, ya.",
  ui_story_5043_50431201_170_option_content = "Force Boost",
  ui_story_5043_50431201_171_dialog_content = "Memiliki Caelestite di sisi seseorang terkadang terbukti sangat berguna, bukan?",
  ui_story_5043_50431201_172_dialog_content = "Dengan baik? Apa yang kamu lihat?",
  ui_story_5043_50431201_173_dialog_content = "Apakah ada sumber cahaya yang bisa kita gunakan, seperti lilin atau obor?",
  ui_story_5043_50431201_174_dialog_content = "Ruang bawah tanah ini tampaknya turun sangat jauh ...",
  ui_story_5043_50431201_175_dialog_content = "... Hah? Sesuatu menuju ke arah kita!",
  ui_story_5043_50431201_176_dialog_content = "Apakah itu...",
  ui_story_5043_50431201_177_dialog_content = "Graaah—",
  ui_story_5043_50431201_178_dialog_content = "Wahhhhhhhh—",
  ui_story_5043_50431201_179_dialog_content = "Apa itu? Apa yang Anda lihat?!",
  ui_story_5043_50431201_180_dialog_content = "L-Lari! Kembali ke pintu masuk!",
  ui_story_5043_50431201_181_dialog_content = "Massa Eclipsites menyerbu ke arah kita!",
  ui_story_5043_50431202_1_dialog_content = "Graah...",
  ui_story_5043_50431202_2_dialog_content = "Gerhana? Apa yang dilakukan makhluk kotor ini di ruang bawah tanah Schwab?!",
  ui_story_5043_50431202_3_dialog_content = "Rupanya, para bangsawan menyukai lebih dari sekadar hal-hal yang lebih baik dalam hidup!",
  ui_story_5043_50431202_4_dialog_content = "Jangan samakan kami dengan fitnah kejimu! Saya ingin Anda tahu keluarga saya tidak akan pernah menyimpan monster menjijikkan seperti itu di rumah kami!",
  ui_story_5043_50431202_5_dialog_content = "Cukup, kalian! Mereka semakin dekat!",
  ui_story_5043_50431202_6_dialog_content = "Aku akan menunda Eclipsites! Kalian berdua keluar dari sini secepat mungkin!",
  ui_story_5043_50431202_7_dialog_content = "A-Apakah kamu yakin?",
  ui_story_5043_50431202_8_dialog_content = "Tentu saja! Jangan remehkan juri Lumopolis!",
  ui_story_5043_50431202_9_dialog_content = "Baiklah, kau bajingan Eclipsite... Ambil ini!",
  ui_story_5043_50431202_10_dialog_content = "<color=#e8d9bb>Menabrak-!</color>",
  ui_story_5043_50431202_11_dialog_content = "Aduh Buyung! Anda baru saja memecahkan kandil mereka!",
  ui_story_5043_50431202_12_dialog_content = "Tampaknya dibuat dari kristal Northland? Berarti itu perlengkapan yang cukup mahal.",
  ui_story_5043_50431202_13_dialog_content = "Ups! Pikirkan mereka akan meminta saya untuk membayarnya...?",
  ui_story_5043_50431202_14_dialog_content = "Anda khawatir tentang uang pada saat seperti ini ?! Fokus pada Eclipsites!",
  ui_story_5043_50431202_15_dialog_content = "Ini mereka datang lagi...",
  ui_story_5043_50431202_16_dialog_content = "<color=#e8d9bb>Menabrak-!</color>",
  ui_story_5043_50431202_17_dialog_content = "Besar! Sekarang meja teh mereka juga hancur!",
  ui_story_5043_50431202_18_dialog_content = "Dan menilai dari keahliannya yang luar biasa, saya yakin Schwab juga akan kehilangan tidur karenanya.",
  ui_story_5043_50431202_19_dialog_content = "Aku benar-benar minta maaf! Tapi kurasa bukan aku yang harus membayar, karena itu adalah kesalahan Eclipsites sejak awal...",
  ui_story_5043_50431202_20_dialog_content = "Sekarang bukan waktunya, kalian berdua! Lihat, itu pintunya!",
  ui_story_5043_50431202_21_dialog_content = "Kita harus pergi sekarang!",
  ui_story_5043_50431202_22_dialog_content = "<color=#e8d9bb>Sepuluh menit kemudian...</color>",
  ui_story_5043_50431202_23_dialog_content = "Kami telah mencari di sekeliling perkebunan, Master Schwab... Tapi masih belum ada tanda-tanda penyusup.",
  ui_story_5043_50431202_24_dialog_content = "Benar-benar kacau... Siapa atau apa yang menyebabkan semua ini?",
  ui_story_5043_50431202_25_dialog_content = "... Anda yakin tidak melihat penyusup?",
  ui_story_5043_50431202_26_dialog_content = "Ya tuan. Semuanya tampak aman, setidaknya untuk saat ini.",
  ui_story_5043_50431202_27_dialog_content = "Sangat mungkin pelakunya atau pelakunya adalah ahli... Jika mereka meninggalkan petunjuk, kami belum menemukannya.",
  ui_story_5043_50431202_28_dialog_content = "Mungkin lebih baik... serahkan ini ke Balai Kehakiman?",
  ui_story_5043_50431202_29_dialog_content = "Tentunya, mereka akan menyelidiki masalah ini dengan sangat serius, mengingat status Anda?",
  ui_story_5043_50431202_30_dialog_content = "Sebuah investigasi...",
  ui_story_5043_50431202_31_dialog_content = "Tidak, itu tidak perlu.",
  ui_story_5043_50431202_32_dialog_content = "Lagipula itu hanya beberapa perabot. Apa yang hilang dapat dengan mudah diganti.",
  ui_story_5043_50431202_33_dialog_content = "Untuk saat ini, mintalah seseorang membereskan kekacauan ini segera.",
  ui_story_5043_50431202_34_dialog_content = "Ya, Tuan Schwab!",
  ui_story_5043_50431202_35_dialog_content = "(Pintu ruang bawah tanah terbuka...)",
  ui_story_5043_50431202_36_dialog_content = "(Apakah saya membukanya sebelum saya pergi untuk makan malam?)",
  ui_story_5043_50431202_37_dialog_content = "(Bagi saya untuk membuat kesalahan bodoh ... Ini hampir tak terduga.)",
  ui_story_5043_50431202_38_dialog_content = "(Saya harus tidur lebih awal malam ini. Saya membutuhkan pikiran yang jernih untuk sidang besok.)",
  ui_story_5043_50431202_39_dialog_content = "Sigh, apa yang sebenarnya terjadi di sini?",
  ui_story_5043_50431202_40_dialog_content = "Penjahat macam apa yang membobol rumah seseorang, hanya untuk menghancurkan lampu gantung dan meja teh mereka?",
  ui_story_5043_50431202_41_dialog_content = "Tetap saja... potongan-potongan yang rusak ini mungkin mendapatkan harga yang bagus dengan penjual barang bekas yang tepat.",
  ui_story_5043_50431202_42_dialog_content = "Huft, huft...",
  ui_story_5043_50431202_43_dialog_content = "(Akhirnya... akhirnya keluar!)",
  ui_story_5043_50431202_44_dialog_content = "Apakah ada yang berhasil mengikuti kami?",
  ui_story_5043_50431202_45_dialog_content = "Saya kira tidak demikian. Sepertinya pantainya bersih.",
  ui_story_5043_50431202_46_dialog_content = "Ck. Betapa memalukan—sepanjang hari, dihabiskan untuk hal-hal yang sia-sia.",
  ui_story_5043_50431202_47_dialog_content = "Yang lebih buruk adalah kami tidak dapat menemukannya Tina, atau bahkan petunjuk terkecil yang bisa membantunya.",
  ui_story_5043_50431202_48_dialog_content = "Bagaimana dia bisa melewati persidangan sekarang?",
  ui_story_5043_50431202_49_dialog_content = "Kami telah melakukan semua yang kami bisa... Yang tersisa hanyalah kami memenuhi tugas kami sebagai hakim.",
  ui_story_5043_50431202_50_dialog_content = "Sebelum persidangan dimulai, kita perlu memperhitungkan semua yang telah terjadi hari ini.",
  ui_story_5043_50431202_51_dialog_content = "Mungkin saja petunjuk yang kita cari tersembunyi di suatu tempat dalam detailnya.",
  ui_story_5043_50431202_52_dialog_content = "Tak perlu dikatakan bahwa kami akan melakukan tugas kami dengan kemampuan terbaik kami. Namun...",
  ui_story_5043_50431202_53_dialog_content = "Tanpa bukti yang pasti, kami tidak berdaya seperti orang lain untuk mengubah hasil persidangan.",
  ui_story_5043_50431202_54_dialog_content = "Belum lagi, kami tidak tahu trik lain apa yang masih dimiliki Schwab.",
  ui_story_5043_50431202_55_dialog_content = "Mengadili dia seperti ini akan sia-sia, untuk sedikitnya.",
  ui_story_5043_50431202_56_dialog_content = "Ada lebih dari satu cara untuk menang, Matthieu.",
  ui_story_5043_50431202_57_dialog_content = "Kita mungkin tidak memiliki semua kartu yang kita butuhkan, tetapi itu tidak berarti kita sudah keluar dari permainan.",
  ui_story_5043_50431202_58_dialog_content = "Wah, wah, merasa begitu yakin tentang diri kita sendiri, bukan?",
  ui_story_5043_50431202_59_dialog_content = "Bukan dalam diri kita sendiri, tetapi dalam kebenaran.",
  ui_story_5043_50431202_60_dialog_content = "Tugas satu pihak adalah menyembunyikan kebenaran, sementara pihak lain mengungkapkannya. Mengetahui hal itu, kami memiliki keuntungan yang jelas dalam kasus ini.",
  ui_story_5043_50431202_61_dialog_content = "Lagi pula, perjalanan kecil kami ke rumah Schwab tidak sepenuhnya sia-sia...",
  ui_story_5043_50431301_1_dialog_content = "<color=#e8d9bb>Keesokan harinya</color>",
  ui_story_5043_50431301_2_dialog_content = "(Jadi akhirnya akan dimulai...)",
  ui_story_5043_50431301_3_dialog_content = "(Uji coba Pemenggalan Patung Berantai akan segera berlangsung.)",
  ui_story_5043_50431301_4_dialog_content = "(Leyn, Matthieu, Dan Tina... Apakah mereka dapat mengungkap kebenaran di depan pengadilan?)",
  ui_story_5043_50431301_5_dialog_content = "PlayerName!",
  ui_story_5043_50431301_6_dialog_content = "Carleen! Dan Loewe juga!",
  ui_story_5043_50431301_7_dialog_content = "Anda berhasil kembali!",
  ui_story_5043_50431301_8_dialog_content = "Tentu saja. Saya memberi semua orang kata saya bahwa saya akan berada di sini untuk persidangan, bukan?",
  ui_story_5043_50431301_9_dialog_content = "Namun, sesuatu yang meresahkan dibawa ke perhatian saya ...",
  ui_story_5043_50431301_10_dialog_content = "Saya mendengar itu Tina adalah terdakwa?",
  ui_story_5043_50431301_11_dialog_content = "Matthieu, Anda benar-benar kalah sendiri kali ini.",
  ui_story_5043_50431301_12_dialog_content = "Saya tantang Anda untuk mengatakannya lagi...!",
  ui_story_5043_50431301_13_dialog_content = "I-Itu benar, ya...",
  ui_story_5043_50431301_14_dialog_content = "Tina ditetapkan sebagai tersangka utama dalam kasus ini setelah beberapa bukti aneh terungkap.",
  ui_story_5043_50431301_15_dialog_content = "Tapi aku yakin semuanya akan baik-baik saja!",
  ui_story_5043_50431301_16_dialog_content = "Apa yang sebenarnya terjadi dalam dua hari terakhir?",
  ui_story_5043_50431301_17_dialog_content = "Ceritanya agak panjang. Aku akan memberitahumu lebih banyak lagi setelah kita berada di dalam ruang sidang.",
  ui_story_5043_50431301_18_dialog_content = "<color=#e8d9bb>Hall of Justice, Divisi Percintaan, Lumopolis Gardens</color>",
  ui_story_5043_50431301_19_dialog_content = "Pesan, pesan!",
  ui_story_5043_50431301_20_dialog_content = "Pertama, izinkan saya untuk meminta maaf kepada semua orang karena harus melakukan begitu banyak perjalanan ke gedung pengadilan untuk kasus ini.",
  ui_story_5043_50431301_21_dialog_content = "Sayangnya, kami tidak dapat mencegah pelakunya melakukan beberapa kali kejahatan keji ini.",
  ui_story_5043_50431301_22_dialog_content = "Tampaknya hari ini adalah hari di mana penjahat ini akhirnya diadili!",
  ui_story_5043_50431301_23_dialog_content = "Sekarang, tanpa basa-basi lagi—",
  ui_story_5043_50431301_24_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431301_25_dialog_content = "Uji coba Pemenggalan Patung Serial sekarang sedang berlangsung!",
  ui_story_5043_50431301_26_dialog_content = "...",
  ui_story_5043_50431301_27_dialog_content = "...",
  ui_story_5043_50431301_28_dialog_content = "<size=30>Kalian...</size>",
  ui_story_5043_50431301_29_dialog_content = "<size=30>Percayalah pada mereka. Hanya itu yang bisa kita lakukan sekarang.</size>",
  ui_story_5043_50431301_30_dialog_content = "Pertama, izinkan kami memperkenalkan pihak-pihak yang terlibat dalam litigasi hari ini!",
  ui_story_5043_50431301_31_dialog_content = "Untuk penuntutan, Tn. Byron.",
  ui_story_5043_50431301_32_dialog_content = "Dan untuk pertahanan, Tina Campbell.",
  ui_story_5043_50431301_33_dialog_content = "Kami sangat malu melihat salah satu hakim Divisi Percintaan kami diadili atas kejahatan keji seperti itu. Tetapi semua sama di mata hukum, dan semua harus bertanggung jawab atas dosa-dosa mereka.",
  ui_story_5043_50431301_34_dialog_content = "Sulit dipercaya...",
  ui_story_5043_50431301_35_dialog_content = "Saya, Schwab Salar, akan memimpin sebagai hakim ketua dalam persidangan hari ini.",
  ui_story_5043_50431301_36_dialog_content = "Hakim Matthieu Penggergaji dan Leyn akan bergabung dalam persidangan, serta anggota juri yang dihormati lainnya.",
  ui_story_5043_50431301_37_dialog_content = "Hmph, kamu akhirnya belajar menunjukkan rasa hormat kepada yang lebih tua.",
  ui_story_5043_50431301_38_dialog_content = "Kontribusi kami untuk penyelidikan sama pentingnya dengan kontribusi orang lain!",
  ui_story_5043_50431301_39_dialog_content = "Katakan padaku, apa pendapatmu tentang kasus ini sejauh ini?",
  ui_story_5043_50431301_40_dialog_content = "...",
  ui_story_5043_50431301_41_dialog_content = "...",
  ui_story_5043_50431301_42_dialog_content = "Ah ya, aku hampir lupa kita harus diam untuk saat ini...",
  ui_story_5043_50431301_43_dialog_content = "Detail dasar kasus ini diuraikan dalam dokumen yang diletakkan di depan Anda. Setiap orang diundang untuk meninjaunya atas kebijaksanaan mereka sendiri.",
  ui_story_5043_50431301_44_dialog_content = "Terima kasih tidak sedikit atas upaya investigasi menyeluruh kami, kami akhirnya menetapkan rangkaian peristiwa yang jelas.",
  ui_story_5043_50431301_45_dialog_content = "Selanjutnya saya akan menyampaikan keterangan singkat tentang temuan upaya penyidikan tersebut terkait kasus Pemenggalan Patung Berantai.",
  ui_story_5043_50431301_46_dialog_content = "Temuan kami menunjukkan bahwa terdakwa, Tina Campbell, menggunakan penghancuran patung untuk mempublikasikan kebenciannya yang mendalam terhadap gelombang cinta yang melanda seluruh Lumopolis.",
  ui_story_5043_50431301_47_dialog_content = "Dalam dua insiden sebelumnya, dia menyalahgunakan wewenangnya sebagai hakim untuk menghilangkan bukti yang menunjukkan kesalahannya.",
  ui_story_5043_50431301_48_dialog_content = "Namun terima kasih kepada Tuan Byron dan laporannya yang tepat waktu, Hakim Leyn sepenuhnya siap untuk insiden ketiga dan terakhir.",
  ui_story_5043_50431301_49_dialog_content = "Dan di TKP, dia bisa mendapatkan bukti penting dari pelaku ...",
  ui_story_5043_50431301_50_dialog_content = "Sarung tangan ini!",
  ui_story_5043_50431301_51_dialog_content = "Bagus sekali! Ini seharusnya lebih dari cukup untuk memberatkan terdakwa!",
  ui_story_5043_50431301_52_dialog_content = "Memang. Saya meluncurkan penyelidikan terhadap pemilik sarung tangan ini, dan bawahan saya menemukan penemuan yang mengejutkan — sarung tangan lainnya ditemukan di laci meja milik Hakim. Tina Campbell!",
  ui_story_5043_50431301_53_dialog_content = "Mengapa, ini pasangan yang sempurna!",
  ui_story_5043_50431301_54_dialog_content = "Dan penyelidikan kami mengkonfirmasi hal yang sama. Kedua sarung tangan adalah bagian dari satu set milik satu pemilik ...",
  ui_story_5043_50431301_55_dialog_content = "Dan pemilik itu berdiri di hadapan kita hari ini, di kursi terdakwa—Tina Campbell!",
  ui_story_5043_50431301_56_dialog_content = "Tidak seperti itu...",
  ui_story_5043_50431301_X56_dialog_content = "Wow! Ketua Hakim Schwab adalah badass melebihi usianya!",
  ui_story_5043_50431301_57_dialog_content = "Berdasarkan bukti-bukti yang tidak terbantahkan, pengadilan dengan ini mengusulkan agar terdakwa didakwa dengan penghancuran barang milik umum, serta subversi asmara!",
  ui_story_5043_50431301_58_dialog_content = "Secara alami, Anda bebas untuk membenarkan perilaku menjijikkan Anda sesuka Anda.",
  ui_story_5043_50431301_59_dialog_content = "Ketahuilah bahwa tidak ada campur tangan ilahi yang akan mempengaruhi juri untuk membebaskan Anda dari semua tuduhan.",
  ui_story_5043_50431301_60_dialog_content = "Kenapa kamu...",
  ui_story_5043_50431301_61_dialog_content = "Saya tidak berpikir itu mungkin!",
  ui_story_5043_50431301_62_dialog_content = "Kualitas terpenting kita di sini saat memimpin sebuah kasus adalah ketidakberpihakan!",
  ui_story_5043_50431301_63_dialog_content = "Bukan begitu, rekan-rekan juri?",
  ui_story_5043_50431301_64_dialog_content = "...",
  ui_story_5043_50431301_65_dialog_content = "...",
  ui_story_5043_50431301_66_dialog_content = "Saya tidak tahu harus berkata apa lagi tentang sarung tangan itu ...",
  ui_story_5043_50431301_67_dialog_content = "Memang benar itu milik saya, tapi saya tidak pernah membawanya ke TKP.",
  ui_story_5043_50431301_68_dialog_content = "Saya melawan Eclipsites pada saat itu, dan tidak mungkin mendekati patung itu, apalagi merusaknya.",
  ui_story_5043_50431301_69_dialog_content = "Pada saat saya sampai di patung itu, kerusakan sudah terjadi...",
  ui_story_5043_50431301_70_dialog_content = "Apakah ada saksi yang bisa membuktikannya?",
  ui_story_5043_50431301_71_dialog_content = "Aku…",
  ui_story_5043_50431301_72_dialog_content = "Maaf, tapi aku terpisah dari semua orang saat itu, jadi tidak ada saksi...",
  ui_story_5043_50431301_73_dialog_content = "Maka tampaknya kesaksian Anda tidak dapat membalikkan kesimpulan kami saat ini.",
  ui_story_5043_50431301_74_dialog_content = "Jika Anda tidak memiliki bukti kuat lain untuk ditawarkan, maka untuk kejahatan penghancuran properti publik dan subversi cinta, dengan ini kami menemukan Anda—",
  ui_story_5043_50431301_75_dialog_content = "<size=45>Tunggu!!!</size>",
  ui_story_5043_50431301_76_dialog_content = "... Ya, Hakim Matthieu?",
  ui_story_5043_50431301_77_dialog_content = "Saya khawatir saya harus menolak keputusan Anda, Hakim Schwab!",
  ui_story_5043_50431301_78_dialog_content = "Tina tidak mungkin menjadi penyebab di balik pemenggalan patung berantai ini! Dia memiliki bukti yang membuktikan bahwa dia tidak pernah berada di TKP!",
  ui_story_5043_50431301_79_dialog_content = "Heh, apakah dia, sekarang?",
  ui_story_5043_50431301_80_dialog_content = "Kalau begitu mari kita dengar apa yang Anda katakan, Hakim Matthieu.",
  ui_story_5043_50431301_81_dialog_content = "Dan ingatlah untuk bersikap rasional dan seobjektif mungkin dalam pembelaannya.",
  ui_story_5043_50431301_82_dialog_content = "Jika tidak, kami mungkin menemukan bukti kaki tangan dalam kejahatannya.",
  ui_story_5043_50431301_83_dialog_content = "Ahem. Mari kita kembali ke awal kasus.",
  ui_story_5043_50431301_84_dialog_content = "Yakni, kejadian pertama patung dipenggal.",
  ui_story_5043_50431301_85_dialog_content = "Saya sudah menyelidiki secara menyeluruh tindakan para pelaku hari itu.",
  ui_story_5043_50431301_86_dialog_content = "Sayangnya, terdakwa tidak dapat membuktikan bahwa dia tidak berada di TKP.",
  ui_story_5043_50431301_87_dialog_content = "Tidak, Yang Mulia... Tapi yang terpenting adalah apa yang terjadi SETELAH kejahatan itu dilakukan!",
  ui_story_5043_50431301_88_dialog_content = "Siang itu, Tina dan saya berada di Hall of Justice, tempat kami bekerja bersama selama kira-kira empat jam.",
  ui_story_5043_50431301_89_dialog_content = "Saya secara pribadi dapat membuktikan hal ini, seperti halnya anggota Aula lainnya yang hadir hari itu.",
  ui_story_5043_50431301_90_dialog_content = "Baiklah, jadi kalian bekerja bersama selama empat jam. Lalu bagaimana?",
  ui_story_5043_50431301_91_dialog_content = "Dia bisa dengan mudah melakukan kejahatan sebelum kembali bekerja denganmu di Hall of Justice.",
  ui_story_5043_50431301_92_dialog_content = "Salah, Yang Mulia! Empat jam itu adalah bukti positif bahwa dia tidak pernah berada di TKP!",
  ui_story_5043_50431301_93_dialog_content = "Kamu melihat, Tina menderita bentuk hipersomnia yang langka. Rumah sakit mana pun di Lumopolis juga dapat membuktikan hal ini.",
  ui_story_5043_50431301_94_dialog_content = "Akibatnya, paling lama dia bisa tetap terjaga selama hari tertentu kira-kira empat jam!",
  ui_story_5043_50431301_95_dialog_content = "...",
  ui_story_5043_50431301_96_dialog_content = "Dengan kata lain, di luar empat jam yang kami habiskan untuk bekerja bersama, dia pasti tertidur sepanjang waktu!",
  ui_story_5043_50431301_97_dialog_content = "Dengan demikian, tidak mungkin dia bisa merusak patung pertama!",
  ui_story_5043_50431301_98_dialog_content = "Dia bahkan tidur di tempat kerja!?",
  ui_story_5043_50431301_99_dialog_content = "Apakah dia tidak punya rasa malu? Adakah yang bisa benar-benar dibayar untuk tidak melakukan apa-apa akhir-akhir ini?",
  ui_story_5043_50431301_100_dialog_content = "Itu benar! Saya sedang tidur pada saat itu!",
  ui_story_5043_50431301_101_dialog_content = "Saya tidak mendengar tentang patung itu sampai setelah saya bangun.",
  ui_story_5043_50431301_102_dialog_content = "Baiklah kalau begitu? Apakah itu bukti bahwa dia tidak bersalah atas patung pertama?",
  ui_story_5043_50431301_103_dialog_content = "Anda menyebut itu argumen?",
  ui_story_5043_50431301_104_dialog_content = "Menggunakan spekulasi belaka untuk tidak hanya menetapkan alibi bagi terdakwa, tetapi juga memberikan penilaian atas seluruh persidangannya!",
  ui_story_5043_50431301_105_dialog_content = "Jika sistem peradilan kita begitu sembrono, kita tidak membutuhkan hal-hal seperti bukti atau kesaksian!",
  ui_story_5043_50431301_106_dialog_content = "Saya mengerti, Yang Mulia! Anda ingin melihat bukti, ya?",
  ui_story_5043_50431301_107_dialog_content = "Kemudian izinkan saya untuk melanjutkan ke contoh kedua dari pemenggalan patung.",
  ui_story_5043_50431301_108_dialog_content = "Sama seperti kejadian pertama, ada bukti yang cukup di sini membuktikan Tina Campbell tidak ada di TKP.",
  ui_story_5043_50431301_109_dialog_content = "Untuk itu, Hakim Leyn dan saya berdua bisa menjadi saksi.",
  ui_story_5043_50431301_110_dialog_content = "Hmph! Apakah Anda yakin Anda bermaksud mengatakan saksi dan bukan kaki tangan, Hakim Matthieu?",
  ui_story_5043_50431301_111_dialog_content = "Astaga, sebagai hakim yang dihormati di Hall of Justice, bukankah kita semua berada di pihak yang sama, Yang Mulia?",
  ui_story_5043_50431301_112_dialog_content = "Ah, tapi tidak masalah... Ada satu orang lagi di sini hari ini yang juga bisa menjadi saksi.",
  ui_story_5043_50431301_113_dialog_content = "Dan saya percaya seseorang dalam posisinya akan lebih dari cukup untuk membuktikan bahwa Tina tidak bersalah.",
  ui_story_5043_50431301_114_dialog_content = "Kecuali, tentu saja, maksud Anda menyiratkan bahwa Putri Lumopolis juga terlibat dalam kejahatan ini?",
  ui_story_5043_50431301_115_dialog_content = "...",
  ui_story_5043_50431301_116_dialog_content = "... Dia?",
  ui_story_5043_50431301_117_dialog_content = "Pada saat kejadian kedua, kami semua berada di Meadow Square di Halaman Lumopolis, menanggapi sebuah krisis.",
  ui_story_5043_50431301_118_dialog_content = "Saya mengerti apa yang Anda katakan. Tapi kita perlu memulihkan ketertiban terlebih dahulu.",
  ui_story_5043_50431301_119_dialog_content = "Tolong, jangan panik. Ikuti aku!",
  ui_story_5043_50431301_120_dialog_content = "<color=#e8d9bb>Menghancurkan-!</color>",
  ui_story_5043_50431301_121_dialog_content = "(Suara apa itu?!)",
  ui_story_5043_50431301_122_dialog_content = "Saya adalah orang pertama yang mendengar suara patung dihancurkan. Tak lama kemudian, Hakim Tina dan saya pergi untuk menyelidiki.",
  ui_story_5043_50431301_123_dialog_content = "Saat sampai di TKP, kami berdua menemukan patung itu kehilangan kepalanya.",
  ui_story_5043_50431301_124_dialog_content = "Tidak ada poin dalam rangkaian peristiwa hari itu yang dilakukan oleh Judge Tina pernah lepas dari pandanganku. Dengan demikian, saya dapat membuktikan, dengan kepastian penuh, bahwa dia tidak berada di TKP ketika patung kedua dipenggal.",
  ui_story_5043_50431301_125_dialog_content = "Saya percaya Bu Carleen dan biarawati dapat menguatkan ini.",
  ui_story_5043_50431301_126_dialog_content = "Itu benar. Sebelum kejadian tersebut, Tina bersama kami sepanjang waktu.",
  ui_story_5043_50431301_127_dialog_content = "Dia tidak punya cara untuk melakukan kejahatan.",
  ui_story_5043_50431301_128_dialog_content = "Memang. Saya juga bisa berdiri sebagai saksi kurangnya keterlibatan Hakim Tina dalam kejahatan tersebut.",
  ui_story_5043_50431301_129_dialog_content = "Nah, Yang Mulia?",
  ui_story_5043_50431301_130_dialog_content = "Apakah kesaksian-kesaksian ini cukup menjadi bukti bagi Anda?",
  ui_story_5043_50431301_131_dialog_content = "Baik.",
  ui_story_5043_50431301_132_dialog_content = "Pengadilan menghormati dan mengakui setiap kesaksian yang diberikan oleh Lady Carleen.",
  ui_story_5043_50431301_133_dialog_content = "Selain itu, kata-kata dan hasrat Anda berpengaruh pada saya, Hakim Matthieu.",
  ui_story_5043_50431301_134_dialog_content = "Sepertinya saya salah menuduh Nona Tina Campbell, bagaimanapun juga.",
  ui_story_5043_50431301_135_dialog_content = "(A-Apakah kita baru saja menang?)",
  ui_story_5043_50431301_136_dialog_content = "Pengadilan menarik keputusan sebelumnya! Kami menemukan bahwa terdakwa, Tina Campbell, bukanlah pelaku di balik rangkaian pemenggalan patung.",
  ui_story_5043_50431301_137_dialog_content = "Kami, bagaimanapun, menemukan dia bersalah atas <color=#FFB400>contoh ketiga</color> pemenggalan patung!",
  ui_story_5043_50431301_138_dialog_content = "Eh...?",
  ui_story_5043_50431301_139_dialog_content = "Cih.",
  ui_story_5043_50431301_140_dialog_content = "Banggalah dengan usaha Anda, Hakim Matthieu! Tanpa mereka, hukuman terdakwa akan sangat berkurang.",
  ui_story_5043_50431301_141_dialog_content = "Namun! Selama bukti penting yang diberikan sebelumnya tidak terbantahkan...",
  ui_story_5043_50431301_142_dialog_content = "... pengadilan masih akan menemukan Tina Campbell bersalah karena merusak properti publik, serta menumbangkan asmara!",
  ui_story_5043_50431301_143_dialog_content = "Tapi Anda sudah menyadarinya, bukan, Hakim Matthieu?",
  ui_story_5043_50431301_144_dialog_content = "Benar-benar omong kosong...",
  ui_story_5043_50431301_145_dialog_content = "Dengan mengatakan itu, Anda masih ingin terus menyangkal bukti tak terbantahkan yang dibawa ke pengadilan hari ini?",
  ui_story_5043_50431301_146_dialog_content = "...",
  ui_story_5043_50431301_147_dialog_content = "<size=30>Tetap bertahan, Matthieu...</size>",
  ui_story_5043_50431301_148_dialog_content = "<size=30>Itu masih belum cukup...</size>",
  ui_story_5043_50431301_149_dialog_content = "Tidak, Yang Mulia. Saya telah mengatakan semua yang perlu saya katakan.",
  ui_story_5043_50431301_150_dialog_content = "Apa...?",
  ui_story_5043_50431301_151_dialog_content = "Hehehehe, begitu?",
  ui_story_5043_50431301_152_dialog_content = "Ya, Yang Mulia.",
  ui_story_5043_50431301_153_dialog_content = "Dalam hal ini, pengadilan dengan ini—",
  ui_story_5043_50431301_154_dialog_content = "Sekarang giliranmu, Leyn.",
  ui_story_5043_50431301_155_dialog_content = "!!!",
  ui_story_5043_50431301_156_dialog_content = "Leyn?",
  ui_story_5043_50431301_157_dialog_content = "Pergilah kalau begitu. Pendatang baru jarang diberikan kesempatan seperti ini.",
  ui_story_5043_50431301_158_dialog_content = "Aku mengerti.",
  ui_story_5043_50431301_159_dialog_content = "Ketua Hakim Schwab, sesama anggota juri, dan semua yang berkumpul di sini hari ini.",
  ui_story_5043_50431301_160_dialog_content = "Saya dengan rendah hati meminta beberapa menit dari waktu Anda.",
  ui_story_5043_50431301_161_dialog_content = "Agar kami bisa <color=#FFB400>menarik kesimpulan</color> dari pemahaman kita tentang kejahatan.",
  ui_story_5043_50431301_162_dialog_content = "Huh, anak ini agak gila.",
  ui_story_5043_50431301_163_dialog_content = "Anda sebaiknya memilih kata-kata Anda dengan bijak, Hakim Leyn. Terutama mengingat latar belakang Anda yang \"rendah hati\".",
  ui_story_5043_50431301_164_dialog_content = "Berbeda dengan Hakim Matthieu, Anda tidak mendapat dukungan dari keluarga bangsawan jika kualitas pekerjaan Anda dipertanyakan.",
  ui_story_5043_50431301_165_dialog_content = "Dan tidak seperti Anda, Ketua Hakim Schwab, saya tidak percaya bahwa latar belakang umum saya menjadi penghalang.",
  ui_story_5043_50431301_166_dialog_content = "Paling tidak, tindakan saya tidak memiliki cara untuk mencerminkan kasta bangsawan yang termasyhur.",
  ui_story_5043_50431301_167_dialog_content = "Kamu...",
  ui_story_5043_50431301_168_dialog_content = "Tapi mari kita kembali ke kasus yang ada, oke? Yang Mulia tampaknya sangat bersikeras pada bukti penting itu...",
  ui_story_5043_50431301_169_dialog_content = "Saya menyarankan agar kita melakukan tinjauan yang lebih mendetail tentang kasus ini, dan tidak meninggalkan kebutuhan bisnis yang terlewat.",
  ui_story_5043_50431301_170_dialog_content = "Dengan memeriksa setiap detail secara cermat, saya yakin kita akan menemukan jejak pelaku sebenarnya—sesuatu yang akan mengarahkan kita ke arah kebenaran!",
  ui_story_5043_50431301_171_dialog_content = "Ohhh! Betapa profesionalnya! Saya suka bagaimana segala sesuatunya berjalan!",
  ui_story_5043_50431301_172_dialog_content = "(Beberapa jejak pelaku sebenarnya, ya...)",
  ui_story_5043_50431301_173_dialog_content = "(Apakah Anda akhirnya menemukan sesuatu, Leyn?)",
  ui_story_5043_50431301_174_dialog_content = "Mari kita ingat apa yang terjadi di Stairway to the Skies kemarin, sesaat sebelum kejadian.",
  ui_story_5043_50431301_175_dialog_content = "Untuk melindungi patung di puncak tangga, kami berusaha menghentikan pawai.",
  ui_story_5043_50431301_176_dialog_content = "Yang mengejutkan kami, kami menemukan sekelompok Eclipsites kecil bersembunyi tepat di belakang prosesi.",
  ui_story_5043_50431301_177_dialog_content = "Saya segera melibatkan mereka dalam pertempuran. Tidak lama kemudian, Hakim Tina tertangkap olehku...",
  ui_story_5043_50431302_1_dialog_content = "Saya menendang Eclipsite pertama menuruni tangga.",
  ui_story_5043_50431302_2_dialog_content = "Yang kedua, saya tertusuk dengan senjata saya.",
  ui_story_5043_50431302_3_dialog_content = "Yang terakhir, bagaimanapun, hancur berkeping-keping oleh tinju Tina.",
  ui_story_5043_50431302_4_dialog_content = "Baiklah baiklah! Apakah detail seperti itu benar-benar diperlukan?",
  ui_story_5043_50431302_5_dialog_content = "Dengan dikalahkannya sekelompok kecil Eclipsites, Tina dan saya mulai berjalan kembali ke patung itu dan berkumpul kembali dengan yang lain.",
  ui_story_5043_50431302_6_dialog_content = "Tetapi orang banyak pada hari itu, dan menerobos mereka terbukti menjadi tugas yang sulit.",
  ui_story_5043_50431302_7_dialog_content = "Akibatnya, saya dipisahkan dari Tina di tengah keramaian... Baru setelah kejadian itu aku akhirnya melihatnya lagi.",
  ui_story_5043_50431302_8_dialog_content = "Mencoba untuk melewati semua orang itu adalah mimpi buruk... Saya hampir tidak bisa bergerak separuh waktu!",
  ui_story_5043_50431302_9_dialog_content = "Itu yang bisa kita sepakati.",
  ui_story_5043_50431302_10_dialog_content = "Tapi ini tidak membuktikan itu Tina Campbell tidak berada di TKP hari itu.",
  ui_story_5043_50431302_11_dialog_content = "Mari kita kesampingkan itu sebentar, Yang Mulia. Alih-alih, mari kita alihkan perhatian kita ke saat kejadian itu terjadi.",
  ui_story_5043_50431302_12_dialog_content = "Ketika saya akhirnya mencapai patung itu, saya disergap oleh sekelompok Eclipsites lainnya.",
  ui_story_5043_50431302_13_dialog_content = "Saat kami melawan Eclipsites, pelakunya memiliki peluang sempurna untuk menyerang.",
  ui_story_5043_50431302_14_dialog_content = "Mengambil keuntungan dari kekacauan di sekitarnya, mereka mengulurkan tangan bersarung tangan dan menghancurkan kepala patung itu.",
  ui_story_5043_50431302_15_dialog_content = "Saya berhasil memegang tangan mereka, tetapi pelakunya bersembunyi di antara Eclipsites, yang mencegah saya untuk melihat wajah atau tubuh mereka dengan jelas.",
  ui_story_5043_50431302_16_dialog_content = "Pada akhirnya, pelakunya berhasil lolos dari genggamanku dan melarikan diri, meninggalkan satu sarung tangan...",
  ui_story_5043_50431302_17_dialog_content = "Sarung tangan yang sudah disediakan sebagai bukti kunci dalam kasus tersebut, ya.",
  ui_story_5043_50431302_18_dialog_content = "Wanita Carleen dan Hakim Matthieu melakukan pekerjaan singkat tentang Eclipsites segera setelah itu, tetapi pelakunya tidak terlihat.",
  ui_story_5043_50431302_19_dialog_content = "Setelah debu mengendap, Hakim Tina akhirnya muncul kembali dan bergabung dengan kami.",
  ui_story_5043_50431302_20_dialog_content = "Dan itu, hadirin sekalian di istana, adalah laporan lengkap tentang peristiwa seputar pemenggalan patung itu.",
  ui_story_5043_50431302_21_dialog_content = "Dan akun dengan kata-kata yang sangat bagus, pada saat itu. Terima kasih atas kontribusinya, Hakim Leyn.",
  ui_story_5043_50431302_22_dialog_content = "Dengan mengingat hal tersebut, maka masuk akal jika pemilik sarung tangan tersebut adalah pelaku kejahatan tersebut.",
  ui_story_5043_50431302_23_dialog_content = "Itu, pada gilirannya, adalah alasan yang mendorong kami untuk menangkap terdakwa, Tina Campbell.",
  ui_story_5043_50431302_24_dialog_content = "Maafkan saya, Yang Mulia... Tapi Anda langsung mengambil kesimpulan.",
  ui_story_5043_50431302_25_dialog_content = "Maaf?",
  ui_story_5043_50431302_26_dialog_content = "Berdasarkan informasi yang kami kumpulkan di TKP mengenai pelakunya—",
  ui_story_5043_50431302_27_dialog_content = "Kita tahu pelakunya berhasil menghancurkan kepala patung dengan tangan kosong sambil mengenakan sarung tangan itu.",
  ui_story_5043_50431302_28_dialog_content = "Orang yang kau tangkap, di sisi lain...",
  ui_story_5043_50431302_29_dialog_content = "Apakah hanya wanita muda yang merupakan pemilik sah dari sarung tangan itu.",
  ui_story_5043_50431302_30_dialog_content = "Jika Anda membandingkan keduanya lebih dekat, Anda akan menemukan lebih banyak ketidakkonsistenan daripada yang lainnya.",
  ui_story_5043_50431302_31_dialog_content = "Saya merasa Anda terlalu banyak berpikir, Hakim Leyn.",
  ui_story_5043_50431302_32_dialog_content = "Apakah tidak masuk akal bahwa pemilik sarung tangan adalah orang yang paling mungkin memakainya di TKP?",
  ui_story_5043_50431302_33_dialog_content = "Ya, Yang Mulia... Tapi Anda melewatkan intinya.",
  ui_story_5043_50431302_34_dialog_content = "Apakah Hakim Tina terlihat seperti dia bisa menghancurkan kepala patung dengan tangan kosong?",
  ui_story_5043_50431302_35_dialog_content = "Oh? Sudut baru?",
  ui_story_5043_50431302_36_dialog_content = "Kalau dipikir-pikir, bagaimana bisa seorang gadis kecil menghancurkan patung dengan tangan kosong?",
  ui_story_5043_50431302_37_dialog_content = "Sepertinya Anda tersesat dalam proses berpikir Anda sendiri, Hakim Leyn.",
  ui_story_5043_50431302_38_dialog_content = "Apakah Anda sudah lupa apa yang Anda katakan bukan dua menit yang lalu?",
  ui_story_5043_50431302_39_dialog_content = "Saya menendang Eclipsite pertama menuruni tangga.",
  ui_story_5043_50431302_40_dialog_content = "Yang kedua, saya tertusuk dengan senjata saya.",
  ui_story_5043_50431302_41_dialog_content = "Namun, yang terakhir adalah <color=#FFB400>hancur berkeping-keping oleh tinju Tina</color>.",
  ui_story_5043_50431302_42_dialog_content = "Tentunya, Anda tahu rekan Anda lebih baik dari itu? Bagaimanapun, dia adalah pewaris Tangan Ilahi Keluarga Campbell.",
  ui_story_5043_50431302_43_dialog_content = "Untuk seseorang yang dapat sepenuhnya melenyapkan Eclipsite dengan satu pukulan, kepala patung seharusnya tidak menimbulkan masalah sama sekali.",
  ui_story_5043_50431302_44_dialog_content = "Itu benar! Dia bukan gadis biasa!",
  ui_story_5043_50431302_45_dialog_content = "Anak muda, Anda perlu lebih memikirkan deduksi Anda.",
  ui_story_5043_50431302_46_dialog_content = "(Kurasa dia kurang dari sasaran, ya?)",
  ui_story_5043_50431302_47_dialog_content = "(Jika hanya Leyn bisa selangkah lebih maju dari musuh, dan menemukan sesuatu yang luput dari perhatian mereka...)",
  ui_story_5043_50431302_48_dialog_content = "Ah iya... Tina mewarisi Tangan Ilahi.",
  ui_story_5043_50431302_49_dialog_content = "Lalu asumsinya adalah dia menggunakannya untuk menghancurkan kepala patung, benar?",
  ui_story_5043_50431302_50_dialog_content = "Benar. Lagipula itu satu-satunya kesimpulan logis.",
  ui_story_5043_50431302_51_dialog_content = "Dan sementara saya harus memuji Anda untuk metode analisis Anda yang ketat, Hakim Leyn...",
  ui_story_5043_50431302_52_dialog_content = "Untuk persidangan di masa mendatang, saya sarankan Anda membagikan analisis Anda kepada saya sebelum memulai proses kita daripada membuang-buang waktu pengadilan yang berharga.",
  ui_story_5043_50431302_53_dialog_content = "Saya tidak berpikir saya telah menyia-nyiakan waktu siapa pun, Yang Mulia.",
  ui_story_5043_50431302_54_dialog_content = "Semua kesimpulan saya adalah untuk satu-satunya tujuan membuat Anda sampai pada kesimpulan ini.",
  ui_story_5043_50431302_55_dialog_content = "Yaitu, Tina menggunakan Tangan Ilahi untuk menghancurkan kepala patung itu.",
  ui_story_5043_50431302_56_dialog_content = "... Langsung ke intinya, Hakim Leyn. Apa yang ingin kamu katakan?",
  ui_story_5043_50431302_57_dialog_content = "Sekarang setelah kita sampai pada kesimpulan ini, yang perlu kita lakukan hanyalah melihat ke belakang sekali lagi untuk menyadari kebenaran.",
  ui_story_5043_50431302_58_dialog_content = "Sarung tangan itu, bukti penting itu, bukanlah bukti kesalahannya yang tak terbantahkan, tetapi bukti ketidakbersalahannya!",
  ui_story_5043_50431302_59_dialog_content = "Apa?!",
  ui_story_5043_50431302_60_dialog_content = "Yang Mulia, izinkan saya menunjukkan kepada semua orang di pengadilan sarung tangan pelaku!",
  ui_story_5043_50431302_61_dialog_content = "Ada kemungkinan sarung tangan itu dibersihkan dari bukti yang memberatkan saat berada di tangan Anda, Yang Mulia...",
  ui_story_5043_50431302_62_dialog_content = "Tapi tidak masalah, asalkan masih sarung tangan yang sama dari TKP. Itu bisa kami pastikan, kan, Yang Mulia?",
  ui_story_5043_50431302_63_dialog_content = "Apakah Anda mempertanyakan kemampuan saya untuk menyimpan bukti kasus, salah satu tanggung jawab paling mendasar dari Balai Kehakiman?!",
  ui_story_5043_50431302_64_dialog_content = "Senang mendengarnya.",
  ui_story_5043_50431302_65_dialog_content = "Saya meminta semua orang untuk memperhatikan baik-baik sarung tangan ini.",
  ui_story_5043_50431302_66_dialog_content = "Ini sarung tangan kanan, bukan?",
  ui_story_5043_50431302_67_dialog_content = "Cukup, Hakim Leyn. Langsung ke intinya!",
  ui_story_5043_50431302_68_dialog_content = "Apa bedanya tangan mana yang digunakan—",
  ui_story_5043_50431302_69_dialog_content = "!!!",
  ui_story_5043_50431302_70_dialog_content = "Hah?",
  ui_story_5043_50431302_71_dialog_content = "Ah-!",
  ui_story_5043_50431302_72_dialog_content = "Tangan kanan! Itu menjelaskan semuanya!",
  ui_story_5043_50431302_73_dialog_content = "Tunggu, saya tidak mengerti! Apa yang sedang terjadi?!",
  ui_story_5043_50431302_74_dialog_content = "Sepertinya Anda juga sudah menyadarinya, Yang Mulia.",
  ui_story_5043_50431302_75_dialog_content = "Hanya ada satu kesalahan fatal dalam kesimpulanmu...",
  ui_story_5043_50431302_76_dialog_content = "Tangan Ilahi Tina, yang memang mampu menghancurkan kepala patung, membutuhkan penggunaannya <color=#FFB400>tangan kiri</color>.",
  ui_story_5043_50431302_77_dialog_content = "Namun, sarung tangan ini a <color=#FFB400>Pengguna tangan kanan</color> sarung tangan!",
  ui_story_5043_50431302_78_dialog_content = "Oh! Aku mengerti sekarang!!!",
  ui_story_5043_50431302_79_dialog_content = "Kiri kanan...",
  ui_story_5043_50431302_80_dialog_content = "Setelah menghabiskan seluruh persidangan untuk menekankan pentingnya bukti penting ini.",
  ui_story_5043_50431302_81_dialog_content = "Saya pikir kita semua bisa setuju dengan Anda sekarang, Yang Mulia.",
  ui_story_5043_50431302_82_dialog_content = "Sekarang kita tahu ini bukan sarung tangan yang menutupi Tangan Ilahi Tina, saya bertanya-tanya kesimpulan seperti apa yang akan ditarik?",
  ui_story_5043_50431302_83_dialog_content = "Nah, Yang Mulia? Maukah Anda berbaik hati menghiasi pengadilan dengan pikiran Anda?",
  ui_story_5043_50431302_84_dialog_content = "Kamu... Kamu...!",
  ui_story_5043_50431302_85_dialog_content = "Jalan untuk pergi, Leyn! Bukti yang sama digunakan untuk memberatkan Tina juga membuktikan dia tidak bersalah!",
  ui_story_5043_50431302_86_dialog_content = "Sepertinya timbangan akhirnya menguntungkan kita!",
  ui_story_5043_50431302_87_dialog_content = "Ini tidak bisa dipercaya...",
  ui_story_5043_50431302_88_dialog_content = "Baiklah kalau begitu. Saya tidak punya pilihan selain mengakui dan menerima bantahan Anda.",
  ui_story_5043_50431302_89_dialog_content = "Karena tidak cukup bukti pada saat ini, pengadilan tidak dapat menemukan terdakwa bersalah atas kejahatan tersebut.",
  ui_story_5043_50431302_90_dialog_content = "Oleh karena itu, pemenggal patung yang sebenarnya masih buron.",
  ui_story_5043_50431302_91_dialog_content = "Ini bagus!!!",
  ui_story_5043_50431302_92_dialog_content = "Mereka melakukannya, Carleen! Mereka benar-benar melakukannya!",
  ui_story_5043_50431302_93_dialog_content = "Memang! Ini luar biasa!",
  ui_story_5043_50431302_94_dialog_content = "Menyaksikan keadilan dipertahankan di Hall of Justice merupakan suatu kehormatan besar!",
  ui_story_5043_50431302_95_dialog_content = "Jadi kalau pelakunya masih buron...",
  ui_story_5043_50431302_96_dialog_content = "Apa itu berarti aku tidak bersalah?!",
  ui_story_5043_50431302_97_dialog_content = "Tentu saja, Tina. Anda selalu tidak bersalah.",
  ui_story_5043_50431302_98_dialog_content = "Anda berutang budi pada kami, Anda tahu? Terutama untuk pemula kita yang biasa.",
  ui_story_5043_50431302_99_dialog_content = "Untuk kasus besar pertamanya, dia melakukannya dengan sangat baik.",
  ui_story_5043_50431302_100_dialog_content = "Saya sangat setuju! Terima kasih banyak atas semua yang telah Anda lakukan untuk saya!",
  ui_story_5043_50431302_101_dialog_content = "Saya bangga memanggil Anda kolega tersayang!",
  ui_story_5043_50431302_102_dialog_content = "Hai! Apa maksudnya ini?!",
  ui_story_5043_50431302_103_dialog_content = "Setelah menghabiskan setengah hari berdebat dengan diri sendiri sampai serak, Anda bermaksud memberi tahu saya bahwa Anda salah orang?!",
  ui_story_5043_50431302_104_dialog_content = "...",
  ui_story_5043_50431302_105_dialog_content = "Menakjubkan. Luar biasa!",
  ui_story_5043_50431302_106_dialog_content = "Memaksa saya untuk duduk melalui semua pertimbangan itu, hanya untuk mengatakan bahwa kita segera kembali ke tempat kita mulai?",
  ui_story_5043_50431302_107_dialog_content = "Aku sudah memberitahumu banyak sebelumnya! Kesabaranku sudah mencapai batasnya!",
  ui_story_5043_50431302_108_dialog_content = "Jika kau tidak menyelesaikan kasus ini di penghujung hari, aku akan menyelesaikan seluruh Pengadilan Divisi Percintaan ini!!!",
  ui_story_5043_50431302_109_dialog_content = "Jangan terburu-buru, Tuanku yang baik. Seperti berdiri, kami hanya membahas setengah dari masalah.",
  ui_story_5043_50431302_110_dialog_content = "Setengah...?",
  ui_story_5043_50431302_111_dialog_content = "Duduklah di sini bersama kami, Hakim Tina.",
  ui_story_5043_50431302_112_dialog_content = "Sudah waktunya bagi orang lain untuk melayani sebagai terdakwa sekarang.",
  ui_story_5043_50431302_113_dialog_content = "Hah? Siapa yang kamu maksud...?",
  ui_story_5043_50431302_114_dialog_content = "Setelah investigasi mendalam Divisi Percintaan atas kasus ini dan semua bukti diberikan, saya, Hakim Leyn—",
  ui_story_5043_50431302_115_dialog_content = "Dan saya, Hakim Matthieu—",
  ui_story_5043_50431302_116_dialog_content = "Dengan ini menuntut Mr. Schwab Salar dengan kejahatan menghancurkan properti publik dan menumbangkan cinta!",
  ui_story_5043_50431302_117_dialog_content = "Ketua Hakim Schwab, silakan bersaksi.",
  ui_story_5043_50431302_118_dialog_content = "Apa? Dia menuduh Schwab?!",
  ui_story_5043_50431302_119_dialog_content = "Jangan bilang ini juga bagian dari rencana, PlayerName?!",
  ui_story_5043_50431302_120_dialog_content = "Anu…",
  ui_story_5043_50431302_121_dialog_content = "Ya, kami memang memiliki kecurigaan tentang Schwab kemarin, tapi...",
  ui_story_5043_50431302_122_dialog_content = "Aku tidak tahu mereka benar-benar akan menuduhnya apa pun...",
  ui_story_5043_50431302_123_dialog_content = "Apakah Anda dan yang lainnya berhasil menemukan bukti yang memberatkan?",
  ui_story_5043_50431302_124_dialog_content = "Sama sekali tak tahu…",
  ui_story_5043_50431302_125_dialog_content = "Menuduh saya, bukan?",
  ui_story_5043_50431302_126_dialog_content = "Apakah Anda tahu apa yang Anda lakukan, Hakim Leyn?",
  ui_story_5043_50431302_127_dialog_content = "Saya hanya melakukan tugas saya, Pak.",
  ui_story_5043_50431302_128_dialog_content = "Hmph. Anda lebih baik berharap begitu.",
  ui_story_5043_50431302_129_dialog_content = "Karena saya dapat memberi tahu Anda sekarang, saya memiliki alibi yang tidak perlu dipertanyakan untuk masing-masing dari ketiga insiden tersebut.",
  ui_story_5043_50431302_130_dialog_content = "Ke mana pun pertanyaan konyol ini mengarah, ketahuilah bahwa seluruh Balai Kehakiman akan menguatkan cerita saya.",
  ui_story_5043_50431302_131_dialog_content = "Saya tidak punya apa-apa lagi untuk dikatakan tentang tuduhan tidak masuk akal Anda untuk saat ini.",
  ui_story_5043_50431302_132_dialog_content = "Yakinlah, Hakim Schwab, pertanyaan saya singkat dan sederhana.",
  ui_story_5043_50431302_133_dialog_content = "Saya juga dapat membuktikan alibi kedap udara Anda untuk ketiga contoh kesalahan dalam kasus ini.",
  ui_story_5043_50431302_134_dialog_content = "Namun Anda menolak untuk menarik tuduhan sia-sia Anda?",
  ui_story_5043_50431302_135_dialog_content = "Betul pak, karena pelakunya tidak perlu hadir di TKP.",
  ui_story_5043_50431302_136_dialog_content = "May Saya memanggil saksi baru?",
  ui_story_5043_50431302_137_dialog_content = "Seorang saksi?",
  ui_story_5043_50431302_138_dialog_content = "Silakan datangi mimbar dan bersiaplah untuk bersumpah di bawah sumpah.",
  ui_story_5043_50431302_139_dialog_content = "(Kapan dia menemukan saksi untuk ini?)",
  ui_story_5043_50431302_140_dialog_content = "(Aku ingin tahu siapa itu ...)",
  ui_story_5043_50431302_141_dialog_content = "B-Bisakah saya...",
  ui_story_5043_50431302_142_dialog_content = "Bisakah saya bicara sekarang?",
  ui_story_5043_50431302_143_dialog_content = "Sebuah Eclipsite! Dan yang bisa berbicara, tidak kurang!",
  ui_story_5043_50431302_144_dialog_content = "T-Toto?!?",
  ui_story_5043_50431302_145_dialog_content = "Hah? Apa yang dia lakukan di sini?!",
  ui_story_5043_50431302_146_dialog_content = "Memiliki Eclipsite sebagai saksi... Apa yang dia pikirkan?",
  ui_story_5043_50431302_147_dialog_content = "Apakah Anda kehilangan pikiran Anda ?! Beraninya kau membawa makhluk kotor itu ke halaman suci Balai Kehakiman!",
  ui_story_5043_50431302_148_dialog_content = "Apakah Anda berusaha merusak semua yang telah kami bangun ?!",
  ui_story_5043_50431302_149_dialog_content = "Tidak ada alasan untuk khawatir. Kami telah memastikan, tanpa ragu, bahwa Eclipsite ini sama sekali tidak berbahaya.",
  ui_story_5043_50431302_150_dialog_content = "Tidak ada seorang pun di sini yang dalam bahaya. Dia hanya di sini untuk membantu kita mengungkap kebenaran dengan kesaksiannya, tidak lebih.",
  ui_story_5043_50431302_151_dialog_content = "Saya yakin kita semua ada di sini untuk alasan yang sama, ya?",
  ui_story_5043_50431302_152_dialog_content = "Hmmm... Nah, jika kesaksiannya melanjutkan persidangan, saya kira itu bisa diterima.",
  ui_story_5043_50431302_153_dialog_content = "Toto terlihat lebih kurus dari sebelumnya...",
  ui_story_5043_50431302_154_dialog_content = "Ini mungkin belum pernah terjadi sebelumnya dalam seluruh sejarah Hall of Justice... Aku ingin tahu kesaksian seperti apa yang akan dia berikan?",
  ui_story_5043_50431302_155_dialog_content = "A-Izinkan saya untuk memperkenalkan m-diri saya sendiri.",
  ui_story_5043_50431302_156_dialog_content = "T-Tolong jangan takut padaku!",
  ui_story_5043_50431302_157_dialog_content = "Aku tidak lebih dari Eclipsite rata-rata tingkat rendah.",
  ui_story_5043_50431302_158_dialog_content = "Aku tidak sengaja memakan benda percobaan di Gannon City...",
  ui_story_5043_50431302_159_dialog_content = "Aku tidak tahu apa itu, tapi...",
  ui_story_5043_50431302_160_dialog_content = "Tubuh saya mulai berubah, dan pada saat yang sama, saya memperoleh tingkat perasaan tertentu!",
  ui_story_5043_50431302_161_dialog_content = "Hmph! Betapa tipikal Federasi Illumina untuk mencoba-coba penelitian yang tak terkatakan seperti itu!",
  ui_story_5043_50431302_162_dialog_content = "Wow... Universese-nya menjadi jauh lebih lancar sejak terakhir kali kita berbicara?",
  ui_story_5043_50431302_163_dialog_content = "Sejak saat itu, m-hubunganku dengan Eclipsites lain semakin melemah...",
  ui_story_5043_50431302_164_dialog_content = "Saya tidak bisa mengendalikan mereka lagi tetapi mereka juga tidak bisa mengendalikan saya!",
  ui_story_5043_50431302_165_dialog_content = "Hidup di antara Eclipsites lainnya semakin sulit... Tidak ada cara bagi saya untuk menyelesaikan pekerjaan saya tanpa komplikasi terus-menerus...",
  ui_story_5043_50431302_166_dialog_content = "Pemimpin tidak bisa mentolerirnya, dan akhirnya memaksa saya untuk pergi...",
  ui_story_5043_50431302_167_dialog_content = "Dia berkata, jika kau ingin membuat masalah, pergilah membuat masalah untuk Aurorian...",
  ui_story_5043_50431302_168_dialog_content = "Emm, jadi ada Eclipsites yang bahkan Eclipsites tidak tahan.",
  ui_story_5043_50431302_169_dialog_content = "Jangan merasa kasihan untuk itu. Musuh dari musuhmu belum tentu menjadi temanmu.",
  ui_story_5043_50431302_170_dialog_content = "Tidak lama kemudian, saya mulai mempelajari semua yang saya bisa tentang Aurorian. Bahasa mereka, budaya mereka...",
  ui_story_5043_50431302_171_dialog_content = "Saya melakukan perjalanan ke seluruh negeri, mencari pekerjaan di mana pun saya bisa. Tapi ke mana pun aku pergi, aku terus dipecat...",
  ui_story_5043_50431302_172_dialog_content = "Hidup ini sulit, tetapi saya jauh lebih bahagia daripada sebelumnya!",
  ui_story_5043_50431302_173_dialog_content = "Saya tidak akan pernah menyakiti siapa pun.",
  ui_story_5043_50431302_174_dialog_content = "K-Karena aku suka hidup sebagai Aurorian!",
  ui_story_5043_50431302_X174_dialog_content = "Aku tidak ingin dibenci lagi!",
  ui_story_5043_50431302_175_dialog_content = "Dia benar! Toto tidak akan pernah menyakiti lalat!",
  ui_story_5043_50431302_176_dialog_content = "Dia bahkan lebih manis dari kebanyakan Aurorian! Tolong jangan merasa terancam olehnya!",
  ui_story_5043_50431302_177_dialog_content = "Tsk, Eclipsite yang hidup seperti Aurorian...",
  ui_story_5043_50431302_178_dialog_content = "Waktu telah berubah, tampaknya!",
  ui_story_5043_50431302_179_dialog_content = "Terima kasih, Toto. Itu cukup untuk perkenalan.",
  ui_story_5043_50431302_180_dialog_content = "Tolong beri tahu pengadilan alasan Anda datang ke sini dan menjadi saksi dalam persidangan hari ini.",
  ui_story_5043_50431302_181_dialog_content = "A-aku datang untuk melaporkan seorang Aurorian atas perilaku melanggar hukum!",
  ui_story_5043_50431302_182_dialog_content = "Dan siapa itu?",
  ui_story_5043_50431302_183_dialog_content = "Pria itu disana! Yang duduk di atas orang lain. Pria bernama Schwab!",
  ui_story_5043_50431302_184_dialog_content = "Kamu...",
  ui_story_5043_50431302_185_dialog_content = "Kejahatan apa yang dia lakukan?",
  ui_story_5043_50431302_186_dialog_content = "K-Dia yang menghancurkan patung-patung itu!",
  ui_story_5043_50431302_187_dialog_content = "Dia memiliki alibi yang membuktikan bahwa dia tidak pernah berada di TKP, jadi apa yang membuatmu begitu yakin bahwa dia adalah pelakunya?",
  ui_story_5043_50431302_188_dialog_content = "Dia tidak perlu berada di sana untuk menghancurkan mereka! Itu karena dia bisa... Dia bisa...",
  ui_story_5043_50431302_189_dialog_content = "Dia bisa apa?",
  ui_story_5043_50431302_190_dialog_content = "Dia bisa mengendalikan Eclipsites!!!",
  ui_story_5043_50431401_1_dialog_content = "Kontrol Eclipsites?!",
  ui_story_5043_50431401_2_dialog_content = "Astaga! Apakah Anda tahu tahu apa yang Anda maksudkan?",
  ui_story_5043_50431401_3_dialog_content = "Mendampingi Eclipsites adalah kejahatan yang paling menyedihkan di sini di Lumopolis!",
  ui_story_5043_50431401_4_dialog_content = "Tsk! Kesaksian yang konyol!",
  ui_story_5043_50431401_5_dialog_content = "Apakah Anda benar-benar berpikir bahwa Anda dapat menuduh saya bersekongkol dengan Eclipsites dengan menggunakan kesaksian salah satu dari mereka ?!",
  ui_story_5043_50431401_6_dialog_content = "Apa ejekan keadilan! Kesaksian seorang pemabuk akan mengandung lebih banyak air daripada kesaksian Eclipsite yang busuk!",
  ui_story_5043_50431401_7_dialog_content = "Dalam hal menjebak orang lain, keterampilan Anda masih sangat kurang, Leyn!",
  ui_story_5043_50431401_8_dialog_content = "Apakah begitu? Kalau begitu mungkin saya harus mengambil satu atau dua halaman dari buku Anda, Hakim Schwab?",
  ui_story_5043_50431401_9_dialog_content = "Kau…!",
  ui_story_5043_50431401_10_dialog_content = "Saya tidak perlu menjebak Anda untuk membuktikan kesalahan Anda.",
  ui_story_5043_50431401_11_dialog_content = "Seperti yang Anda katakan, kesaksian dari satu Eclipsite hampir tidak cukup untuk melibatkan Anda atas kejahatan ini.",
  ui_story_5043_50431401_12_dialog_content = "Tapi bagaimana jika Eclipsite memainkan peran khusus dalam kasus ini?",
  ui_story_5043_50431401_13_dialog_content = "Peran khusus...?",
  ui_story_5043_50431401_14_dialog_content = "Jika Anda akan begitu baik, Toto?",
  ui_story_5043_50431401_15_dialog_content = "aku minta maaf!!!",
  ui_story_5043_50431401_16_dialog_content = "Saya membuat kesalahan... Saya akan menerima hukuman saya, di sini dan sekarang!!!",
  ui_story_5043_50431401_17_dialog_content = "Hah?",
  ui_story_5043_50431401_18_dialog_content = "Apa maksudmu, Toto? Kesalahan apa yang kamu bicarakan?",
  ui_story_5043_50431401_19_dialog_content = "Sejujurnya, suatu saat ia menuduh hakim ketua, dan selanjutnya, ia mengakui kesalahannya sendiri...",
  ui_story_5043_50431401_20_dialog_content = "Berhentilah membuang-buang waktu dan bicaralah dengan jelas, kataku!",
  ui_story_5043_50431401_21_dialog_content = "M-Maaf! I-Kebenarannya adalah...",
  ui_story_5043_50431401_22_dialog_content = "Akulah yang menghancurkan patung-patung itu!",
  ui_story_5043_50431401_23_dialog_content = "Apa?!",
  ui_story_5043_50431401_24_dialog_content = "Hah? Jadi itu kamu?!",
  ui_story_5043_50431401_25_dialog_content = "Kaulah yang menghancurkan istri dan kekasihku?!",
  ui_story_5043_50431401_26_dialog_content = "Ya, itu aku.",
  ui_story_5043_50431401_27_dialog_content = "Kenapa, kamu busuk, kecil...!",
  ui_story_5043_50431401_28_dialog_content = "T-Tunggu! Aku tidak melakukannya dengan sengaja! Saya terpaksa!",
  ui_story_5043_50431401_29_dialog_content = "Schwab adalah orang yang membuatku melakukannya setiap saat!",
  ui_story_5043_50431401_30_dialog_content = "Tolong, semuanya. Kasihanilah aku—!",
  ui_story_5043_50431401_31_dialog_content = "<size=45>Apa?!?</size>",
  ui_story_5043_50431401_32_dialog_content = "...",
  ui_story_5043_50431401_33_dialog_content = "Benarkah ini yang terjadi...?",
  ui_story_5043_50431401_34_dialog_content = "I-Semuanya dimulai sekitar dua minggu yang lalu...",
  ui_story_5043_50431401_35_dialog_content = "Saya baru saja tiba di Lumopolis, dan saya bersiap untuk mencari pekerjaan.",
  ui_story_5043_50431401_36_dialog_content = "Tapi Lumopolis sangat besar, dan aku tidak terlalu mengenal jalanan... Sebelum aku menyadarinya, hari sudah malam.",
  ui_story_5043_50431401_37_dialog_content = "Setelah itu, saya... Saya bertemu dengan sekelompok Eclipsites di Halaman Lumopolis.",
  ui_story_5043_50431401_38_dialog_content = "Nah, ada beberapa penampakan aktivitas Eclipsite di kota belakangan ini.",
  ui_story_5043_50431401_39_dialog_content = "Ini benar, setidaknya.",
  ui_story_5043_50431401_40_dialog_content = "Aku tidak berharap menemukan lebih banyak jenisku di kota. Rasanya aneh.",
  ui_story_5043_50431401_41_dialog_content = "Ketika saya berdiri di sana mencoba memahami banyak hal, mereka menganggap saya hanyalah Eclipsite yang hilang.",
  ui_story_5043_50431401_42_dialog_content = "Mereka sangat bersikeras membuat saya bergabung dengan barisan mereka.",
  ui_story_5043_50431401_43_dialog_content = "Meskipun kebingungan, saya mengikuti mereka sampai akhirnya...",
  ui_story_5043_50431401_44_dialog_content = "Kami tiba di Salar Manor.",
  ui_story_5043_50431401_45_dialog_content = "Hai! Itu rumah Schwab!",
  ui_story_5043_50431401_46_dialog_content = "Itu benar, dan di situlah aku melihatnya untuk pertama kali.",
  ui_story_5043_50431401_47_dialog_content = "Itu adalah hal yang paling mengejutkan yang pernah saya lihat...",
  ui_story_5043_50431401_48_dialog_content = "Dia memerintahkan Eclipsites berkeliling seolah-olah mereka adalah budak.",
  ui_story_5043_50431401_49_dialog_content = "Dan Eclipsites... Mereka mematuhi setiap perintahnya!",
  ui_story_5043_50431401_50_dialog_content = "A-aku tidak punya cara untuk melarikan diri... Jadi aku harus berpura-pura menjadi salah satu dari mereka.",
  ui_story_5043_50431401_51_dialog_content = "Saat itulah dia mengunci kita semua di ruang bawah tanah Salar Manor!",
  ui_story_5043_50431401_52_dialog_content = "Ruang bawah tanah?!",
  ui_story_5043_50431401_53_dialog_content = "Jadi dia menahan Eclipsites itu di sana selama ini! Tidak heran...",
  ui_story_5043_50431401_54_dialog_content = "Apakah Anda pernah ke sana sebelumnya?",
  ui_story_5043_50431401_55_dialog_content = "Er, kurasa ini bukan waktu atau tempat yang tepat untuk memberitahumu...",
  ui_story_5043_50431401_56_dialog_content = "Saya akan membicarakannya dengan Anda setelah persidangan!",
  ui_story_5043_50431401_57_dialog_content = "<size=45>Hentikan omong kosong ini sekarang juga!</size>",
  ui_story_5043_50431401_58_dialog_content = "Bisakah Anda percaya codswallop mutlak yang dimuntahkan dari mulut makhluk busuk ini?",
  ui_story_5043_50431401_59_dialog_content = "Saya tidak punya alasan untuk menanggung fitnah menggelikan ini lagi!!!",
  ui_story_5043_50431401_60_dialog_content = "Kita akan lihat apakah itu fitnah segera, Hakim Schwab.",
  ui_story_5043_50431401_61_dialog_content = "Tolong beritahu kami apa yang terjadi setelah itu, Toto.",
  ui_story_5043_50431401_62_dialog_content = "Meskipun bagian dari kesaksian Anda ini mengejutkan, memang, ini tidak ada hubungannya dengan pemenggalan patung berantai.",
  ui_story_5043_50431401_63_dialog_content = "Oh, benar! Biarkan saya mengikatnya kembali ke kasing!",
  ui_story_5043_50431401_64_dialog_content = "Sesekali, Schwab akan menarik beberapa dari kami keluar dari ruang bawah tanah untuk melaksanakan perintahnya.",
  ui_story_5043_50431401_65_dialog_content = "A-aku sangat membutuhkan kesempatan untuk melarikan diri, jadi aku bertindak lebih gelisah daripada saudara-saudaraku.",
  ui_story_5043_50431401_66_dialog_content = "Dan akhirnya... Dia memilihku untuk salah satu tugasnya.",
  ui_story_5043_50431401_67_dialog_content = "Secara khusus... Dia mengatakan kepada saya untuk menunggu sampai Balon Bulan naik ke langit, dan kemudian hancurkan patung-patung di bawahnya!",
  ui_story_5043_50431401_68_dialog_content = "Oh! Itu sangat cocok dengan pengetahuan yang kami miliki tentang kasus ini!",
  ui_story_5043_50431401_69_dialog_content = "Dua kali pertama adalah patung di depan Hall of Justice dan Meadow Square.",
  ui_story_5043_50431401_70_dialog_content = "Di depan Aula Kehakiman?!",
  ui_story_5043_50431401_71_dialog_content = "Itu adalah... Kekasihku!",
  ui_story_5043_50431401_72_dialog_content = "Saya sangat menyesal atas kehilangan Anda, Tn. Byron.",
  ui_story_5043_50431401_73_dialog_content = "Mungkin karena dua kali pertama berjalan begitu lancar... Tapi Schwab meminta lebih banyak dariku untuk ketiga kalinya.",
  ui_story_5043_50431401_74_dialog_content = "K-Dia bilang... Untuk memakai sarung tangan aneh sebelum memecahkan patung ketiga...",
  ui_story_5043_50431401_75_dialog_content = "Itu menjelaskan sarung tangan!!!",
  ui_story_5043_50431401_76_dialog_content = "Dan begitu saya selesai, saya harus meninggalkan sarung tangan di TKP.",
  ui_story_5043_50431401_77_dialog_content = "Saat itulah saya pergi ke Stairway to the Skies dengan sekelompok Eclipsites...",
  ui_story_5043_50431401_78_dialog_content = "Tapi setelah aku menghancurkan kepala patung itu, Hakim Leyn berhasil meraih tangan kanan saya... Saya hampir tidak bisa menghindari penangkapan hari itu.",
  ui_story_5043_50431401_79_dialog_content = "Syukurlah, saya dapat melepaskan tangan saya dari sarung tangan dan melarikan diri... Dengan itu, \"tugas\" saya berhasil.",
  ui_story_5043_50431401_80_dialog_content = "Apakah ini sarung tangan yang Anda tinggalkan?",
  ui_story_5043_50431401_81_dialog_content = "Ya! Itu dia!",
  ui_story_5043_50431401_82_dialog_content = "Itu bertambah! Semuanya bertambah sekarang!",
  ui_story_5043_50431401_83_dialog_content = "Kesaksian Toto tampaknya sejalan dengan bukti yang diberikan dalam persidangan ini.",
  ui_story_5043_50431401_84_dialog_content = "Selanjutnya mari kita...",
  ui_story_5043_50431401_85_dialog_content = "Hmph! \"Berbaris,\" katamu?",
  ui_story_5043_50431401_86_dialog_content = "\"Kesaksian\" suaranya ini sepenuhnya dilatih! Narasi yang benar-benar dipalsukan!",
  ui_story_5043_50431401_87_dialog_content = "Apakah ada bukti, apapun, yang membuktikan bahkan satu kalimat dari apa yang dia katakan adalah kebenaran?!",
  ui_story_5043_50431401_88_dialog_content = "Jadi meskipun dia bersedia untuk mengaku bersalah, Anda masih belum menganggap kesaksiannya cukup dapat diandalkan, Hakim Schwab?",
  ui_story_5043_50431401_89_dialog_content = "Tentu saja tidak! Hanya karena seorang saksi mengaku bersalah bukan berarti mereka pelakunya!",
  ui_story_5043_50431401_90_dialog_content = "Saya punya lebih dari cukup alasan untuk curiga bahwa seseorang membeli Eclipsite ini untuk menjebak saya dengannya.",
  ui_story_5043_50431401_91_dialog_content = "Lagi pula, menggunakan bentuk kehidupan yang lebih rendah untuk memberatkan hakim berpangkat tinggi akan sangat murah, tidakkah Anda setuju?",
  ui_story_5043_50431401_92_dialog_content = "A-Apa maksudnya itu?! K-Selain itu, k-kaulah yang memberatkanku!!",
  ui_story_5043_50431401_93_dialog_content = "Aku baru saja datang ke Lumopolis untuk mencari pekerjaan... Aku tidak pernah ingin ditangkap dan diperintah karena rencanamu!",
  ui_story_5043_50431401_94_dialog_content = "Jika seseorang tidak membiarkan pintu ruang bawah tanah terbuka kemarin, saya tidak akan pernah menemukan kebebasan saya lagi!",
  ui_story_5043_50431401_95_dialog_content = "Begitu... Sepertinya ruang bawah tanah ini cukup menarik.",
  ui_story_5043_50431401_96_dialog_content = "Omong kosong! Ini memuntahkan omong kosong lagi!",
  ui_story_5043_50431401_97_dialog_content = "Rumah saya tidak memiliki ruang bawah tanah apa pun!",
  ui_story_5043_50431401_98_dialog_content = "Oh ya? Mengapa kita tidak mengirim seseorang untuk mencarinya dan mendengar apa yang mereka katakan?!",
  ui_story_5043_50431401_99_dialog_content = "Cari rumah saya? Itu ilegal, monster bodoh!",
  ui_story_5043_50431401_100_dialog_content = "Privasi Keluarga Salar berhak atas perlindungan hukum sepenuhnya!",
  ui_story_5043_50431401_101_dialog_content = "Tapi bagaimana mungkin...?",
  ui_story_5043_50431401_102_dialog_content = "Hakim Schwab benar sekali. Kami tidak punya hak untuk melakukan penyelidikan ke kediaman pribadi Keluarga Salar.",
  ui_story_5043_50431401_103_dialog_content = "...",
  ui_story_5043_50431401_104_dialog_content = "Kecuali, tentu saja, Anda telah membuktikan diri Anda bersalah.",
  ui_story_5043_50431401_105_dialog_content = "Apa?!?",
  ui_story_5043_50431401_106_dialog_content = "Ck...",
  ui_story_5043_50431401_107_dialog_content = "Saya yakin Anda juga menyadarinya, Hakim Schwab. Lagi pula, kata-kata itu berasal dari mulutmu sendiri ...",
  ui_story_5043_50431401_108_dialog_content = "\"Hanya karena seorang saksi mengaku bersalah bukan berarti mereka pelakunya.\"",
  ui_story_5043_50431401_109_dialog_content = "...",
  ui_story_5043_50431401_110_dialog_content = "Anda mengucapkan kata-kata itu karena Anda tahu semuanya bergantung pada kata-kata itu.",
  ui_story_5043_50431401_111_dialog_content = "Saat Balai Kehakiman memutuskan dia bersalah, semua yang dia katakan akan diperiksa tingkat tertinggi.",
  ui_story_5043_50431401_112_dialog_content = "Itu karena kesaksiannya juga merupakan pengakuan bersalah.",
  ui_story_5043_50431401_113_dialog_content = "Dan jika pengadilan menerima kesaksian Eclipsite ini, itu juga menerima fakta bahwa dia memberontak terhadap seseorang yang menarik tali dari belakang layar.",
  ui_story_5043_50431401_114_dialog_content = "Balai Kehakiman kemudian akan diberikan setiap otoritas untuk menyelidiki unsur-unsur kesaksian Toto sampai batas hukum yang paling tinggi.",
  ui_story_5043_50431401_115_dialog_content = "Jika itu terjadi, pertanyaan apakah Salar Manor memiliki ruang bawah tanah atau tidak akan terjawab lebih cepat daripada nanti.",
  ui_story_5043_50431401_116_dialog_content = "Luangkan saya penemuan Anda, Leyn. Saya tahu betul apa yang Anda rencanakan.",
  ui_story_5043_50431401_117_dialog_content = "Anda hanya menggunakan kasus yang tidak penting dan Eclipsite yang bahkan lebih tidak penting untuk melanggar privasi Keluarga Salar.",
  ui_story_5043_50431401_118_dialog_content = "Tandai kata-kataku, Leyn. Anda tidak akan berhasil!",
  ui_story_5043_50431401_119_dialog_content = "Hai! Kasus siapa yang Anda sebut \"tidak penting\"?!",
  ui_story_5043_50431401_120_dialog_content = "Tutup mulutmu, bajingan!",
  ui_story_5043_50431401_121_dialog_content = "A-Apa itu...?!",
  ui_story_5043_50431401_122_dialog_content = "Aku sudah muak dengan lelucon percobaan ini!",
  ui_story_5043_50431401_123_dialog_content = "Sebagai hakim ketua, saya menyatakan bahwa kesaksian Eclipsite tidak ada hubungannya dengan kasus ini!",
  ui_story_5043_50431401_124_dialog_content = "Seperti yang dinyatakan sebelumnya, sidang kasus ini harus ditunda karena kurangnya bukti yang kuat saat ini.",
  ui_story_5043_50431401_125_dialog_content = "Pengadilan ditunda sampai hari dimana bukti konklusif terungkap—",
  ui_story_5043_50431401_126_dialog_content = "T-Tunggu! Saya punya bukti kesalahan saya!",
  ui_story_5043_50431401_127_dialog_content = "!!!",
  ui_story_5043_50431401_128_dialog_content = "Ada di sini! Tepat di ruang sidang ini!",
  ui_story_5043_50431401_129_dialog_content = "Biar saya tebak, cerita sia-sia lain yang dimaksudkan untuk melibatkan saya?",
  ui_story_5043_50431401_130_dialog_content = "Saya punya bukti! Benar-benar!",
  ui_story_5043_50431401_131_dialog_content = "Dan ini buktinya apa toto?",
  ui_story_5043_50431401_132_dialog_content = "Itu sarung tangan yang tertinggal di TKP!",
  ui_story_5043_50431401_133_dialog_content = "Sarung tangan...?",
  ui_story_5043_50431401_134_dialog_content = "Aku yakin Schwab sudah membersihkan sarung tangannya untuk menghilangkan jejak Eclipsites...",
  ui_story_5043_50431401_135_dialog_content = "Tapi sebelum saya memecahkan patung itu, saya menggunakan kuku saya untuk membuat lubang di sarung tangan!",
  ui_story_5043_50431401_136_dialog_content = "I-Itu bukan sesuatu yang bisa dia basuh begitu saja!",
  ui_story_5043_50431401_137_dialog_content = "Apa?!?",
  ui_story_5043_50431401_138_dialog_content = "Jadi begitu. Jadi jika kita bisa menemukan lubang di sarung tangan itu, itu membuktikan bahwa kaulah yang memakainya.",
  ui_story_5043_50431401_139_dialog_content = "Yang, pada gilirannya, akan membuktikan bahwa Anda adalah pelaku kejahatan tersebut.",
  ui_story_5043_50431401_140_dialog_content = "Benar sekali!",
  ui_story_5043_50431401_141_dialog_content = "Hakim Schwab, bisakah kami memeriksa bukti itu sekali lagi?",
  ui_story_5043_50431401_142_dialog_content = "...",
  ui_story_5043_50431401_143_dialog_content = "Tolong serahkan untuk dilihat pengadilan.",
  ui_story_5043_50431401_144_dialog_content = "Jika pengadilan akan segera ditunda, saya berjanji tidak akan lama. Ini akan menjadi pesanan bisnis terakhir kami untuk hari ini.",
  ui_story_5043_50431401_145_dialog_content = "...",
  ui_story_5043_50431401_146_dialog_content = "Hakim Schwab?",
  ui_story_5043_50431401_147_dialog_content = "... Ugh.",
  ui_story_5043_50431401_148_dialog_content = "Inilah tepatnya mengapa saya berpikir <color=#FFB400>cinta itu menjijikkan</color>.",
  ui_story_5043_50431401_149_dialog_content = "Apa?!",
  ui_story_5043_50431401_150_dialog_content = "Tunggu, apakah itu berarti dia...?",
  ui_story_5043_50431401_151_dialog_content = "Saya merasa menjijikkan, dikelilingi oleh begitu banyak orang biasa yang memujanya.",
  ui_story_5043_50431401_152_dialog_content = "Terus-menerus mendekati saya, terus-menerus mencoba mengorek kehidupan pribadi saya. Orang bodoh yang lancang!",
  ui_story_5043_50431401_153_dialog_content = "Dan ya, kalian sangat mengingatkan saya pada mereka.",
  ui_story_5043_50431401_154_dialog_content = "Anda mengatakan Anda menemukan cinta \"menjijikkan\"?",
  ui_story_5043_50431401_155_dialog_content = "Tentu saja! Apa yang kalian sebut cinta tidak lebih dari mimpi buruk yang tak terhindarkan!",
  ui_story_5043_50431401_156_dialog_content = "Dikelilingi oleh teman-teman saya setiap hari, harus menanggung sanjungan berlebihan mereka di setiap kesempatan.",
  ui_story_5043_50431401_157_dialog_content = "Sebagai seorang siswa, meja saya penuh dengan surat cinta, dan rumah saya dipenuhi dengan hadiah selama liburan hanya untuk saya.",
  ui_story_5043_50431401_158_dialog_content = "Apakah kalian tahu betapa menyakitkannya dicintai oleh semua orang?!?",
  ui_story_5043_50431401_159_dialog_content = "...",
  ui_story_5043_50431401_160_dialog_content = "... Apa sih yang dia bicarakan?",
  ui_story_5043_50431401_161_dialog_content = "Aku pun tidak tahu jawabannya.",
  ui_story_5043_50431401_162_dialog_content = "Awalnya, saya pikir semuanya akan menjadi lebih baik setelah saya mulai bekerja.",
  ui_story_5043_50431401_163_dialog_content = "Aku tidak pernah menyangka gelombang cinta yang memicu muntah akan menyapu seluruh kota seperti ini!",
  ui_story_5043_50431401_164_dialog_content = "Dan seolah menambah penderitaanku, mereka menjadikanku hakim ketua Divisi Percintaan yang memalukan ini di dalam Balai Kehakiman!",
  ui_story_5043_50431401_165_dialog_content = "Itu benar. Saya tidak tahan lagi, jadi saya merencanakan penghancuran patung-patung itu!!!",
  ui_story_5043_50431401_166_dialog_content = "Saya tahu penyelenggara acara dangkal itu berencana untuk menggunakannya sebagai pusat perayaan keji mereka, dan saya bersumpah untuk menghentikan mereka dengan cara apa pun!",
  ui_story_5043_50431401_167_dialog_content = "Kamu...",
  ui_story_5043_50431401_168_dialog_content = "Anda adalah orang yang dangkal karena menggunakan kekerasan untuk mengirimkan pesan kebencian Anda!",
  ui_story_5043_50431401_169_dialog_content = "Jadi itu sebabnya kau memerintahkan Eclipsites untuk menghancurkan patung-patung itu?",
  ui_story_5043_50431401_170_dialog_content = "Ya... akulah yang mengirim mereka. Sifat kotor mereka sempurna untuk mencemarkan apa yang disebut \"perayaan cinta\".",
  ui_story_5043_50431401_171_dialog_content = "Apakah ini berarti saya dapat menganggap semua yang baru saja Anda katakan sebagai pengakuan bersalah?",
  ui_story_5043_50431401_172_dialog_content = "Anda dapat membuang formalitas palsu sekarang, Leyn.",
  ui_story_5043_50431401_173_dialog_content = "Anda sudah mendapatkan semua bukti yang Anda butuhkan. Anda menang.",
  ui_story_5043_50431401_174_dialog_content = "Satu-satunya kesalahan saya adalah saya lupa untuk menghancurkan \"alat\" yang saya gunakan untuk kejahatan tersebut... Saya tidak pernah menyangka akan kembali untuk bersaksi melawan saya seperti ini.",
  ui_story_5043_50431401_175_dialog_content = "...",
  ui_story_5043_50431401_176_dialog_content = "Tidak, Swab. Alasan Anda kalah tidak terlalu rumit.",
  ui_story_5043_50431401_177_dialog_content = "Alasan Anda kalah adalah karena Anda tidak menunjukkan sarung tangan itu kepada kami.",
  ui_story_5043_50431401_178_dialog_content = "<size=45>Apa?!?</size>",
  ui_story_5043_50431401_179_dialog_content = "Tunggu sebentar! Bukankah sarung tangan adalah bukti yang kita butuhkan untuk menang?!",
  ui_story_5043_50431401_180_dialog_content = "Mungkinkah... itu semua hanya gertakan?",
  ui_story_5043_50431401_181_dialog_content = "Wah, syukurlah sudah berakhir! Akhirnya aku bisa bernafas normal sekarang.",
  ui_story_5043_50431401_182_dialog_content = "Saya harus mengatakan, Leyn, Anda benar-benar ahli penyesatan!",
  ui_story_5043_50431401_183_dialog_content = "Kalian... Kalian menipuku?!",
  ui_story_5043_50431401_184_dialog_content = "I-Eclipsite terkutuk itu tidak pernah meninggalkan lubang apapun di dalamnya!!!",
  ui_story_5043_50431401_185_dialog_content = "Heheh... Tapi tunggu, masih ada lagi!",
  ui_story_5043_50431401_186_dialog_content = "Tidakkah menurut Anda Anda menganggapnya terlalu kebetulan?",
  ui_story_5043_50431401_187_dialog_content = "Bahwa satu-satunya Eclipsite yang berhasil kabur dari rumahmu, adalah orang yang sama yang kau perintahkan untuk menghancurkan patung-patung itu?",
  ui_story_5043_50431401_188_dialog_content = "Jangan bilang kamu...",
  ui_story_5043_50431401_189_dialog_content = "<color=#e8d9bb>Kemarin...</color>",
  ui_story_5043_50431401_190_dialog_content = "Siap untuk sedikit lembur, kalau begitu?",
  ui_story_5043_50431401_191_dialog_content = "Tentu saja. Dengan kasus yang semakin tidak jelas, tugas saya adalah mengumpulkan informasi sebanyak mungkin sebelum persidangan.",
  ui_story_5043_50431401_192_dialog_content = "Tetap saja, saya tidak menyangka Anda akan memilih untuk ikut dengan saya.",
  ui_story_5043_50431401_193_dialog_content = "Cih! Katakan padaku, orang biasa, apakah itu penghinaan terhadap etos kerjaku atau persahabatanku dengan Tina baru saja?",
  ui_story_5043_50431401_194_dialog_content = "Tidak masalah, saya kira. Mari kita kesampingkan perbedaan kita untuk saat ini, dan fokus pada kasus ini...",
  ui_story_5043_50431401_195_dialog_content = "M-Maaf mengganggu, tapi apakah Hall of Justice masih buka?",
  ui_story_5043_50431401_196_dialog_content = "Apa ini? Sebuah Eclipsite?",
  ui_story_5043_50431401_197_dialog_content = "Dan di depan pintu Hall of Justice, tidak kurang! Bersiaplah untuk mati, iblis!",
  ui_story_5043_50431401_198_dialog_content = "T-Tunggu, jangan sakiti aku! Saya di sini untuk melaporkan kejahatan!!!",
  ui_story_5043_50431401_199_dialog_content = "Maafkan saya? Eclipsite melaporkan kejahatan?",
  ui_story_5043_50431401_200_dialog_content = "Mari kita dengarkan apa yang dia katakan. Selain itu, jika dia menimbulkan masalah, memusnahkannya tidak akan menjadi masalah.",
  ui_story_5043_50431401_201_dialog_content = "Bagus. Beritahu kami tentang kejahatan ini. Dan membuatnya cepat!",
  ui_story_5043_50431401_202_dialog_content = "B-baiklah!",
  ui_story_5043_50431401_203_dialog_content = "A-Izinkan saya untuk memperkenalkan m-diri saya ...",
  ui_story_5043_50431401_204_dialog_content = "<color=#e8d9bb>Sepuluh menit kemudian...</color>",
  ui_story_5043_50431401_205_dialog_content = "... Dan saat itulah dia mengumpulkan kami semua dan mengunci kami di ruang bawah tanah Salar Manor!",
  ui_story_5043_50431401_206_dialog_content = "Tapi bagaimana ini bisa terjadi? Maksudku, itu menjelaskan kenapa kita menemukan Eclipsites di ruang bawah tanah...",
  ui_story_5043_50431401_207_dialog_content = "Y-Ya! Saat itulah aku melarikan diri dengan yang lainnya!",
  ui_story_5043_50431401_208_dialog_content = "Apa?!",
  ui_story_5043_50431401_209_dialog_content = "Berarti... Kamilah yang menyelamatkanmu!",
  ui_story_5043_50431401_210_dialog_content = "D-Dan aku sangat bersyukur! Kalian adalah p-pahlawanku!",
  ui_story_5043_50431401_211_dialog_content = "Jadi Anda ingin menuduh Schwab menyembunyikan Eclipsites di luar kehendak mereka?",
  ui_story_5043_50431401_212_dialog_content = "Y-Ya! Saya tahu bahwa hukum L-Lumopolis tidak akan pernah melindungi E-Eclipsite, tetapi saya tahu dia pasti merencanakan sesuatu yang lebih buruk!",
  ui_story_5043_50431401_213_dialog_content = "Tugas yang cukup sederhana. Datang saja ke gedung pengadilan besok, dan beri tahu semua orang apa yang baru saja Anda ceritakan kepada kami.",
  ui_story_5043_50431401_214_dialog_content = "Segera, semua orang akan tahu persis apa yang dilakukan Schwab dalam bayang-bayang!",
  ui_story_5043_50431401_215_dialog_content = "S-Tentu! Saya bisa melakukan itu!",
  ui_story_5043_50431401_216_dialog_content = "... Apakah Anda punya bukti?",
  ui_story_5043_50431401_217_dialog_content = "Bukti-P?",
  ui_story_5043_50431401_218_dialog_content = "Ingat, Anda adalah Eclipsite.",
  ui_story_5043_50431401_219_dialog_content = "Kami pernah ke ruang bawah tanah Keluarga Salar, jadi kami bisa mempercayai kata-katamu, tapi bagaimana dengan yang lain?",
  ui_story_5043_50431401_220_dialog_content = "Tanpa bukti apa pun, yang harus dilakukan Schwab hanyalah menyangkal kesaksian Anda, dan Anda akan diusir.",
  ui_story_5043_50431401_221_dialog_content = "Tidak hanya itu, dia bahkan mungkin mengejar Anda setelah persidangan selesai.",
  ui_story_5043_50431401_222_dialog_content = "Melanjutkan ini akan menjadi keputusan yang sangat berbahaya.",
  ui_story_5043_50431401_223_dialog_content = "Aku minta maaf, tapi aku tidak punya bukti...",
  ui_story_5043_50431401_224_dialog_content = "I-Butuh semua yang kumiliki untuk melarikan diri dari ruang bawah tanahnya...",
  ui_story_5043_50431401_225_dialog_content = "Hai! Kami tidak bisa menyerah hanya karena kami tidak punya bukti!",
  ui_story_5043_50431401_226_dialog_content = "Mengapa kita tidak mencoba berkunjung lagi ke Salar Manor?",
  ui_story_5043_50431401_227_dialog_content = "Tunggu, saya tidak berpikir kita perlu sejauh itu. Saya punya ide...",
  ui_story_5043_50431401_228_dialog_content = "Lanjutkan?",
  ui_story_5043_50431401_229_dialog_content = "Karena kita tidak punya bukti, yang harus kita lakukan adalah membuatnya mengakui kejahatannya!",
  ui_story_5043_50431401_230_dialog_content = "... Kamu bercanda kan?",
  ui_story_5043_50431401_231_dialog_content = "Bagaimana kita bisa membuatnya mengaku kepada mereka tanpa bukti ?!",
  ui_story_5043_50431401_232_dialog_content = "Katakan padaku, menurutmu mengapa dia menahan Eclipsites sejak awal?",
  ui_story_5043_50431401_233_dialog_content = "Hmm... Nah, baginya untuk melakukan sesuatu yang sangat berbahaya, itu pasti karena alasan yang sangat penting.",
  ui_story_5043_50431401_234_dialog_content = "Saya pikir dia entah bagaimana memerintahkan mereka untuk menghancurkan patung-patung itu.",
  ui_story_5043_50431401_235_dialog_content = "Oh? Apa yang membuatmu mengatakan itu?",
  ui_story_5043_50431401_236_dialog_content = "Ingat ketika saya meraih tangan pelakunya kembali di Stairway to the Skies?",
  ui_story_5043_50431401_237_dialog_content = "Setelah Anda dan yang lainnya memusnahkan sisa Eclipsites, tidak ada orang lain di sekitar.",
  ui_story_5043_50431401_238_dialog_content = "Bagian atas Stairway to the Skies adalah ruang terbuka yang besar. Tidak mungkin ada orang yang bisa menghilang dari pandangan kita secepat itu.",
  ui_story_5043_50431401_239_dialog_content = "Kecuali, tentu saja, pelakunya adalah Eclipsite.",
  ui_story_5043_50431401_240_dialog_content = "Oh, saya mengerti sekarang! Jika pelakunya adalah Eclipsite, kami akan menyingkirkannya bersama yang lain!",
  ui_story_5043_50431401_241_dialog_content = "Itu akan menjelaskan mengapa kami tidak pernah menemukan mereka!",
  ui_story_5043_50431401_242_dialog_content = "Ini adalah alasan yang paling mungkin, ya.",
  ui_story_5043_50431401_243_dialog_content = "Jadi bagaimana Anda berencana menggunakan informasi ini?",
  ui_story_5043_50431401_244_dialog_content = "Pertama, kita akan menjadikan Toto sebagai pelakunya.",
  ui_story_5043_50431401_245_dialog_content = "Selanjutnya, kita akan memintanya memberikan versi kebenaran kita sebagai kesaksiannya.",
  ui_story_5043_50431401_246_dialog_content = "Selama firasat kita cukup dekat dengan kebenaran, Schwab akan percaya bahwa Toto adalah Eclipsite yang dia perintahkan untuk menghancurkan patung-patung itu.",
  ui_story_5043_50431401_247_dialog_content = "Itu sempurna! Jadi tujuanmu adalah membuatnya percaya kita memiliki bukti yang memberatkannya. Dan begitu dia mengaku kalah, dia akan mengakui kejahatannya karena frustrasi!",
  ui_story_5043_50431401_248_dialog_content = "Itu benar. Kita harus mengalahkannya dalam adu kecerdasan.",
  ui_story_5043_50431401_249_dialog_content = "Jadi apa yang kamu katakan, Toto? Apakah Anda bersedia berbohong di bawah sumpah?",
  ui_story_5043_50431401_250_dialog_content = "A-Selama itu memperlihatkan Schwab, aku akan melakukannya!",
  ui_story_5043_50431401_251_dialog_content = "Bagus. Kita akan habiskan sisa hari ini untuk melatih dialogmu.",
  ui_story_5043_50431401_252_dialog_content = "Jika kita ingin memaksimalkan peluang sukses kita, kita harus menghasilkan sesuatu yang meyakinkan.",
  ui_story_5043_50431401_253_dialog_content = "Sesuatu yang akan membuat Schwab meragukan dirinya sendiri untuk percaya bahwa kami mengatakan yang sebenarnya.",
  ui_story_5043_50431401_254_dialog_content = "Anda... Anda penipu yang menyedihkan!",
  ui_story_5043_50431401_255_dialog_content = "Yang kami lakukan hanyalah melawan api dengan api, Hakim Schwab.",
  ui_story_5043_50431401_256_dialog_content = "Untuk berpikir bahwa pelakunya adalah hakim ketua selama ini.",
  ui_story_5043_50431401_257_dialog_content = "Ini tidak bisa dipercaya. Bagaimana mungkin ada di antara kalian yang membungkuk begitu rendah? Anda menyebut diri Anda anggota Hall of Justice?!",
  ui_story_5043_50431401_258_dialog_content = "Meski begitu, pengadilan pada akhirnya mampu mengungkap kebenaran, bukan?",
  ui_story_5043_50431401_259_dialog_content = "Terkadang, satu-satunya cara untuk mengalahkan kegelapan adalah dengan kegelapan itu sendiri!",
  ui_story_5043_50431401_260_dialog_content = "Sudah berakhir, Hakim Schwab. Datang dengan damai, dan bertanggung jawab atas tindakan Anda.",
  ui_story_5043_50431401_261_dialog_content = "Hmph. Sudah berakhir, katamu?",
  ui_story_5043_50431401_262_dialog_content = "Sepertinya Anda juga telah membuat satu kesalahan krusial, Leyn. Apakah Anda ingin menebak apa itu?",
  ui_story_5043_50431401_263_dialog_content = "Apa maksudmu...?",
  ui_story_5043_50431401_264_dialog_content = "Kesalahanmu adalah berasumsi bahwa segala sesuatunya akan berakhir begitu kamu menemukan kebenaran.",
  ui_story_5043_50431401_265_dialog_content = "Sebagai hakim ketua, dengan ini saya menyatakan Hakim itu Leyn, Hakim Tina, dan Hakim Matthieu semuanya terlibat dalam kejahatan yang diajukan ke pengadilan!",
  ui_story_5043_50431401_266_dialog_content = "Ketiga pelaku harus segera ditangkap pada saat sidang ditunda!",
  ui_story_5043_50431401_267_dialog_content = "Kegilaan apa ini, Schwab?!",
  ui_story_5043_50431401_268_dialog_content = "Semua orang di sini baru saja mendengar Anda mengaku! Anda pelaku sebenarnya, bukan kami!",
  ui_story_5043_50431401_269_dialog_content = "Ya ampun, sepertinya kita belum mencapai konsensus tentang kasus ini.",
  ui_story_5043_50431401_270_dialog_content = "Baiklah kalau begitu! Sebagai gantinya, kami akan meminta juri untuk memilihnya!",
  ui_story_5043_50431401_271_dialog_content = "Juri?!",
  ui_story_5043_50431401_272_dialog_content = "Tunggu sebentar, apakah itu...?",
  ui_story_5043_50431401_273_dialog_content = "E-Eclipsites?! Tapi bagaimana caranya?!",
  ui_story_5043_50431401_274_dialog_content = "Silakan sampaikan pernyataan penutup Anda, Hakim Leyn.",
  ui_story_5043_50431401_275_dialog_content = "... Mengingat semua yang telah terjadi, saya menyimpulkan bahwa Schwab Salar adalah pelaku sebenarnya dalam kasus ini.",
  ui_story_5043_50431401_276_dialog_content = "Bagus, bagus... Mereka yang setuju dengan tuduhannya, angkat tangan.",
  ui_story_5043_50431401_277_dialog_content = "Mari kita lihat... Leyn, Matthieu, Tina, Dan Judge Jr.",
  ui_story_5043_50431401_278_dialog_content = "Total empat suara. Sepertinya kata-katamu telah mengguncang cukup banyak hati, Leyn.",
  ui_story_5043_50431401_279_dialog_content = "Itu karena saya mengatakan yang sebenarnya!",
  ui_story_5043_50431401_280_dialog_content = "Di sisi lain, saya menyimpulkan bahwa Hakim Leyn, Tina, Dan Matthieu adalah pelaku sebenarnya dalam kasus ini.",
  ui_story_5043_50431401_281_dialog_content = "Mereka yang setuju dengan kesimpulan saya, silakan mengetuk meja sekali.",
  ui_story_5043_50431401_282_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431401_283_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431401_284_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431401_285_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431401_286_dialog_content = "Tapi mereka...",
  ui_story_5043_50431401_287_dialog_content = "Empat suara.",
  ui_story_5043_50431401_288_dialog_content = "Termasuk suara saya sendiri, jadi lima.",
  ui_story_5043_50431401_289_dialog_content = "Tampaknya kesimpulan saya sedikit lebih menarik daripada kesimpulan Anda.",
  ui_story_5043_50431401_290_dialog_content = "Kamu... Kamu mengganti semua juri dengan anak buahmu sendiri!!",
  ui_story_5043_50431401_291_dialog_content = "Anak buahmu? Mereka semua pasti Eclipsites di bawah topeng itu!",
  ui_story_5043_50431401_292_dialog_content = "Suara telah diberikan, dan keputusan yang jelas telah dibuat!",
  ui_story_5043_50431401_293_dialog_content = "Pengadilan menemukan Leyn, Matthieu, Dan Tina—",
  ui_story_5043_50431401_294_dialog_content = "Bersalah!",
  ui_story_5043_50431401_295_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5043_50431401_296_dialog_content = "Ada yang salah dengan para juri itu!",
  ui_story_5043_50431401_X296_dialog_content = "Darkflow yang intens! Mereka benar-benar Eclipsites!",
  ui_story_5043_50431401_X297_dialog_content = "A-Apa yang kau katakan!?",
  ui_story_5043_50431401_X298_dialog_content = "Kamu pasti bercanda—semua orang yang duduk di sini bersamaku ini adalah Eclipsites!?",
  ui_story_5043_50431401_297_dialog_content = "Anggota dewan juri yang saya hormati, saya ucapkan terima kasih atas bantuannya.",
  ui_story_5043_50431401_298_dialog_content = "Anda melayani tidak hanya sebagai saksi hari ini tetapi sebagai ksatria saya dalam pelaksanaan keadilan.",
  ui_story_5043_50431401_299_dialog_content = "Dengan kekuatan yang diberikan di Hall of Justice—",
  ui_story_5043_50431401_300_dialog_content = "Tangkap para penjahat itu!",
  ui_story_5043_50431401_301_dialog_content = "Graah...",
  ui_story_5043_50431401_302_dialog_content = "Sial, kupikir itu adalah Eclipsites yang bersembunyi di bawah topeng itu!",
  ui_story_5043_50431401_303_dialog_content = "Memang. Jika ini kartu truf Schwab, mereka tidak akan mudah dihadapi.",
  ui_story_5043_50431401_304_dialog_content = "Menggunakan kekerasan, semua karena Anda kalah di pengadilan? Betapa piciknya!",
  ui_story_5043_50431401_305_dialog_content = "Ini tidak bagus, Hall of Justice lebih cocok dengan gaya bertarung mereka. Kami akan dikepung dalam waktu singkat!",
  ui_story_5043_50431401_306_dialog_content = "Kami benar... Kami benar, Schwab! Bagaimana Anda bisa membiarkan kejahatan menang di rumah keadilan ?!",
  ui_story_5043_50431401_307_dialog_content = "Biarkan saja, Leyn! Keadilan selalu berpihak pada pemenang, dan kami berjuang keras di sini!",
  ui_story_5043_50431401_308_dialog_content = "Kita harus melarikan diri selagi kita bisa!",
  ui_story_5043_50431401_309_dialog_content = "Dia benar, sekarang bergerak!",
  ui_story_5043_50431401_310_dialog_content = "Lewat sini, cepat!",
  ui_story_5043_50431402_1_dialog_content = "Jauh di atas kepala kita, cinta kita mengapung seperti awan! ♪",
  ui_story_5043_50431402_2_dialog_content = "Tersembunyi di balik tabir, cinta kita begitu bangga! ♪",
  ui_story_5043_50431402_3_dialog_content = "Dari jauh, kami bertanya-tanya keindahan apa yang ada di dalamnya ♪",
  ui_story_5043_50431402_4_dialog_content = "Melihat cinta kita mekar adalah keinginan yang tidak bisa kita sembunyikan! ♪",
  ui_story_5043_50431402_5_dialog_content = "Kudengar mereka akan meletuskan balon bulan hari ini. Apakah menurut Anda itu benar?",
  ui_story_5043_50431402_6_dialog_content = "Tentu mereka! Itulah alasan utama kita berkumpul di sini hari ini!",
  ui_story_5043_50431402_7_dialog_content = "Mereka bilang balon itu diisi dengan segala macam benda, seperti bunga, kerajinan kertas, dan bahkan gelembung warna-warni!",
  ui_story_5043_50431402_8_dialog_content = "Kedengarannya lebih baik daripada kembang api! Penghargaan sempurna untuk kekuatan cinta!",
  ui_story_5043_50431402_9_dialog_content = "Hah? Sepertinya kerumunan orang berlari keluar dari Hall of Justice.",
  ui_story_5043_50431402_10_dialog_content = "Ingin tahu apa yang mereka lakukan?",
  ui_story_5043_50431402_11_dialog_content = "Fiuh, akhirnya kami berhasil kabur.",
  ui_story_5043_50431402_12_dialog_content = "Kita belum bisa bersantai dulu! Mereka akan menyusul sebentar lagi!",
  ui_story_5043_50431402_13_dialog_content = "...",
  ui_story_5043_50431402_14_dialog_content = "Monster yang gigih, bukan?",
  ui_story_5043_50431402_15_dialog_content = "Apa mereka berniat mengejar kita sampai ke Umbraton?!",
  ui_story_5043_50431402_16_dialog_content = "Tunggu, sepertinya pawai sedang menuju ke sini!",
  ui_story_5043_50431402_17_dialog_content = "Sekarang, sepanjang masa...",
  ui_story_5043_50431402_18_dialog_content = "Kita tidak bisa lari begitu saja sekarang! Eclipsites akan menyerang orang-orang itu jika kita melakukannya!",
  ui_story_5043_50431402_19_dialog_content = "Itu benar. Kita harus mengalahkan mereka, di sini dan sekarang.",
  ui_story_5043_50431402_20_dialog_content = "PlayerName, dapatkah Anda memperingatkan pawai dan meminta mereka mengevakuasi area tersebut?",
  ui_story_5043_50431402_21_dialog_content = "Tentu, serahkan padaku!",
  ui_story_5043_50431402_22_dialog_content = "Mereka datang untuk melihat pertunjukan, yang belum pernah mereka saksikan sebelumnya.",
  ui_story_5043_50431402_23_dialog_content = "Apakah Anda benar-benar tega merampok mereka dari pengalaman yang sangat dinanti?",
  ui_story_5043_50431402_24_dialog_content = "Kamu... Beraninya kamu membuat lelucon di saat seperti ini!",
  ui_story_5043_50431402_25_dialog_content = "Saya benar-benar serius, Matthieu. Yang saya inginkan hanyalah memberi orang-orang pertunjukan yang sangat ingin mereka lihat.",
  ui_story_5043_50431402_26_dialog_content = "Akhir yang megah untuk lelucon perayaan ini!",
  ui_story_5043_50431402_27_dialog_content = "<size=45>Lewat sini, semuanya! Cepat, sekarang!</size>",
  ui_story_5043_50431402_28_dialog_content = "<size=45>Pertunjukan baru saja akan dimulai!</size>",
  ui_story_5043_50431402_29_dialog_content = "Schwab, apa artinya ini?!",
  ui_story_5043_50431402_30_dialog_content = "Dia mencoba merusak perayaan! Orang-orang itu dalam bahaya!",
  ui_story_5043_50431402_31_dialog_content = "Mereka bergegas! Jangan biarkan mereka mendekati Eclipsites!",
  ui_story_5043_50431402_32_dialog_content = "Jangan khawatir, aku akan melindungi mereka!",
  ui_story_5043_50431402_33_dialog_content = "Kenapa sangat serius? Lagipula itu tidak lebih dari sebuah pertunjukan.",
  ui_story_5043_50431402_34_dialog_content = "Sekarang saya ingat, bukankah balon bulan seharusnya meledak hari ini?",
  ui_story_5043_50431402_35_dialog_content = "Aku ingin tahu apa yang akan kita temukan bersembunyi di dalam monumen terapung yang konyol itu untuk dicintai ketika itu terjadi.",
  ui_story_5043_50431402_36_dialog_content = "Jangan bilang kamu...",
  ui_story_5043_50431402_37_dialog_content = "Lihatlah buah dari keyakinan menggelikan Anda!",
  ui_story_5043_50431402_38_dialog_content = "<color=#e8d9bb>Pop—!!!</color>",
  ui_story_5043_50431402_39_dialog_content = "Woooooow!!!",
  ui_story_5043_50431402_40_dialog_content = "Hati-hati, semuanya!",
  ui_story_5043_50431402_41_dialog_content = "Hei, apa ini melayang di atas kita...?",
  ui_story_5043_50431402_42_dialog_content = "Hadiah dari festival kuno — karangan bunga semanggi saya — apa ini?",
  ui_story_5043_50431402_43_dialog_content = "Apakah ini bunga mati?",
  ui_story_5043_50431402_44_dialog_content = "Ya, mawar mati, tepatnya...",
  ui_story_5043_50431402_45_dialog_content = "Langit penuh dengan bunga mati...",
  ui_story_5043_50431402_46_dialog_content = "Sungguh pemandangan yang jelek, aku merasa tidak enak hanya dengan melihatnya.",
  ui_story_5043_50431402_47_dialog_content = "Apakah ini benar-benar bagaimana ledakan Balon Bulan seharusnya terjadi?",
  ui_story_5043_50431402_48_dialog_content = "Memang itu!",
  ui_story_5043_50431402_49_dialog_content = "Bukan langkah lain, Schwab!",
  ui_story_5043_50431402_50_dialog_content = "Ada apa, Hakim Tina? Bukankah ini gambaran cinta?",
  ui_story_5043_50431402_51_dialog_content = "Keindahan yang hanya bisa kita bayangkan ketika kita memalingkan pandangan kita dari apa yang ada di dalamnya.",
  ui_story_5043_50431402_52_dialog_content = "Seperti bulan di langit malam, ia memikat kita dengan keindahannya yang misterius dan jauh.",
  ui_story_5043_50431402_53_dialog_content = "Daya pikatnya menarik kekuatan dari yang tidak diketahui, dari ketidaktahuan orang tentang sifat aslinya.",
  ui_story_5043_50431402_54_dialog_content = "Dan sekarang, semua orang telah menyaksikannya sendiri.",
  ui_story_5043_50431402_55_dialog_content = "Inilah arti sebenarnya dari apa yang disebut cinta Anda.",
  ui_story_5043_50431402_56_dialog_content = "Yang tersisa setelah kegembiraan dan absurditas mereda adalah dunia yang berantakan.",
  ui_story_5043_50431402_57_dialog_content = "Dan mulai hari ini dan seterusnya, tak seorang pun akan melihat keindahan bulan lagi.",
  ui_story_5043_50431402_58_dialog_content = "Yah, dia benar tentang satu hal, aku tidak ingin melihat balon bodoh itu lagi.",
  ui_story_5043_50431402_59_dialog_content = "Tidak main-main, ide siapa yang mengisinya dengan bunga mati? Itu pada dasarnya hanya sekantong sampah yang mengambang ...",
  ui_story_5043_50431402_60_dialog_content = "Cukup retorika keliru Anda! Kaulah yang mengubah isi balon, bukan?!",
  ui_story_5043_50431402_61_dialog_content = "Saya tidak pernah menyentuh isi balon itu. Yang saya lakukan hanyalah menghapus Luminatics yang mengelilinginya.",
  ui_story_5043_50431402_62_dialog_content = "Kau…!",
  ui_story_5043_50431402_63_dialog_content = "Jangan menatapku seperti itu. Kaulah yang ingin membohongi massa dengan mengawetkan bunga-bunga itu bersama Lumina.",
  ui_story_5043_50431402_64_dialog_content = "Yang saya lakukan hanyalah mengungkap kebenaran.",
  ui_story_5043_50431402_65_dialog_content = "Kecantikan hanya dihargai ketika seseorang memikul tanggung jawab atas keburukan.",
  ui_story_5043_50431402_66_dialog_content = "Sama seperti para gadis bermata bintang yang mengejarku dengan janji cinta mereka, mereka tidak tahu betapa aku menderita karena fantasi mereka.",
  ui_story_5043_50431402_67_dialog_content = "Benarkah ini cinta...?",
  ui_story_5043_50431402_68_dialog_content = "Sesuatu yang begitu luar biasa sehingga menimbulkan beban bagi orang lain...",
  ui_story_5043_50431402_69_dialog_content = "Sepertinya Anda akhirnya mulai memahami pesan saya.",
  ui_story_5043_50431402_70_dialog_content = "...",
  ui_story_5043_50431402_71_dialog_content = "(Mungkinkah... aku melakukan kesalahan yang sama?)",
  ui_story_5043_50431402_72_dialog_content = "Bukan itu sama sekali, Tina! Jangan biarkan kesalahpahaman Schwab membodohi Anda!",
  ui_story_5043_50431402_73_dialog_content = "Hah?",
  ui_story_5043_50431402_74_dialog_content = "Bagaimana mungkin \"kebenarannya\" lebih diutamakan daripada pengalaman orang lain?",
  ui_story_5043_50431402_75_dialog_content = "Sama seperti emosi lainnya, kita semua merasakan cinta dengan cara kita sendiri.",
  ui_story_5043_50431402_76_dialog_content = "Aku mungkin tidak tahu \"kebenaran\" di balik konsep cinta... Tapi melihat betapa bahagianya semua orang selama acara seperti ini sudah cukup bagiku!",
  ui_story_5043_50431402_77_dialog_content = "Dan selain itu, saya rasa Schwab tidak pernah benar-benar merasakan cinta untuk dirinya sendiri!",
  ui_story_5043_50431402_78_dialog_content = "Hak apa yang dia miliki untuk memberi tahu orang lain bagaimana perasaannya tentang itu ?!",
  ui_story_5043_50431402_79_dialog_content = "Kamu...",
  ui_story_5043_50431402_80_dialog_content = "Tentu saja aku belum pernah merasakan cinta sebelumnya! Bagaimana mungkin aku membiarkan diriku merasakan emosi yang begitu menjijikkan?!",
  ui_story_5043_50431402_81_dialog_content = "Ya kamu benar, PlayerName!",
  ui_story_5043_50431402_82_dialog_content = "Tidak ada kebenaran untuk apa yang dia katakan sama sekali. Dia hanya terpaku pada hasil terburuk yang mungkin terjadi!",
  ui_story_5043_50431402_83_dialog_content = "Terlebih lagi, tidak ada salahnya juga membayangkan indahnya cinta!",
  ui_story_5043_50431402_84_dialog_content = "Cinta bukanlah sesuatu yang bisa diputuskan di pengadilan. Jadi siapakah kita untuk menghakiminya?",
  ui_story_5043_50431402_85_dialog_content = "Apakah itu pengakuan cinta atau mencintai seseorang dari jauh, berkumpul, atau berpisah, semua pengalaman ini adalah ekspresi cinta yang sah!",
  ui_story_5043_50431402_86_dialog_content = "Schwab, kamu tidak tahu apa arti cinta sebenarnya!",
  ui_story_5043_50431402_87_dialog_content = "Hmph, Anda mungkin benar mengatakan bahwa saya tidak mengerti arti cinta.",
  ui_story_5043_50431402_88_dialog_content = "Saya juga tidak mengerti mengapa Anda akan berusaha keras untuk mengejarnya.",
  ui_story_5043_50431402_89_dialog_content = "Bagiku, cinta tak lebih dari penghalang, emosi parasit yang menghancurkan kedamaianku dan mengajak orang lain ikut campur dalam hidupku.",
  ui_story_5043_50431402_90_dialog_content = "Tidak, pengaruh busuknya jauh melampaui hidup saya! Itu mengancam karir dan kemampuan saya untuk menjalankan tugas saya, itu mengancam keseimbangan semua Lumopolis!",
  ui_story_5043_50431402_91_dialog_content = "Kok kau bisa bilang begitu?",
  ui_story_5043_50431402_92_dialog_content = "Lihat saja orang-orang di sekitar kita. Bahkan sedikit saja emosi dapat membuat mereka mengabaikan semua alasan.",
  ui_story_5043_50431402_93_dialog_content = "Emosi yang sama itu mengarah pada pembentukan ejekan yang dikenal sebagai Divisi Percintaan!",
  ui_story_5043_50431402_94_dialog_content = "Apa yang benar-benar telah dilakukan cinta untuk kita, hmm? Selain memberi penjahat kesempatan untuk lolos dari hukuman, itu membuat kita menuntut orang yang tidak bersalah dengan kejahatan yang tidak pernah mereka lakukan.",
  ui_story_5043_50431402_95_dialog_content = "Itu menodai hukum berusia berabad-abad yang telah menyatukan Lumopolis sepanjang sejarahnya yang gemilang!",
  ui_story_5043_50431402_96_dialog_content = "Untuk alasan ini, saya memilih untuk menggunakan kekuatan hukum sepenuhnya melawan gelombang \"cinta\" terkutuk yang mengganggu kota kita yang adil ini...",
  ui_story_5043_50431402_97_dialog_content = "Semua yang saya lakukan, saya lakukan dengan tujuan tunggal menghilangkan cinta sebagai faktor dalam pelaksanaan keadilan!",
  ui_story_5043_50431402_98_dialog_content = "Saya membutuhkan juri yang pandangannya sejalan dengan pandangan saya, yang penilaiannya tidak akan diracuni oleh emosi yang tidak perlu.",
  ui_story_5043_50431402_99_dialog_content = "Syukurlah, monster mengerikan ini lebih dari mampu mengisi peran tersebut.",
  ui_story_5043_50431402_100_dialog_content = "...",
  ui_story_5043_50431402_101_dialog_content = "Jadi itu yang dia pikirkan selama ini...",
  ui_story_5043_50431402_102_dialog_content = "Untuk membenarkan paranoia sendiri sedemikian rupa.",
  ui_story_5043_50431402_103_dialog_content = "Orang seperti ini jauh lebih menakutkan daripada penjahat yang mencari keburukan.",
  ui_story_5043_50431402_104_dialog_content = "Tapi mari kita akhiri percakapan tidak berguna tentang cinta ini.",
  ui_story_5043_50431402_105_dialog_content = "Alih-alih, mari kita arahkan perhatian kita ke kasus yang ada.",
  ui_story_5043_50431402_106_dialog_content = "Bagaimanapun, Anda semua <color=#FFB400>bersalah</color> di mata pengadilan!",
  ui_story_5043_50431402_107_dialog_content = "Hei, lihat ke sana!",
  ui_story_5043_50431402_108_dialog_content = "Eclipsites mengalir keluar dari dalam Hall of Justice!",
  ui_story_5043_50431402_109_dialog_content = "Hari ini tidak bisa lebih gila lagi! Melarikan diri!!!",
  ui_story_5043_50431402_110_dialog_content = "Sepertinya Schwab mengambil ofensif lagi.",
  ui_story_5043_50431402_111_dialog_content = "Dia gila jika mengira bisa memanggil Eclipsites di depan umum. Para penjaga akan segera membelenggunya.",
  ui_story_5043_50431402_112_dialog_content = "Untuk saat ini, kami masih perlu mengendalikan situasi dan memastikan tidak ada warga sipil yang dirugikan oleh tindakannya.",
  ui_story_5043_50431402_113_dialog_content = "Anda mengatakan itu, tetapi Eclipsites bertopeng itu tidak akan mudah untuk dihadapi ...",
  ui_story_5043_50431402_114_dialog_content = "Biar aku yang menghadapi mereka.",
  ui_story_5043_50431402_115_dialog_content = "Demi kehormatanku, dan kehormatan Keluarga Campbell—",
  ui_story_5043_50431402_116_dialog_content = "Lihatlah kekuatan Tangan Ilahi!",
  ui_story_5043_50431402_117_dialog_content = "Wah! Ada apa dengan Lumina ini?!",
  ui_story_5043_50431402_118_dialog_content = "Serangan seperti ini mungkin cukup untuk—",
  ui_story_5043_50431402_119_dialog_content = "Yaaawn—",
  ui_story_5043_50431402_120_dialog_content = "Hah? H-Hei! Kenapa kau menguap di saat seperti ini?!",
  ui_story_5043_50431402_121_dialog_content = "Maaf... tapi aku sudah... melewati batasku... untuk hari ini...",
  ui_story_5043_50431402_122_dialog_content = "Hmph. Bawa mereka, Empat Ksatria.",
  ui_story_5043_50431402_123_dialog_content = "T-Tunggu, waktu habis! Ini tidak adil!!",
  ui_story_5043_50431402_124_dialog_content = "Keluar darinya, Tina! Hai! Hai!!!",
  ui_story_5043_50431402_125_dialog_content = "Nnng... lihatlah kekuatan... dari Tangan Ilahi...!",
  ui_story_5043_50431402_126_dialog_content = "<color=#e8d9bb>Kemerosotan-</color>",
  ui_story_5043_50431402_127_dialog_content = "D-Dia tertidur bahkan sebelum pertarungan dimulai!!!",
  ui_story_5043_50431402_128_dialog_content = "Apa yang harus kita lakukan?! Ini bukan tempat untuk tidur siang!!!",
  ui_story_5043_50431402_129_dialog_content = "Bangun, Tina! Musuh akan menyerang!",
  ui_story_5043_50431402_130_dialog_content = "Bintang... Aku melihat bintang... di kepalamu... Leyn...",
  ui_story_5043_50431402_131_dialog_content = "Ini bukan waktunya untuk melihat bintang! Bersiaplah untuk pertempuran!",
  ui_story_5043_50431402_132_dialog_content = "Maaf... tapi aku tidak bisa...",
  ui_story_5043_50431402_133_dialog_content = "Ini, makan saja ini.",
  ui_story_5043_50431402_134_dialog_content = "Itu coklat?! Ini juga bukan waktunya untuk ngemil, Leyn!!!",
  ui_story_5043_50431402_135_dialog_content = "aku... aku...",
  ui_story_5043_50431402_136_dialog_content = "Apa yang kita lakukan? Mereka ada di depan kita sekarang...",
  ui_story_5043_50431402_137_dialog_content = "Aku benar-benar terjaga sekarang!!!",
  ui_story_5043_50431402_138_dialog_content = "Hah?!",
  ui_story_5043_50431402_139_dialog_content = "Bicara tentang tidur siang!!!",
  ui_story_5043_50431402_140_dialog_content = "Heh! Dalam hal memenangkan hati seseorang, Anda harus mengandalkan lebih dari satu strategi!",
  ui_story_5043_50431402_141_dialog_content = "Mari saya tunjukkan bagaimana hal itu dilakukan!",
  ui_story_5043_50431402_142_dialog_content = "Uh? Apa itu?",
  ui_story_5043_50431402_143_dialog_content = "Apakah kamu sudah lupa? Kamu dan yang lainnya adalah orang-orang yang menunjukkanku sejak awal!",
  ui_story_5043_50431402_144_dialog_content = "Ada banyak cara untuk mengejar minat romantis, termasuk ... <color=#FFB400>sebuah pengakuan</color>!",
  ui_story_5043_50431402_145_dialog_content = "Anda benar selama ini, Leyn! Mendapatkan perhatian penuh orang lain adalah langkah pertama dan salah satu yang paling penting!",
  ui_story_5043_50431402_X145_dialog_content = "Tarik monster menjauh dari kerumunan!",
  ui_story_5043_50431402_146_dialog_content = "Maaf, apa...?",
  ui_story_5043_50431402_147_dialog_content = "Baiklah, monster bertopeng, ambil ini!",
  ui_story_5043_50431402_148_dialog_content = "Graah...",
  ui_story_5043_50431402_149_dialog_content = "Saya percaya Tangan Ilahi berhasil mendapatkan perhatian penuh Anda, ya?",
  ui_story_5043_50431402_X149_dialog_content = "Astaga!!!",
  ui_story_5043_50431402_X150_dialog_content = "Anda bahkan tidak akan meninggalkan goresan pada ksatria saya dengan tingkat kekuatan ini! Jangan berhenti menyerang!",
  ui_story_5043_50431402_150_dialog_content = "Hakim Matthieu adalah orang yang menunjukkan apa yang harus saya lakukan selanjutnya. Masih ingat, kan?",
  ui_story_5043_50431402_151_dialog_content = "Orang tidak bisa hanya mengandalkan mengambil inisiatif. Mereka juga perlu belajar... <color=#FFB400>seni penyembunyian</color>!",
  ui_story_5043_50431402_152_dialog_content = "Dan memang begitu! Aku akan melindungimu, Tina!",
  ui_story_5043_50431402_153_dialog_content = "Cepat, ayo berlindung di balik tembok itu!",
  ui_story_5043_50431402_154_dialog_content = "Hmph. Siap untuk menyerah setelah kemunduran kecil seperti itu? Cintamu benar-benar rapuh.",
  ui_story_5043_50431402_155_dialog_content = "Bukankah kamu baru saja mengatakan bahwa kamu ingin melindungi orang?",
  ui_story_5043_50431402_156_dialog_content = "Graaaaah...",
  ui_story_5043_50431402_157_dialog_content = "Grah?",
  ui_story_5043_50431402_158_dialog_content = "Aku tahu itu! Mereka tidak dapat menemukan kita!",
  ui_story_5043_50431402_159_dialog_content = "Saya pikir topeng yang mereka kenakan mungkin adalah titik lemah mereka!",
  ui_story_5043_50431402_160_dialog_content = "Kamu mungkin benar. Mari kita lihat apa yang ada di balik penyamaran mereka!",
  ui_story_5043_50431402_161_dialog_content = "Di sinilah metode ketiga berperan!",
  ui_story_5043_50431402_162_dialog_content = "Untuk menemukan keseimbangan yang tepat antara menekan maju dan mundur... <color=#FFB400>pengintaian</color>!",
  ui_story_5043_50431402_163_dialog_content = "Kita perlu memahami orang lain sebanyak mungkin sebelum mengambil langkah terakhir itu.",
  ui_story_5043_50431402_X163_dialog_content = "Kita hanya perlu menemukan kelemahan mereka dan memberikan pukulan yang menentukan untuk mengakhiri semua ini!",
  ui_story_5043_50431402_164_dialog_content = "Jadi mari kita mulai dengan menyerang topeng mereka!",
  ui_story_5043_50431402_165_dialog_content = "Sekarang kesempatan kita! Menyerang!",
  ui_story_5043_50431402_166_dialog_content = "Graaaah!!!",
  ui_story_5043_50431402_167_dialog_content = "<color=#e8d9bb>Apa, apa, apa!!!</color>",
  ui_story_5043_50431402_168_dialog_content = "Argh, terbuat dari apa benda-benda itu?!",
  ui_story_5043_50431402_169_dialog_content = "Sepertinya memecahkan topeng-topeng itu tidak akan semudah yang kita kira.",
  ui_story_5043_50431402_170_dialog_content = "Ha ha ha! Oh, andai saja kamu bisa melihat ekspresi bodoh di wajahmu!",
  ui_story_5043_50431402_171_dialog_content = "Apakah Anda benar-benar percaya Anda bisa menyakiti ksatria saya dengan serangan yang begitu menyedihkan?",
  ui_story_5043_50431402_172_dialog_content = "Hmph, meski semuanya tampak tanpa harapan, masih ada peluang untuk cinta menang!",
  ui_story_5043_50431402_173_dialog_content = "Pada titik ini, trik dan strategi keluar dari pertanyaan. Semua yang tersisa untuk dilakukan—",
  ui_story_5043_50431402_174_dialog_content = "Sekarang, Tina!",
  ui_story_5043_50431402_175_dialog_content = "Tunjukkan pada dunia apa yang ada di hatimu!!!",
  ui_story_5043_50431402_176_dialog_content = "Itu benar! Saya akan mengambil setiap ons ketulusan saya!",
  ui_story_5043_50431402_177_dialog_content = "Dan gunakan itu untuk mendaratkan serangan terakhir!",
  ui_story_5043_50431402_178_dialog_content = "<size=45><color=#FFB400>Kemegahan Ilahi</color>!</size>",
  ui_story_5043_50431402_179_dialog_content = "Fiuh, apakah dia berhasil?",
  ui_story_5043_50431402_180_dialog_content = "Dia melakukanya! Dia meniup topeng langsung dari Eclipsites itu!",
  ui_story_5043_50431402_181_dialog_content = "B-Bagaimana ini bisa terjadi?! ksatria saya...",
  ui_story_5043_50431402_182_dialog_content = "Dorong maju, ksatria saya!",
  ui_story_5043_50431402_183_dialog_content = "Anda tidak dapat mengecewakan saya sekarang! Tidak ketika keadilan belum ditegakkan!",
  ui_story_5043_50431402_184_dialog_content = "Sudah berakhir, Schwab.",
  ui_story_5043_50431402_185_dialog_content = "Sama seperti Anda, mereka tidak merasakan hal-hal seperti cinta atau kesetiaan, yang bisa mereka lakukan hanyalah mengikuti perintah tanpa berpikir.",
  ui_story_5043_50431402_186_dialog_content = "Seperti Anda sekarang, Anda tidak pernah bisa berharap untuk mengatasi kekuatan mentah dari emosi kita.",
  ui_story_5043_50431402_187_dialog_content = "Bahkan sekarang, kamu bersikeras untuk mengungkapkan perasaanmu?!",
  ui_story_5043_50431402_188_dialog_content = "Dia benar, kau tahu? Adapun keadilan tidak dilayani... Anda tidak perlu khawatir tentang itu lagi.",
  ui_story_5043_50431402_189_dialog_content = "Dengan bagaimana keadaannya, Hall of Justice pasti akan menangani kasus ini dengan lebih serius.",
  ui_story_5043_50431402_190_dialog_content = "Bahkan, saya tidak akan terkejut jika Ketua Hakim Irridon memimpin semuanya.",
  ui_story_5043_50431402_191_dialog_content = "Aku yakin dia akan memberimu keadilan yang sangat kau inginkan, Schwab.",
  ui_story_5043_50431402_192_dialog_content = "Melayani saya? Tidak tidak! Ini tidak mungkin!",
  ui_story_5043_50431402_193_dialog_content = "Saya tidak bersalah, saya katakan! Tidak ada yang bisa menghakimi saya!!!",
  ui_story_5043_50431402_194_dialog_content = "Itu bukan untuk Anda putuskan.",
  ui_story_5043_50431402_195_dialog_content = "Tentu saja, bodoh! Saya hakim ketua!!!",
  ui_story_5043_50431402_196_dialog_content = "Status itu juga bukan untuk Anda putuskan lagi.",
  ui_story_5043_50431402_197_dialog_content = "Busuk! Kota ini dan hukumnya sudah busuk sekarang!",
  ui_story_5043_50431402_198_dialog_content = "Minggir! Ayahku akan mendengar tentang ini!",
  ui_story_5043_50431402_199_dialog_content = "Tandai kata-kata saya, Keluarga Salar tidak akan berhenti sampai keadilan sejati ditegakkan!",
  ui_story_5043_50431402_200_dialog_content = "Betapa memalukannya dirimu, Schwab. Berlari pulang ke ayah ketika segala sesuatunya tidak berjalan sesuai keinginanmu?",
  ui_story_5043_50431402_201_dialog_content = "Sungguh memalukan.",
  ui_story_5043_50431402_202_dialog_content = "Aku bilang keluar dari jalanku!!!",
  ui_story_5043_50431402_203_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5043_50431402_204_dialog_content = "Argh...!",
  ui_story_5043_50431402_205_dialog_content = "Ke-Siapa itu? Siapa yang memukulku barusan?!",
  ui_story_5043_50431402_206_dialog_content = "Itu saya, dan kecuali Anda ikut dengan kami dengan damai ke Balai Kehakiman... Akan ada lebih banyak lagi dari mana asalnya.",
  ui_story_5043_50431402_207_dialog_content = "Leyn! Kamu bodoh!",
  ui_story_5043_50431402_208_dialog_content = "Apakah Anda tahu apa yang baru saja Anda lakukan, Anda orang biasa yang malang ?!",
  ui_story_5043_50431402_209_dialog_content = "Itu untuk kebaikanmu sendiri.",
  ui_story_5043_50431402_210_dialog_content = "Anda mungkin tidak berhasil sampai ke uji coba jika Tina telah memukul Anda sebagai gantinya.",
  ui_story_5043_50431402_211_dialog_content = "Itu benar, kok!",
  ui_story_5043_50431402_212_dialog_content = "K-Kalian semua...",
  ui_story_5043_50431402_213_dialog_content = "Itu akan berhasil, semuanya. Karyawan Divisi Percintaan masih bekerja!",
  ui_story_5043_50431402_214_dialog_content = "Datang datang! Saatnya kembali ke tugas kita!",
  ui_story_5043_50431402_215_dialog_content = "Saya kira kita masih memiliki banyak pekerjaan untuk hari ini, ya?",
  ui_story_5043_50431402_216_dialog_content = "Yaaaawn... wah alhamdulillah ada sofa...",
  ui_story_5043_50431402_217_dialog_content = "Hai! Jauhkan tangan kotormu dariku!",
  ui_story_5043_50431402_218_dialog_content = "Saya tidak akan didorong seperti penjahat biasa!",
  ui_story_5043_50431402_219_dialog_content = "Wah! Mereka akhirnya menahan Schwab!",
  ui_story_5043_50431402_220_dialog_content = "Sepertinya semuanya berhasil pada akhirnya, ya?",
  ui_story_5043_50431402_221_dialog_content = "Memang. Schwab memiliki banyak jawaban. Hukumannya tidak akan ringan.",
  ui_story_5043_50431402_222_dialog_content = "Meskipun tindakannya tidak menimbulkan kerusakan yang nyata, tindakan tersebut masih merupakan pelanggaran langsung terhadap hukum Lumopolis.",
  ui_story_5043_50431402_223_dialog_content = "Haruskah dia memilih untuk memanipulasi Eclipsites seperti ini lagi... Aku tidak berani membayangkan konsekuensinya.",
  ui_story_5043_50431402_224_dialog_content = "Saya tidak berpikir dia akan melakukannya. Bagaimanapun, musuh sebenarnya adalah cinta selama ini! Ha ha ha ha!",
  ui_story_5043_50431402_225_dialog_content = "Itu benar. Kebenciannya pada konsep cinta membuatnya sedemikian ekstrem, bukan pada siapa pun atau apa pun, khususnya.",
  ui_story_5043_50431402_226_dialog_content = "Paling tidak, dia bisa menyampaikan pesannya yang salah arah, berkat percobaan palsu dan aksi dengan Balon Bulan ini.",
  ui_story_5043_50431402_227_dialog_content = "Ya, menurut saya kasus ini sudah ditutup!",
  ui_story_5043_50431402_228_dialog_content = "Saya tidak akan pernah menduga bahwa insiden sekecil itu akan berakhir dengan cara yang gila ...",
  ui_story_5043_50431402_229_dialog_content = "Aku juga tidak, tapi akhirnya berakhir.",
  ui_story_5043_50431402_230_dialog_content = "Yang tersisa hanyalah mendengar satu putusan akhir.",
  ui_story_5043_50431402_231_dialog_content = "Ya! Ayo cari tempat duduk yang bagus!",
  ui_story_5043_50431402_232_dialog_content = "Saya tidak sabar untuk mendengar apa yang hakim katakan tentang ini.",
  ui_story_5043_50431402_233_dialog_content = "Hah? Apakah ada sesuatu, Suster?",
  ui_story_5043_50431402_234_dialog_content = "Sudah selesai...",
  ui_story_5043_50431402_235_dialog_content = "Ke-Kenapa kau menangis?",
  ui_story_5043_50431402_236_dialog_content = "Orang-orangnya sudah pergi, begitu pula balonnya.",
  ui_story_5043_50431402_237_dialog_content = "Bunga dan cengkehku, semuanya sudah berakhir...",
  ui_story_5043_50431402_238_dialog_content = "Maaf, Suster... Tapi itu bukan salahmu, itu salah Schwab!",
  ui_story_5043_50431402_239_dialog_content = "Meski begitu, semuanya sudah berakhir sekarang.",
  ui_story_5043_50431402_240_dialog_content = "Gelombang cinta Lumopolis akhirnya surut...",
  ui_story_5043_50431501_1_dialog_content = "Setelah penyelidikan menyeluruh, kebenaran di balik kejahatan itu persis seperti itu Leyn telah menduga.",
  ui_story_5043_50431501_2_dialog_content = "Schwab dinyatakan sebagai pelaku di balik pemenggalan patung berantai dan juga dinyatakan bersalah memanipulasi Eclipsites untuk melakukan perintahnya.",
  ui_story_5043_50431501_3_dialog_content = "Syukurlah, tidak ada Aurorian yang dirugikan karena tindakannya yang bengkok, dan satu-satunya kerusakan yang terjadi adalah pada ketiga patung itu.",
  ui_story_5043_50431501_4_dialog_content = "Saya kira dia masih memiliki rasa keadilan di hatinya, haha ...",
  ui_story_5043_50431501_5_dialog_content = "Saya harus menyerahkannya kepada ketiga hakim itu. Mereka berhasil menyimpulkan kebenaran di balik kejahatan dengan hampir tidak ada bukti untuk membantu mereka!",
  ui_story_5043_50431501_6_dialog_content = "Memang. Setelah kasus ini, saya yakin Balai Kehakiman akan melihat bakat mereka dengan lebih tertarik.",
  ui_story_5043_50431501_7_dialog_content = "Masih ada satu hal yang saya tidak mengerti sekalipun.",
  ui_story_5043_50431501_8_dialog_content = "Bagaimana tepatnya Schwab berhasil mengendalikan Eclipsites itu?",
  ui_story_5043_50431501_9_dialog_content = "Saya tidak melihat dia menggunakan peralatan khusus apa pun selama pertempuran kami ...",
  ui_story_5043_50431501_10_dialog_content = "Oh, investigasinya juga punya teori tentang itu.",
  ui_story_5043_50431501_11_dialog_content = "Setelah memperoleh surat perintah yang diperlukan, Hall of Justice menggeledah Salar Manor dan menemukan ruang bawah tanah tempat Schwab menyembunyikan Eclipsites miliknya.",
  ui_story_5043_50431501_12_dialog_content = "Namun, di luar ruang bawah tanahnya, para penyelidik tidak menemukan apa pun yang dapat digunakan untuk mengendalikan mereka.",
  ui_story_5043_50431501_13_dialog_content = "Setelah interogasi yang panjang, serta pencarian lengkap di ruang bawah tanah, Balai Kehakiman sampai pada kesimpulan yang tidak terduga.",
  ui_story_5043_50431501_14_dialog_content = "Schwab berhasil menjinakkan Eclipsites dengan metode yang tidak seperti yang digunakan untuk pelatihan hewan.",
  ui_story_5043_50431501_15_dialog_content = "Dia menjinakkan mereka?!?",
  ui_story_5043_50431501_16_dialog_content = "Bisakah Eclipsites benar-benar dilatih seperti itu ?!",
  ui_story_5043_50431501_17_dialog_content = "Jika Anda memikirkannya, gagasan itu tidak sepenuhnya berada di luar bidang kemungkinan.",
  ui_story_5043_50431501_18_dialog_content = "Kami Aurorian telah melihat Eclipsites sebagai musuh bebuyutan kami selama beberapa generasi. Secara alami, kami memiliki bias yang kuat terhadap mereka.",
  ui_story_5043_50431501_19_dialog_content = "Tapi begitu Anda mengesampingkan sejarah antara spesies kita, Anda dapat melihat bahwa Eclipsites hanyalah makhluk dengan kecerdasan yang lebih rendah.",
  ui_story_5043_50431501_20_dialog_content = "Mereka memiliki kebutuhan dan perilaku mereka sendiri dan tidak berbeda dengan hewan lainnya.",
  ui_story_5043_50431501_21_dialog_content = "Dengan mempertimbangkan kebiasaan dan karakteristik makhluk, dapat dilatih untuk memahami bahwa mengikuti perintah mengarah pada hasil yang positif. Itulah logika di balik penjinakan binatang buas, bukan?",
  ui_story_5043_50431501_22_dialog_content = "Yang dilakukan Schwab hanyalah menjinakkan mereka sampai batas tertentu, seperti yang dilakukan nenek moyang kita dengan serigala dan hewan lainnya.",
  ui_story_5043_50431501_23_dialog_content = "Oh, begitu…",
  ui_story_5043_50431501_24_dialog_content = "Masuk akal, tapi saya masih berpikir itu agak sulit dipercaya.",
  ui_story_5043_50431501_25_dialog_content = "Banyak detail dalam kasus ini memberikan kredibilitas pada kesimpulannya.",
  ui_story_5043_50431501_26_dialog_content = "Schwab selalu meremehkan jenisnya sendiri, tapi anehnya, dia menunjukkan kedekatan yang kuat dengan hewan kecil.",
  ui_story_5043_50431501_27_dialog_content = "Baginya untuk melakukan upaya yang luar biasa untuk rencananya, itu juga akan membutuhkan kesabaran yang luar biasa.",
  ui_story_5043_50431501_28_dialog_content = "Ketika Anda mengatakannya seperti itu, dia tidak terdengar terlalu buruk, setidaknya tidak dari sudut pandang seorang Aurorian.",
  ui_story_5043_50431501_29_dialog_content = "Oh, tunggu dulu, aku bukan Aurorian...",
  ui_story_5043_50431501_30_dialog_content = "Baiklah, saya pikir kita bisa menyimpan sisa diskusi ini untuk nanti.",
  ui_story_5043_50431501_31_dialog_content = "Persidangan Schwab akan segera dimulai.",
  ui_story_5043_50431501_32_dialog_content = "Terdakwa, Schwab Salar, dituduh memanipulasi Eclipsites untuk melakukan penghancuran tiga patung.",
  ui_story_5043_50431501_33_dialog_content = "Hall of Justice telah menyelidiki masalah ini secara menyeluruh, dan bukti yang diperoleh menguatkan tuduhan tersebut di atas.",
  ui_story_5043_50431501_34_dialog_content = "Apakah Anda memiliki sesuatu untuk dikatakan dalam pembelaan Anda, Schwab Salar?",
  ui_story_5043_50431501_35_dialog_content = "...",
  ui_story_5043_50431501_36_dialog_content = "(Dia dulu bertingkah sangat tinggi dan perkasa sebelumnya, tapi sekarang dia terlihat sangat malu pada dirinya sendiri.)",
  ui_story_5043_50431501_37_dialog_content = "Penyelidikan juga menyimpulkan bahwa terlepas dari perilaku terdakwa yang melanggar hukum, tidak ada kerusakan serius yang terjadi pada kota Lumopolis atau penduduknya.",
  ui_story_5043_50431501_38_dialog_content = "Selain itu, mengingat usia terdakwa yang relatif muda, pengadilan berkeyakinan bahwa terdakwa masih dapat memperbaiki perbuatannya. Dengan demikian, pengadilan tidak akan menjatuhkan hukuman penjara kepada terdakwa.",
  ui_story_5043_50431501_39_dialog_content = "Oh? Jadi saya tidak akan masuk penjara.",
  ui_story_5043_50431501_40_dialog_content = "Masuk akal. Merepotkan dia, tindakan Schwab tidak lebih dari vandalisme yang salah arah.",
  ui_story_5043_50431501_41_dialog_content = "Mengingat tingkat kerusakan yang kecil, tidak ada alasan untuk mengirimnya ke penjara karena kejahatannya.",
  ui_story_5043_50431501_42_dialog_content = "Namun demikian, pembebasan dari hukuman penjara tidak berarti pembebasan penuh dari semua konsekuensi hukum.",
  ui_story_5043_50431501_43_dialog_content = "Terdakwa, serta Keluarga Salar, harus menanggung setiap dan semua beban keuangan yang ditimbulkan oleh kasus ini.",
  ui_story_5043_50431501_44_dialog_content = "Gaji Anda sebagai hakim di Hall of Justice juga akan dipotong sepenuhnya.",
  ui_story_5043_50431501_45_dialog_content = "Tentu saja. Saya menerima hukuman saya tanpa pertanyaan.",
  ui_story_5043_50431501_46_dialog_content = "Kenapa dia terlihat sangat tenang sekarang?",
  ui_story_5043_50431501_47_dialog_content = "Uang adalah hal yang paling tidak penting di dunia bagi pria seperti dia.",
  ui_story_5043_50431501_48_dialog_content = "Jika itu masalahnya, bukankah menurutmu hukumannya terlalu ringan?",
  ui_story_5043_50431501_49_dialog_content = "Secara alami, ini hanya setengah dari kalimat Anda.",
  ui_story_5043_50431501_50_dialog_content = "Setelah menganalisis peristiwa yang mengarah ke insiden ini, Dewan Kehakiman menyimpulkan bahwa perilaku ekstrem Schwab Salar dihasilkan dari kegagalan dalam sistem pendidikan aristokrasi.",
  ui_story_5043_50431501_51_dialog_content = "Oleh karena itu, untuk memperbaiki kegagalan tersebut, pengadilan menjatuhkan hukuman kepada Schwab Salar untuk pendidikan ulang di tempat studi sebelumnya.",
  ui_story_5043_50431501_52_dialog_content = "Apa...? Maksudmu aku harus kembali ke Dawn Akademi dan ulangi kelasku?!",
  ui_story_5043_50431501_53_dialog_content = "Berkolusi dengan Eclipsites adalah kejahatan serius dan harus ditindak tegas.",
  ui_story_5043_50431501_X53_dialog_content = "Pengadilan telah memutuskan bahwa pelaku, Schwab, membutuhkan bimbingan baru dari Dewa Cahaya.",
  ui_story_5043_50431501_54_dialog_content = "Untuk menerima panduan ini, Anda telah ditugaskan ke <color=#FFB400>kuil tempat biarawati dilatih</color>.",
  ui_story_5043_50431501_55_dialog_content = "N-Biarawati?!?",
  ui_story_5043_50431501_56_dialog_content = "Ini... Ini keterlaluan, Yang Mulia!!!",
  ui_story_5043_50431501_57_dialog_content = "Izinkan saya untuk memperkenalkan instruktur baru Anda. May pendidikan ulang Anda berjalan lancar, Schwab Salar.",
  ui_story_5043_50431501_58_dialog_content = "Kita bertemu lagi, Tn. Schwab.",
  ui_story_5043_50431501_59_dialog_content = "Itu kamu! Itu hanya berarti, ini adalah idemu, bukan?!",
  ui_story_5043_50431501_60_dialog_content = "Kami memiliki kurikulum menarik yang direncanakan hanya untuk Anda. Selain pelajaran teologi harian Anda, akan ada pelajaran menjahit, memasak, dan melayani yang kurang beruntung...",
  ui_story_5043_50431501_61_dialog_content = "Saya merasa terhormat memiliki hak istimewa untuk membimbing studi Anda selama beberapa tahun ke depan.",
  ui_story_5043_50431501_62_dialog_content = "Tidak, tidak!!! Saya menolak untuk dididik di tempat yang dijalankan sepenuhnya oleh wanita!!!",
  ui_story_5043_50431501_63_dialog_content = "Tampaknya nilai-nilai sosial Anda juga membutuhkan pendidikan ulang.",
  ui_story_5043_50431501_64_dialog_content = "Bawa dia ke biara, dan persiapkan dia untuk kehidupan belajar dan refleksi barunya.",
  ui_story_5043_50431501_65_dialog_content = "Selain Schwab, ada pihak lain dalam kasus ini yang perlu ditegur.",
  ui_story_5043_50431501_66_dialog_content = "Hakim Leyn.",
  ui_story_5043_50431501_67_dialog_content = "Ya, Yang Mulia!",
  ui_story_5043_50431501_68_dialog_content = "Anda dituduh membobol Salar Manor. Apakah Anda mengakui kejahatan ini?",
  ui_story_5043_50431501_69_dialog_content = "Ya, aku suka.",
  ui_story_5043_50431501_70_dialog_content = "(Saya pikir dia tidak akan berbohong kepada ketua hakim...)",
  ui_story_5043_50431501_71_dialog_content = "Sangat baik. Dengan otoritas Balai Kehakiman, dan sesuai dengan Pasal 127 Kode Etik Hakim...",
  ui_story_5043_50431501_72_dialog_content = "Nilai kinerja bulanan Anda akan disetel ulang menjadi nol, dan gaji Anda untuk bulan ini akan dikurangi menjadi tingkat gaji minimum yang diizinkan sebagai pegawai negeri Lumopolis.",
  ui_story_5043_50431501_73_dialog_content = "aku mengerti...",
  ui_story_5043_50431501_74_dialog_content = "(Dia mengatakan itu, tapi saya pikir itu adalah hukuman paling menyakitkan yang bisa dia berikan!)",
  ui_story_5043_50431501_75_dialog_content = "Nah, sekarang, sungguh... Saya sama bersalahnya atas kejahatan ini, Yang Mulia!",
  ui_story_5043_50431501_76_dialog_content = "Saya bersamanya saat itu, jadi saya yakin hukuman ini harus dibagi antara kita berdua.",
  ui_story_5043_50431501_77_dialog_content = "Begitukah, Hakim Matthieu?",
  ui_story_5043_50431501_78_dialog_content = "A-aku juga ada di sana! Jangan lupakan aku!",
  ui_story_5043_50431501_79_dialog_content = "Saya harus mengatakan, kesediaan Anda untuk mengakui kesalahan Anda cukup menyegarkan. Baiklah kalau begitu! Selain gaji Hakim Matthieu yang dipotong untuk bulan ini...",
  ui_story_5043_50431501_80_dialog_content = "Saya menghukum kalian bertiga untuk menyapu halaman di luar Hall of Justice nanti.",
  ui_story_5043_50431501_81_dialog_content = "Melihat semua bunga mati itu sangat tidak menyenangkan.",
  ui_story_5043_50431501_82_dialog_content = "Hukuman macam apa ini??",
  ui_story_5043_50431501_83_dialog_content = "Apakah Anda ingin saya mempertimbangkan kembali?",
  ui_story_5043_50431501_84_dialog_content = "T-Tidak terima kasih, Yang Mulia! Kami lebih dari bersedia untuk menyetujui!",
  ui_story_5043_50431501_85_dialog_content = "Bagus. Itu hanya menyisakan satu putusan akhir untuk disahkan.",
  ui_story_5043_50431501_86_dialog_content = "Apakah saksi, Toto, mohon datang ke stand?",
  ui_story_5043_50431501_87_dialog_content = "Aku di sini, Yang Mulia!",
  ui_story_5043_50431501_88_dialog_content = "Oh, Toto!",
  ui_story_5043_50431501_89_dialog_content = "(Whoa! Kapan Toto mendapatkan pakaian itu?)",
  ui_story_5043_50431501_90_dialog_content = "(Tampaknya sangat halus. Dia menyatu sempurna dengan Lumopolis lainnya!)",
  ui_story_5043_50431501_91_dialog_content = "Sebagai korban dalam kasus ini, Anda tetap bersedia membantu Aurorian dalam mengejar keadilan. Untuk itu, saya harus memuji Anda.",
  ui_story_5043_50431501_92_dialog_content = "Namun, kejahatan sumpah palsu tidak ditoleransi dengan mudah di sini di Hall of Justice.",
  ui_story_5043_50431501_93_dialog_content = "Sebagai kaki tangan dalam strategi Hakim Leyn, Anda sama-sama bersalah atas pelanggaran ini.",
  ui_story_5043_50431501_94_dialog_content = "aku... aku mengerti...",
  ui_story_5043_50431501_95_dialog_content = "Sebagai hakim ketua, hukumanmu adalah—",
  ui_story_5043_50431501_96_dialog_content = "... minta maaf kepada Schwab.",
  ui_story_5043_50431501_97_dialog_content = "Uh... Apa?",
  ui_story_5043_50431501_98_dialog_content = "K-Kau ingin kami meminta maaf? Itu saja?",
  ui_story_5043_50431501_99_dialog_content = "Tindakan sumpah palsu Anda juga merupakan penghinaan terhadap kehormatannya sebagai hakim di Balai Kehakiman, jadi ingatlah untuk menunjukkan setidaknya sedikit ketulusan saat Anda meminta maaf.",
  ui_story_5043_50431501_100_dialog_content = "Dan dengan itu, semua hukuman terkait kasus ini telah ditiadakan.",
  ui_story_5043_50431501_101_dialog_content = "Kasus Pemenggalan Patung Serial sekarang ditutup! Pengadilan ditunda!",
  ui_story_5043_50431501_102_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5043_50431501_103_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian...</color>",
  ui_story_5043_50431501_104_dialog_content = "Ahem, ini detail perjalanan saya di Longzhou beberapa bulan lalu.",
  ui_story_5043_50431501_105_dialog_content = "Sangat bagus. Terima kasih, PlayerName.",
  ui_story_5043_50431501_106_dialog_content = "Sementara keseimbangan kekuatan bergeser di dunia sekitar kita, sikap Lumopolis tidak akan pernah berubah.",
  ui_story_5043_50431501_107_dialog_content = "Saya berdoa agar Eraveil terus menjaga hubungan persahabatan dengan kota adil kita.",
  ui_story_5043_50431501_108_dialog_content = "Saya berdoa agar Anda juga merasakan hal yang sama, teman muda saya.",
  ui_story_5043_50431501_109_dialog_content = "T-Tentu saja, Tuhan Schwartz! Saya selalu senang membantu dalam hal berdamai dengan orang lain!",
  ui_story_5043_50431501_110_dialog_content = "Saya senang mendengarnya.",
  ui_story_5043_50431501_111_dialog_content = "(Fiuh... Senang akhirnya berakhir!)",
  ui_story_5043_50431501_112_dialog_content = "Anda tahu, Anda bisa menjadi diplomat ketika Anda memikirkannya, PlayerName.",
  ui_story_5043_50431501_113_dialog_content = "Hehehehe, menurutmu begitu? Sejujurnya, saya masih merasa sedikit gugup.",
  ui_story_5043_50431501_114_dialog_content = "Ini mengakhiri pertemuan kita hari ini. Apakah ada pertanyaan lebih lanjut?",
  ui_story_5043_50431501_115_dialog_content = "Hall of Justice tidak punya apa-apa lagi untuk dilaporkan.",
  ui_story_5043_50431501_116_dialog_content = "Adipati Otto?",
  ui_story_5043_50431501_117_dialog_content = "Hmph, kakiku mulai lelah karena terlalu banyak duduk.",
  ui_story_5043_50431501_118_dialog_content = "Baiklah kalau begitu. Terima kasih sekali lagi. Anda bebas untuk pergi sekarang.",
  ui_story_5043_50431501_119_dialog_content = "(Belum, ada satu hal terakhir yang perlu saya kemukakan sementara perwakilan Balai Kehakiman dan Dewan Tetua masih ada di sini.)",
  ui_story_5043_50431501_120_dialog_content = "(Selain Eclipsites dan kerumunan orang yang tidak terkendali, pihak lain di Lumopolis baru-baru ini telah menyebarkan perselisihan.)",
  ui_story_5043_50431501_121_dialog_content = "(Sebagai Kapten Penjaga Taman Lumopolis, saya memiliki kewajiban untuk memberi tahu Dewan Tetua!)",
  ui_story_5043_50431501_122_dialog_content = "Ayah, Adipati Otto... Mohon waktu Anda sebentar.",
  ui_story_5043_50431501_123_dialog_content = "Saya harus mengatakan, Tuhan Schwartz, Taman Lumopolis telah menangani semua keadaan darurat baru-baru ini dengan cukup efektif.",
  ui_story_5043_50431501_124_dialog_content = "Saya cukup terkejut melihat seberapa baik mereka bekerja dengan orang Lumopolis.",
  ui_story_5043_50431501_125_dialog_content = "Haha, pujianmu terlalu murah hati, Duke Otto. Secara alami, kami berhutang banyak atas kesuksesan kami atas dukungan Dewan Tetua.",
  ui_story_5043_50431501_126_dialog_content = "Tanpa bantuanmu dalam perang melawan Eclipsites, Pengawal Taman Lumopolis tidak akan mampu memenuhi kebutuhan kota kita.",
  ui_story_5043_50431501_127_dialog_content = "Apa itu, Carleen?",
  ui_story_5043_50431501_128_dialog_content = "...",
  ui_story_5043_50431501_129_dialog_content = "Ah, jangan katakan lagi, Nyonya. Saya tidak ingin mengganggu percakapan antara ayah dan anak. Selamat tinggal.",
  ui_story_5043_50431501_130_dialog_content = "Tuanku, saya kira Anda mengetahui apa yang dilakukan penjaga Dewan Tetua selama Hari Mahkota Bulan, ya?",
  ui_story_5043_50431501_131_dialog_content = "Jauh lebih sadar daripada yang Anda pikirkan, Carleen.",
  ui_story_5043_50431501_132_dialog_content = "Di tahun lalu, Anda telah menunjukkan diri Anda lebih tenang dan lebih berani dari sebelumnya.",
  ui_story_5043_50431501_133_dialog_content = "Namun, menangani masalah politik seperti ini membutuhkan lebih dari sekadar keberanian.",
  ui_story_5043_50431501_134_dialog_content = "Ketika pekerjaan saya saat ini selesai, saya akan mengatur waktu liburan untuk diberikan kepada semua orang di Taman Lumopolis.",
  ui_story_5043_50431501_135_dialog_content = "Itu tidak perlu, tapi terima kasih, Ayah.",
  ui_story_5043_50431501_136_dialog_content = "Ayo, PlayerName.",
  ui_story_5043_50431501_137_dialog_content = "<color=#e8d9bb>Pop! Pop! Pop!</color>",
  ui_story_5043_50431501_138_dialog_content = "Selamat atas laporan kerja yang sukses, PlayerName!!!",
  ui_story_5043_50431501_139_dialog_content = "Kami mengetahuinya saat kami melihat Hakim Ketua Irridon berjalan keluar dari ruang konferensi!",
  ui_story_5043_50431501_140_dialog_content = "Petasan ini tersisa sejak diberikan kepada Byron untuk patungnya.",
  ui_story_5043_50431501_141_dialog_content = "Tidak bisa membiarkan mereka sia-sia, kan?",
  ui_story_5043_50431501_142_dialog_content = "Apa masalahnya? Terlalu terkejut untuk berbicara?",
  ui_story_5043_50431501_143_dialog_content = "Bergembiralah, bukan? Itu juga berlaku untukmu, Nona Carleen!",
  ui_story_5043_50431501_144_dialog_content = "Selamat atas pekerjaan yang dilakukan dengan baik, PlayerName.",
  ui_story_5043_50431501_145_dialog_content = "Wow... Terima kasih semuanya!",
  ui_story_5043_50431501_146_dialog_content = "Kalian semua sangat...",
  ui_story_5043_50431501_147_dialog_content = "Sigh, apa yang harus kami lakukan denganmu?",
  ui_story_5043_50431501_148_dialog_content = "Maafkan saya karena merusak kesenangan, semuanya. Namun pekerjaan Balai Kehakiman masih belum selesai.",
  ui_story_5043_50431501_149_dialog_content = "Bantuan Anda juga akan sangat dihargai, Lady Carleen.",
  ui_story_5043_50431501_150_dialog_content = "Hal ini membutuhkan kerja sama seseorang dari Lumopolis Gardens.",
  ui_story_5043_50431501_151_dialog_content = "<color=#e8d9bb>Balai Kehakiman, Taman Lumopolis</color>",
  ui_story_5043_50431501_152_dialog_content = "Aku tahu.",
  ui_story_5043_50431501_153_dialog_content = "Jadi meskipun Divisi Percintaan dibubarkan, banyak kasus yang masih harus diselesaikan.",
  ui_story_5043_50431501_154_dialog_content = "Balai Kehakiman tetap rajin seperti biasanya, Ketua Hakim.",
  ui_story_5043_50431501_155_dialog_content = "Wow, lihat saja semua file ini! Kami akan berada di sini selama berminggu-minggu hanya mencoba membaca semuanya ...",
  ui_story_5043_50431501_156_dialog_content = "Kalau begitu, aku mengandalkan—",
  ui_story_5043_50431501_157_dialog_content = "Kita tahu...",
  ui_story_5043_50431501_158_dialog_content = "Satu hal lagi, Nona Carleen. Sementara kasus-kasus ini mungkin tampak seperti perselisihan sederhana antara sepasang kekasih pada pandangan pertama...",
  ui_story_5043_50431501_159_dialog_content = "Penyelidikan yang lebih dalam tentang isinya dengan cepat mengungkapkan segudang masalah yang memengaruhi Lumopolis pada tingkat fundamental dan sosial.",
  ui_story_5043_50431501_160_dialog_content = "Dengan membacanya, saya mendapatkan wawasan yang luar biasa tentang pemikiran dan motif mereka yang tinggal di Halaman Lumopolis dan Lumopolis Bawah. Itu adalah pengalaman yang belum pernah terjadi sebelumnya bagi saya.",
  ui_story_5043_50431501_161_dialog_content = "Berbagai interpretasi mereka tentang cinta dan iman... Membuatku banyak berpikir.",
  ui_story_5043_50431501_162_dialog_content = "Saya percaya bahwa memahami kasus-kasus ini adalah kunci untuk merevisi undang-undang kami untuk menguntungkan Lumopolis secara keseluruhan.",
  ui_story_5043_50431501_163_dialog_content = "Ketika saat itu tiba, saya berdoa agar Balai Kehakiman mendapat dukungan dari Tuan Kota, serta Anda sendiri.",
  ui_story_5043_50431501_164_dialog_content = "Singkatnya, saya yakin pekerjaan ini penting untuk memastikan masa depan yang cerah dan sejahtera bagi Lumopolis.",
  ui_story_5043_50431501_165_dialog_content = "Baiklah, saya setuju dengan permintaan Anda.",
  ui_story_5043_50431501_166_dialog_content = "Lagipula, Irridon... Anda bukan satu-satunya yang merasakan hal ini.",
  ui_story_5043_50431501_167_dialog_content = "Anda pasti merasa jauh lebih bahagia sekarang, bukan Carleen?",
  ui_story_5043_50431501_168_dialog_content = "Oh? Apakah itu jelas bagi Anda?",
  ui_story_5043_50431501_169_dialog_content = "Sejujurnya, saya agak terkejut betapa cepatnya jalanan kembali normal.",
  ui_story_5043_50431501_170_dialog_content = "Begitu saja, kios dan pawai semuanya hilang, dan bulan tidak lagi melayang di atas kepala.",
  ui_story_5043_50431501_171_dialog_content = "Apakah itu benar-benar mengejutkan Anda, Leyn? Bagaimanapun, kami adalah bangsawan.",
  ui_story_5043_50431501_172_dialog_content = "Waktu dan tren selalu berubah di Lumopolis. Bagaimana mungkin kita membiarkan diri kita tertinggal dalam hal-hal terbaru?",
  ui_story_5043_50431501_173_dialog_content = "Lihat sendiri!",
  ui_story_5043_50431501_174_dialog_content = "Hah? Bukankah sarung tangan itu sama dengan milikku?",
  ui_story_5043_50431501_175_dialog_content = "Ya, tapi mereka baru-baru ini menjadi fashion item terpanas di pasaran. Anggota bangsawan sudah terlihat mengenakannya ke berbagai acara sosial.",
  ui_story_5043_50431501_176_dialog_content = "Mereka agak terlalu kental untuk selera saya, tapi itu tidak menghentikan saya untuk membeli tujuh pasang!",
  ui_story_5043_50431501_177_dialog_content = "Betapa konyolnya sembrono.",
  ui_story_5043_50431501_178_dialog_content = "Persis seperti yang kau harapkan dari anak orang kaya...",
  ui_story_5043_50431501_179_dialog_content = "Hmph! Abaikan orang filistin ini, Tina. Katakan padaku, bagaimana rasanya menjadi trendsetter mode terbaru Lumopolis?",
  ui_story_5043_50431501_180_dialog_content = "Oh, dan bagaimana dengan Toto? Apakah Anda sudah menemukan cara untuk mempertahankannya?",
  ui_story_5043_50431501_181_dialog_content = "Sesuatu seperti itu akan menjadi hal yang tabu di sini di Lumopolis... Tapi itulah yang membuatnya semakin menarik, bukan?",
  ui_story_5043_50431501_182_dialog_content = "A-Sebenarnya, semuanya... Aku meminta Toto untuk menemuiku di sini hari ini.",
  ui_story_5043_50431501_183_dialog_content = "Dengan cara itu, saya bisa mengatakan <color=#FFB400>selamat tinggal</color> untuk dia.",
  ui_story_5043_50431501_184_dialog_content = "Apa?!",
  ui_story_5043_50431501_185_dialog_content = "Tapi kenapa secepat ini? Aku tidak tahu kebaikanmu terhadapnya bisa berumur pendek!",
  ui_story_5043_50431501_186_dialog_content = "I-Bukan itu! Jika ada, itu justru karena saya sangat peduli pada si kecil yang manis!",
  ui_story_5043_50431501_187_dialog_content = "Eclipsites telah ditakuti dan dibenci selama yang bisa diingat siapa pun, tetapi Toto tidak seperti yang lain!",
  ui_story_5043_50431501_188_dialog_content = "Meski begitu, tidak semua orang mau melihat hal-hal seperti ini, apalagi menerimanya.",
  ui_story_5043_50431501_189_dialog_content = "Jika saya bersikeras untuk tinggal di sini di Lumopolis bersamanya, itu akan membuat hidup lebih sulit baginya.",
  ui_story_5043_50431501_190_dialog_content = "Saya yakin dia lebih takut daripada senang di bulan terakhir tinggal di sini.",
  ui_story_5043_50431501_191_dialog_content = "…Hah?",
  ui_story_5043_50431501_192_dialog_content = "Um…",
  ui_story_5043_50431501_193_dialog_content = "Kenapa kamu bersembunyi di sana, Toto? Kemarilah!",
  ui_story_5043_50431501_194_dialog_content = "K-Kalian semua ada di sini...",
  ui_story_5043_50431501_X194_dialog_content = "Kamu mengganti pakaianmu!?",
  ui_story_5043_50431501_X195_dialog_content = "Anda terlihat sangat halus, menyatu sempurna dengan Lumopolis lainnya!",
  ui_story_5043_50431501_X196_dialog_content = "Benar... Lagipula hari ini adalah hari yang penting, jadi aku ingin berpakaian untuk acara ini.",
  ui_story_5043_50431501_195_dialog_content = "Sebenarnya, saya datang untuk mengucapkan selamat tinggal juga.",
  ui_story_5043_50431501_196_dialog_content = "Jadi, Anda berencana untuk melakukan perjalanan lagi, ya?",
  ui_story_5043_50431501_197_dialog_content = "I-Itu benar, tapi tidak seperti yang kau pikirkan.",
  ui_story_5043_50431501_198_dialog_content = "Beberapa hari terakhir saya di Lumopolis penuh dengan bahaya dan teror.",
  ui_story_5043_50431501_199_dialog_content = "Tapi itu juga merupakan hari-hari terindah dalam hidupku.",
  ui_story_5043_50431501_200_dialog_content = "Itu karena aku bertemu kalian semua.",
  ui_story_5043_50431501_201_dialog_content = "K-Terutama kamu, Tina.",
  ui_story_5043_50431501_202_dialog_content = "Terima kasih, Toto.",
  ui_story_5043_50431501_203_dialog_content = "K-Kamu adalah Aurorian pertama yang pernah menunjukkan kebaikan tanpa syarat.",
  ui_story_5043_50431501_204_dialog_content = "I-Itu adalah sesuatu yang akan aku hargai selama sisa hidupku.",
  ui_story_5043_50431501_205_dialog_content = "(Kebaikan tanpa syarat, ya...)",
  ui_story_5043_50431501_206_dialog_content = "(Saya tahu bagaimana perasaannya. Itu benar-benar sesuatu yang berharga.)",
  ui_story_5043_50431501_207_dialog_content = "... Semoga sukses dalam perjalanan Anda, Toto.",
  ui_story_5043_50431501_208_dialog_content = "Semoga suatu saat kita bisa bertemu lagi, kawan.",
  ui_story_5043_50431501_209_dialog_content = "Oh tunggu! Sebelum kau pergi, aku punya sesuatu yang selalu ingin kuberikan padamu.",
  ui_story_5043_50431501_210_dialog_content = "Di sini, ini adalah kumpulan kue yang baru dipanggang. Jalan di depan Anda pasti akan panjang. Jadi semoga ini membuat perjalanan Anda sedikit lebih mudah!",
  ui_story_5043_50431501_211_dialog_content = "Sniff... T-Terima kasih... Terima kasih banyak, Tina...",
  ui_story_5043_50431501_212_dialog_content = "Aku akan menghargai semuanya!!!",
  ui_story_5043_50431501_213_dialog_content = "Ha ha ha ha! Hanya saja, jangan terlalu menghargai mereka, oke? Bagaimanapun, mereka dimaksudkan untuk makan!",
  ui_story_5043_50431501_214_dialog_content = "Anda harus pergi sekarang.",
  ui_story_5043_50431501_215_dialog_content = "Matahari mungkin tidak pernah terbenam di Lumopolis, tetapi belum tentu demikian halnya dengan seluruh dunia.",
  ui_story_5043_50431501_216_dialog_content = "B-Baik, kalau begitu... Aku akan pergi sekarang!",
  ui_story_5043_50431501_217_dialog_content = "Selamat tinggal semuanya!!!",
  ui_story_5043_50431501_218_dialog_content = "Sampai jumpa, Toto!!!",
  ui_story_5043_50431501_219_dialog_content = "Jadi, pahlawan kecil kita berangkat sekali lagi! ♪",
  ui_story_5043_50431501_220_dialog_content = "Tapi kali ini, dia pergi dengan membawa hadiah dari teman-temannya! ♪",
  ui_story_5043_50431501_221_dialog_content = "Aroma makanan panggang melayang di belakangnya saat dia pergi ♪",
  ui_story_5043_50431501_222_dialog_content = "Dan ke langit Lumopolis dengan angin pagi! ♪"
}
return config
